function normalizeSuperAdminNotificationType(type) {
  return String(type || "notice").trim().toLowerCase() || "notice";
}

function getSuperAdminNotificationCategory(type) {
  const normalized = normalizeSuperAdminNotificationType(type);
  return SA_INBOX_CATEGORY_BY_TYPE[normalized] || "system";
}

function isSuperAdminSelfActionNotification(notification) {
  const type = normalizeSuperAdminNotificationType(notification?.type);
  if (type === "welcome") {
    return false;
  }
  const createdBy = String(notification?.createdBy || "").trim().toLowerCase();
  if (!createdBy) {
    return false;
  }
  const saName = String(SUPER_ADMIN_USERNAME || "super-admin").trim().toLowerCase();
  return (
    createdBy === saName
    || createdBy === "super-admin"
    || createdBy === "superadmin"
    || createdBy === "super admin"
    || createdBy === "root"
  );
}

function isSuperAdminInboxEligible(notification) {
  if (!notification || typeof notification !== "object") {
    return false;
  }
  const audience = String(notification.audience || "super_admin").trim().toLowerCase();
  if (audience && audience !== "super_admin") {
    return false;
  }
  const type = normalizeSuperAdminNotificationType(notification.type);
  if (SA_INBOX_PRIVACY_BLOCKED_TYPES.has(type)) {
    return false;
  }
  if (SA_INBOX_ECHO_TYPES.has(type) || SA_INBOX_NOISE_TYPES.has(type)) {
    return false;
  }
  if (isSuperAdminSelfActionNotification(notification)) {
    return false;
  }
  if (!SA_INBOX_ALLOWED_TYPES.has(type)) {
    return false;
  }
  // Seller-deleted listings stay; SA-deleted listings are suppressed at the fan-out call site.
  return true;
}

function filterSuperAdminInboxNotifications(notifications) {
  const list = Array.isArray(notifications) ? notifications : [];
  return list
    .filter(isSuperAdminInboxEligible)
    .map((entry) => {
      const type = normalizeSuperAdminNotificationType(entry?.type);
      const category = String(entry?.category || getSuperAdminNotificationCategory(type)).trim() || "system";
      return {
        ...entry,
        type,
        category,
        priority: String(entry?.priority || (category === "security" ? "high" : "normal")).trim() || "normal",
      };
    });
}

function createPersistentLinkedNotification(input = {}) {
  const now = String(input.createdAt || new Date().toISOString());
  const type = normalizeSuperAdminNotificationType(input.type);
  const category = String(input.category || getSuperAdminNotificationCategory(type)).trim() || "system";
  const priority = String(
    input.priority || (category === "security" ? "high" : "normal"),
  )
    .trim()
    .toLowerCase() || "normal";
  const actorTypeRaw = String(input.actorType || "").trim().toLowerCase();
  const actorType =
    actorTypeRaw === "user" || actorTypeRaw === "company" || actorTypeRaw === "system"
      ? actorTypeRaw
      : "";
  return {
    id: String(input.id || `sa-notif-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`).trim(),
    type,
    category,
    priority,
    audience: String(input.audience || "super_admin").trim() || "super_admin",
    title: String(input.title || "Notification").replace(/\s+/g, " ").trim().slice(0, 160),
    reason: String(input.reason || "").replace(/\s+/g, " ").trim().slice(0, 500),
    message: String(input.message || "").replace(/\s+/g, " ").trim().slice(0, 500),
    status: "unread",
    read: false,
    productId: String(input.productId || "").trim(),
    productName: String(input.productName || "").trim(),
    feedbackId: String(input.feedbackId || "").trim(),
    adminId: String(input.adminId || "").trim(),
    companyId: String(input.companyId || "").trim(),
    companyName: String(input.companyName || "").trim(),
    storeName: String(input.storeName || "").trim(),
    businessName: String(input.businessName || "").trim(),
    companyPictureUrl: String(input.companyPictureUrl || "").trim(),
    actorType,
    userId: String(input.userId || "").trim(),
    username: String(input.username || "").trim(),
    userDisplayName: String(input.userDisplayName || "").trim(),
    profileImageUrl: String(input.profileImageUrl || "").trim(),
    createdBy: String(input.createdBy || "").trim(),
    targetUrl: String(input.targetUrl || "").trim(),
    createdAt: now,
  };
}

function formatSaNotificationUserLabel(account = {}, fallback = "User") {
  const fullName = [account?.firstName, account?.lastName].filter(Boolean).join(" ").trim();
  return String(
    account?.username
    || account?.userDisplayName
    || account?.displayName
    || account?.fullName
    || fullName
    || (String(account?.email || "").includes("@")
      ? String(account.email).split("@")[0]
      : account?.email)
    || fallback,
  )
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 160) || fallback;
}

async function resolveSaNotificationUserActor({
  accountId = "",
  account = null,
  payload = {},
  fallback = "User",
} = {}) {
  const id = String(
    accountId
    || account?.id
    || account?.accountId
    || payload?.accountId
    || "",
  ).trim();
  let record = account && typeof account === "object" ? { ...account } : {};
  if (id && typeof findCustomerById === "function") {
    try {
      const customer = await findCustomerById(id);
      if (customer && typeof customer === "object") {
        record = { ...record, ...customer };
      }
    } catch (_) {
      // Keep session/hint fields when customer lookup is unavailable.
    }
  }
  const username = formatSaNotificationUserLabel(record, fallback);
  return {
    actorType: "user",
    userId: id || String(record?.id || record?.accountId || "").trim(),
    username,
    userDisplayName: username,
    profileImageUrl: String(
      record?.profileImageUrl
      || record?.avatarUrl
      || record?.photoUrl
      || "",
    ).trim(),
    createdBy: username,
  };
}

function resolveSaNotificationCompanyActor({
  adminId = "",
  companyId = "",
  companyName = "",
  storeName = "",
  businessName = "",
  companyPictureUrl = "",
  createdBy = "",
} = {}) {
  const name = String(
    companyName || storeName || businessName || createdBy || "Company",
  )
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 160) || "Company";
  return {
    actorType: "company",
    adminId: String(adminId || "").trim(),
    companyId: String(companyId || "").trim(),
    companyName: name,
    storeName: String(storeName || name).trim() || name,
    businessName: String(businessName || name).trim() || name,
    companyPictureUrl: String(companyPictureUrl || "").trim(),
    createdBy: name,
  };
}

async function readSuperAdminNotifications() {
  await ensureStoragePaths();
  try {
    const raw = await fsPromises.readFile(SUPER_ADMIN_NOTIFICATIONS_FILE, "utf8");
    const decoded = JSON.parse(raw);
    return Array.isArray(decoded) ? decoded : [];
  } catch (_) {
    return [];
  }
}

const SUPER_ADMIN_WELCOME_NOTIFICATION_ID = "sa-notif-welcome";

function createSuperAdminWelcomeNotification(createdAt = new Date().toISOString()) {
  return createPersistentLinkedNotification({
    id: SUPER_ADMIN_WELCOME_NOTIFICATION_ID,
    type: "welcome",
    audience: "super_admin",
    title: "Welcome to Switch Super Admin",
    reason: "Workspace ready",
    message:
      "Marketplace command center ready. Seller onboarding, listing reviews, KYC, bans, and platform feedback land here — private buyer↔seller chats stay out.",
    targetUrl: "/super_admin.html#dashboard",
    createdAt,
    createdBy: SUPER_ADMIN_USERNAME,
  });
}

async function ensureSuperAdminWelcomeNotification(notifications) {
  const list = Array.isArray(notifications) ? notifications.slice() : [];
  const hasWelcome = list.some((entry) => {
    const id = String(entry?.id || "").trim();
    const type = String(entry?.type || "").trim().toLowerCase();
    return id === SUPER_ADMIN_WELCOME_NOTIFICATION_ID || type === "welcome";
  });
  if (hasWelcome) {
    return list;
  }
  const welcome = createSuperAdminWelcomeNotification();
  const next = appendPersistentNotifications(list, welcome);
  await writeSuperAdminNotifications(next);
  return next;
}

async function writeSuperAdminNotifications(notifications) {
  await writeJsonFileAtomically(
    SUPER_ADMIN_NOTIFICATIONS_FILE,
    Array.isArray(notifications) ? notifications.slice(0, MAX_SUPER_ADMIN_NOTIFICATIONS) : [],
  );
}

async function persistSuperAdminNotification(notification) {
  if (!notification) {
    return null;
  }
  const shaped =
    notification && typeof notification === "object" && notification.type
      ? {
          ...notification,
          type: normalizeSuperAdminNotificationType(notification.type),
          category:
            String(notification.category || getSuperAdminNotificationCategory(notification.type)).trim() ||
            "system",
        }
      : notification;
  if (!isSuperAdminInboxEligible(shaped)) {
    return null;
  }
  const notifications = await readSuperAdminNotifications();
  await writeSuperAdminNotifications(appendPersistentNotifications(notifications, shaped));
  return shaped;
}

function assignSellerAdminNotification(account, notification) {
  if (!account || typeof account !== "object" || !notification) {
    return account;
  }
  const previous = Array.isArray(account.sellerNotifications) ? account.sellerNotifications : [];
  const scopedNotification = {
    ...notification,
    audience: String(notification.audience || "seller").trim() || "seller",
    adminId: String(
      notification.adminId ||
        account.adminId ||
        account.id ||
        "",
    ).trim(),
  };
  account.lastSellerNotification = scopedNotification;
  account.sellerNotifications = appendPersistentNotifications(previous, scopedNotification);
  return account;
}

function resolveSellerOnboardingAdminId(result, payload = {}) {
  return normalizeAdminTenantId(
    result?.account?.id ||
      result?.account?.adminId ||
      payload.accountId ||
      result?.company?.id ||
      "",
    "",
  );
}

async function notifySellerAdminInboxByAdminId(adminId, notification) {
  const normalizedAdminId = normalizeAdminTenantId(adminId, "");
  if (!normalizedAdminId || !notification) {
    return null;
  }

  const accounts = await readAccounts();
  let account = findAdminAccountByScopeId(accounts, normalizedAdminId);
  if (!account) {
    account = accounts.find((entry) =>
      [
        entry?.id,
        entry?.accountId,
        entry?.adminId,
      ]
        .map((value) => normalizeAdminTenantId(value, ""))
        .includes(normalizedAdminId),
    ) || null;
  }
  if (!account) {
    return null;
  }

  assignSellerAdminNotification(account, {
    ...notification,
    adminId: normalizedAdminId,
  });
  await writeAccounts(accounts);
  return notification;
}

function getSellerCompanyDisplayName(account) {
  return [
    account?.companyName,
    account?.storeName,
    account?.businessName,
  ]
    .map((value) => String(value ?? "").trim())
    .find(Boolean) || "Seller";
}

function getSellerAccountDeletionScheduledAt(account) {
  const scheduledAt = new Date(
    account?.deletionScheduledAt ?? account?.accountDeletionScheduledAt ?? "",
  );
  return Number.isFinite(scheduledAt.getTime()) ? scheduledAt : null;
}

function getSellerAccountDeletionStatus(account) {
  const status = String(account?.status ?? account?.accountStatus ?? account?.accountState ?? "")
    .trim()
    .toLowerCase();
  const deletionStatus = String(
    account?.accountDeletionStatus ?? account?.deletionStatus ?? "",
  )
    .trim()
    .toLowerCase();
  if (
    status === "deleted" ||
    deletionStatus === "deleted" ||
    Boolean(account?.accountDeletedAt || account?.deletedAt)
  ) {
    return "deleted";
  }
  if (deletionStatus === "scheduled" || deletionStatus === "pending") {
    const scheduledAt = getSellerAccountDeletionScheduledAt(account);
    if (scheduledAt && scheduledAt.getTime() <= Date.now()) {
      return "due";
    }
    return "scheduled";
  }
  return "";
}

function isSellerAccountDeletionDue(account) {
  return getSellerAccountDeletionStatus(account) === "due";
}

function createSellerDeletionInboxNotification(account, now, options = {}) {
  const companyName = getSellerCompanyDisplayName(account);
  const scheduledAt = getSellerAccountDeletionScheduledAt(account);
  const scheduledLabel = scheduledAt
    ? scheduledAt.toLocaleString()
    : "the scheduled date";
  const type = String(options.type || "seller-account-deletion").trim();
  const isCancel = type === "seller-account-deletion-canceled";
  return {
    id: `seller-account-deletion-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    type,
    audience: "seller",
    title: isCancel ? "Account deletion canceled" : "Account deletion scheduled",
    reason: isCancel ? "Seller canceled account deletion" : "Seller requested account deletion",
    message: isCancel
      ? `Account deletion for ${companyName} was canceled. Your seller workspace stays active.`
      : `Your seller account is scheduled for permanent deletion on ${scheduledLabel}. You have 30 days to cancel from Account Settings.`,
    status: "unread",
    createdAt: now,
    createdBy: options.createdBy || "Seller Admin",
    targetUrl: "/main.html#account-settings",
    deletionScheduledAt: account?.deletionScheduledAt || null,
  };
}

function createActivityFromSellerNotification(notification, adminId) {
  if (!notification || typeof notification !== "object") {
    return null;
  }
  const createdAt = String(notification.createdAt || notification.notifiedAt || "").trim();
  if (!createdAt) {
    return null;
  }
  const scopedAdminId = normalizeAdminTenantId(
    notification.adminId || adminId,
    "",
  );
  if (!scopedAdminId) {
    return null;
  }
  return {
    id: String(notification.id || `seller-inbox-${scopedAdminId}-${createdAt}`).trim(),
    type: String(notification.type || "seller-notification").trim() || "seller-notification",
    action: String(notification.type || "notice").trim() || "notice",
    source: "super_admin",
    notificationAudience: "admin",
    adminId: scopedAdminId,
    title: String(notification.title || "Seller notice").trim() || "Seller notice",
    description: String(notification.message || notification.reason || "Seller notice recorded.").trim(),
    createdAt,
    targetUrl: String(notification.targetUrl || "").trim(),
    actor: {
      role: "admin",
      accountId: "super-admin",
      displayName: SUPER_ADMIN_USERNAME,
    },
  };
}

async function verifySellerAccountPassword(account, password) {
  const submitted = String(password ?? "");
  if (!submitted || !account) {
    return false;
  }
  if (await isSellerPostgresReady()) {
    const seller = await findSellerByAdminId(account.adminId || account.id);
    if (seller?._passwordHash) {
      return verifyPassword(submitted, seller._passwordHash);
    }
  }
  return verifyPassword(submitted, account.password);
}

function applyScheduledSellerAccountDeletion(account, now, requestedBy = "seller-admin") {
  const requestedAt = now;
  const scheduledAt = new Date(Date.parse(now) + SELLER_ACCOUNT_DELETION_GRACE_MS).toISOString();
  Object.assign(account, {
    accountDeletionStatus: "scheduled",
    deletionStatus: "scheduled",
    deletionRequestedAt: requestedAt,
    accountDeletionRequestedAt: requestedAt,
    deletionScheduledAt: scheduledAt,
    accountDeletionScheduledAt: scheduledAt,
    deletionRequestedBy: requestedBy,
    deletionCanceledAt: null,
    accountDeletionCanceledAt: null,
    updatedAt: now,
  });
  return account;
}

function clearScheduledSellerAccountDeletion(account, now) {
  Object.assign(account, {
    accountDeletionStatus: "",
    deletionStatus: "",
    deletionRequestedAt: null,
    accountDeletionRequestedAt: null,
    deletionScheduledAt: null,
    accountDeletionScheduledAt: null,
    deletionRequestedBy: "",
    deletionCanceledAt: now,
    accountDeletionCanceledAt: now,
    updatedAt: now,
  });
  return account;
}

function applyFinalizedSellerAccountDeletion(account, now) {
  const accountId = String(account?.id || account?.adminId || "seller").trim();
  const companyName = getSellerCompanyDisplayName(account);
  Object.assign(account, {
    status: "deleted",
    accountStatus: "deleted",
    accountState: "deleted",
    accountDeletionStatus: "deleted",
    deletionStatus: "deleted",
    isActive: false,
    disabled: true,
    isOnline: false,
    online: false,
    loggedIn: false,
    isLoggedIn: false,
    sessionActive: false,
    presenceStatus: "offline",
    email: `deleted.${accountId.replace(/[^a-z0-9]/gi, "").slice(0, 18) || "seller"}.${Date.now()}@deleted.switch.invalid`,
    mobileNumber: "",
    googleProfile: null,
    accountDeletedAt: now,
    deletedAt: now,
    updatedAt: now,
    companyName,
    storeName: String(account?.storeName || companyName).trim() || companyName,
    planStatus: "canceled",
  });
  delete account.password;
  return account;
}

async function deactivateDeletedSellerWorkspace(adminId, now) {
  const normalizedAdminId = normalizeAdminTenantId(adminId, "");
  if (!normalizedAdminId) {
    return;
  }

  try {
    const products = await readProducts();
    let didChangeProducts = false;
    const nextProducts = products.map((product) => {
      if (!isRecordInAdminScope(product, normalizedAdminId) || product?.isActive === false) {
        return product;
      }
      didChangeProducts = true;
      return {
        ...product,
        isActive: false,
        hiddenWithSellerDeletion: true,
        sellerDeletedAt: now,
        updatedAt: now,
      };
    });
    if (didChangeProducts) {
      await writeProducts(nextProducts);
    }
  } catch (error) {
    console.error("Unable to hide listings for deleted seller account:", error);
  }
}

async function deactivateBannedSellerListings(adminId, {
  companyId = "",
  now = new Date().toISOString(),
} = {}) {
  const normalizedAdminId = normalizeAdminTenantId(adminId, "");
  if (!normalizedAdminId) {
    return { changed: 0 };
  }

  try {
    const products = await readProducts();
    const normalizedCompanyId = String(companyId || "").trim();
    let changed = 0;
    const nextProducts = products.map((product) => {
      if (!isRecordInAdminScope(product, normalizedAdminId)) {
        return product;
      }
      const productCompanyId = String(product?.companyId || product?.company_id || "").trim();
      if (normalizedCompanyId && productCompanyId && productCompanyId !== normalizedCompanyId) {
        return product;
      }
      const alreadyHidden =
        product?.isActive === false &&
        (product?.hiddenWithCompanyBan === true || product?.companyIsBanned === true);
      if (alreadyHidden) {
        return product;
      }
      changed += 1;
      return {
        ...product,
        isActive: false,
        hiddenWithCompanyBan: true,
        companyIsBanned: true,
        companyAccountState: "banned",
        companyBannedAt: now,
        companyBannedCompanyId: normalizedCompanyId || productCompanyId || "",
        updatedAt: now,
      };
    });
    if (changed > 0) {
      await writeProducts(nextProducts);
    }
    return { changed };
  } catch (error) {
    console.error("Unable to hide listings for banned seller company:", error);
    return { changed: 0 };
  }
}

async function reconcileBannedCompanyLiveListings(accounts = []) {
  const bannedAdmins = (Array.isArray(accounts) ? accounts : []).filter(
    (account) => isAdminAccount(account) && isSellerAccountRecordBanned(account),
  );
  if (!bannedAdmins.length) {
    return { changed: 0 };
  }

  try {
    const products = await readProducts();
    const now = new Date().toISOString();
    let changed = 0;
    const nextProducts = products.map((product) => {
      const adminId = getRecordAdminId(product, product?.adminId || "");
      const account = findAdminAccountByScopeId(bannedAdmins, adminId);
      if (!account || !isProductBannedByCompany(product, [account])) {
        return product;
      }
      const alreadyHidden =
        product?.isActive === false &&
        (product?.hiddenWithCompanyBan === true || product?.companyIsBanned === true);
      if (alreadyHidden) {
        return product;
      }
      changed += 1;
      return {
        ...product,
        isActive: false,
        hiddenWithCompanyBan: true,
        companyIsBanned: true,
        companyAccountState: "banned",
        companyBannedAt: now,
        companyBannedCompanyId: String(
          product?.companyId || product?.company_id || account?.companyId || "",
        ).trim(),
        updatedAt: now,
      };
    });
    if (changed > 0) {
      await writeProducts(nextProducts);
    }
    return { changed };
  } catch (error) {
    console.error("Unable to reconcile banned company live listings:", error);
    return { changed: 0 };
  }
}

let sellerDeletionSweepPromise = null;

async function processDueSellerAccountDeletions() {
  if (sellerDeletionSweepPromise) {
    return sellerDeletionSweepPromise;
  }

  sellerDeletionSweepPromise = (async () => {
    const accounts = await readAccounts();
    const now = new Date().toISOString();
    const dueSellers = accounts.filter(
      (account) => isAdminAccount(account) && isSellerAccountDeletionDue(account),
    );
    if (!dueSellers.length) {
      return { processed: 0 };
    }

    const dueAdminIds = new Set(
      dueSellers.map((account) => getRecordAdminId(account, account.adminId || account.id)),
    );

    for (const account of accounts) {
      if (isAdminAccount(account) && dueAdminIds.has(getRecordAdminId(account, account.adminId || account.id))) {
        applyFinalizedSellerAccountDeletion(account, now);
        continue;
      }
      if (
        String(account?.role ?? "").trim().toLowerCase() === "employee" &&
        dueAdminIds.has(getRecordAdminId(account, account.adminId || ""))
      ) {
        Object.assign(account, {
          status: "deactivated",
          accountStatus: "deactivated",
          isActive: false,
          disabled: true,
          sellerAccountDeletedAt: now,
          updatedAt: now,
        });
      }
    }

    await writeAccounts(accounts);

    for (const account of dueSellers) {
      const adminId = getRecordAdminId(account, account.adminId || account.id);
      const companyName = getSellerCompanyDisplayName(account);
      await deactivateDeletedSellerWorkspace(adminId, now);
      if (await isSellerPostgresReady()) {
        try {
          await deleteSellerAuthIdentities(account.id || adminId);
        } catch (error) {
          console.error("Unable to unlink deleted seller identities:", error);
        }
      }
      await persistSuperAdminNotification(
        createPersistentLinkedNotification({
          type: "seller-account-deleted",
          audience: "super_admin",
          title: "Seller account deleted",
          reason: "30-day deletion period ended",
          message: `${companyName} completed the 30-day deletion period and the seller account is now deleted.`,
          adminId,
          ...resolveSaNotificationCompanyActor({
            adminId,
            companyName,
            createdBy: companyName,
          }),
          targetUrl: "/super_admin.html#companies",
          createdAt: now,
        }),
      );
    }

    return { processed: dueSellers.length };
  })()
    .catch((error) => {
      console.error("Unable to process seller account deletions:", error);
      return { processed: 0 };
    })
    .finally(() => {
      sellerDeletionSweepPromise = null;
    });

  return sellerDeletionSweepPromise;
}

function setCorsHeaders(response, request = corsRequestByResponse.get(response)) {
  applyCorsHeaders(response, request, CORS_EXTRA_ORIGINS);
}

const JSON_GZIP_MIN_BYTES = 1024;

function sendJson(response, statusCode, body) {
  setCorsHeaders(response);
  const json = JSON.stringify(body);
  const acceptEncoding = String(response.req?.headers?.["accept-encoding"] || "");
  if (
    typeof json === "string"
    && json.length >= JSON_GZIP_MIN_BYTES
    && /\bgzip\b/i.test(acceptEncoding)
  ) {
    const compressed = zlib.gzipSync(json, { level: 5 });
    response.writeHead(statusCode, {
      "Content-Type": "application/json; charset=utf-8",
      "Content-Encoding": "gzip",
      "Content-Length": compressed.length,
      Vary: "Accept-Encoding",
    });
    response.end(compressed);
    return;
  }
  response.writeHead(statusCode, {
    "Content-Type": "application/json; charset=utf-8",
  });
  response.end(json);
}

function sendText(response, statusCode, body) {
  setCorsHeaders(response);
  response.writeHead(statusCode, {
    "Content-Type": "text/plain; charset=utf-8",
  });
  response.end(body);
}

function sendRateLimited(response, result = {}) {
  const retryAfterSeconds = Math.max(1, Number(result.retryAfterSeconds) || 60);
  response.setHeader("Retry-After", String(retryAfterSeconds));
  sendJson(response, 429, {
    message: result.message || "Too many requests. Please try again later.",
    code: result.code || "RATE_LIMITED",
    retryAfterSeconds,
  });
}

async function beginLoginAttempt(request, response, identifier) {
  const settings = await getPlatformSettings();
  if (isPlatformSettingBlocking(settings, "loginRateLimit")) {
    return {
      ip: getRequestIpAddress(request) || "unknown",
      identifier: String(identifier ?? "").trim().toLowerCase() || "unknown",
      skippedRateLimit: true,
    };
  }
  const ctx = {
    ip: getRequestIpAddress(request) || "unknown",
    identifier: String(identifier ?? "").trim().toLowerCase() || "unknown",
  };
  const checked = loginLockout.check(ctx);
  if (!checked.ok) {
    sendRateLimited(response, {
      ...checked,
      message: "Too many login attempts. Please try again later.",
      code: "LOGIN_LOCKED",
    });
    return null;
  }
  return ctx;
}

function recordLoginFailure(ctx) {
  if (!ctx) {
    return;
  }
  loginLockout.recordFailure(ctx);
}

function recordLoginSuccess(ctx) {
  if (!ctx) {
    return;
  }
  loginLockout.recordSuccess(ctx);
}

function getEndpointRateLimitKind(pathname) {
  const pathValue = String(pathname || "");
  if (
    pathValue === "/api/uploads"
    || pathValue === "/api/chat-uploads"
    || pathValue === "/api/review-uploads"
    || pathValue === "/api/document-uploads"
  ) {
    return "upload";
  }
  if (pathValue === "/api/products/visual-search") {
    return "visual-search";
  }
  if (pathValue === "/api/analytics/events") {
    return "analytics";
  }
  if (pathValue === "/api/search-events") {
    return "search-events";
  }
  if (
    pathValue.endsWith("/ai-reply")
    || pathValue.startsWith("/api/ai-image-enhancement/")
  ) {
    return "ai";
  }
  return "";
}

function consumeEndpointRateLimit(request, pathname) {
  const kind = getEndpointRateLimitKind(pathname);
  const limiter = kind ? endpointRateLimiters[kind] : null;
  if (!limiter) {
    return { ok: true, remaining: 0, retryAfterSeconds: 0 };
  }
  const ip = getRequestIpAddress(request) || "unknown";
  const accountKey = String(request?.authSession?.accountId || "").trim().toLowerCase();
  const key = accountKey ? `${kind}:acct:${accountKey}` : `${kind}:ip:${ip}`;
  return limiter.consume(key);
}

function isPaymongoWebhookVerifiedIntent(intent, accountId) {
  if (!intent || typeof intent !== "object") {
    return false;
  }
  if (String(intent.accountId || "").trim() !== String(accountId || "").trim()) {
    return false;
  }
  const status = String(intent.status || "").trim().toLowerCase();
  const metadata = intent.metadata && typeof intent.metadata === "object"
    ? intent.metadata
    : {};
  return status === "active"
    || Boolean(String(metadata.paymentPaidAt || "").trim())
    || String(metadata.paymongoEventType || "").trim() === "checkout_session.payment.paid";
}

function getAccountSessionId(account) {
  return String(
    account?.id
      ?? account?.accountId
      ?? account?.accountCode
      ?? account?.employeeId
      ?? account?.userId
      ?? account?.uid
      ?? account?.email
      ?? "",
  ).trim();
}

function setAppSessionCookie(request, response, session) {
  const forwardedProtocol = String(request.headers["x-forwarded-proto"] ?? "")
    .split(",")[0]
    .trim()
    .toLowerCase();
  const secure = forwardedProtocol === "https" || request.socket?.encrypted === true;
  response.setHeader(
    "Set-Cookie",
    [
      `switch_session=${encodeURIComponent(session.token)}`,
      "Path=/",
      "HttpOnly",
      "SameSite=Lax",
      `Max-Age=${session.expiresInSeconds}`,
      secure ? "Secure" : "",
    ].filter(Boolean).join("; "),
  );
}

function issueAppSessionForAccount(request, response, account, role, overrides = {}) {
  const normalizedRole = String(role ?? "").trim().toLowerCase();
  const session = appSessionAuth.issueSession({
    accountId: overrides.accountId || getAccountSessionId(account),
    email: overrides.email || account?.email,
    role: normalizedRole,
    adminId:
      overrides.adminId
      || (normalizedRole === "seller" || normalizedRole === "employee"
        ? getRecordAdminId(
            account,
            normalizedRole === "seller" ? getAccountSessionId(account) : "",
          )
        : ""),
  });
  setAppSessionCookie(request, response, session);
  return {
    sessionToken: session.token,
    sessionExpiresAt: session.expiresAt,
    sessionExpiresInSeconds: session.expiresInSeconds,
  };
}

function parseRequestBody(request) {
  return new Promise((resolve, reject) => {
    let body = "";

    request.on("data", (chunk) => {
      body += chunk;

      if (body.length > MAX_JSON_BODY_BYTES) {
        reject(new Error("Request body is too large."));
        request.destroy();
      }
    });

    request.on("end", () => {
      if (!body) {
        resolve({});
        return;
      }

      try {
        resolve(JSON.parse(body));
      } catch (error) {
        reject(new Error("Invalid JSON body."));
      }
    });

    request.on("error", reject);
  });
}

function parseRawRequestBody(request, maxBytes = MAX_JSON_BODY_BYTES) {
  return new Promise((resolve, reject) => {
    let body = "";

    request.on("data", (chunk) => {
      body += chunk;
      if (body.length > maxBytes) {
        reject(new Error("Request body is too large."));
        request.destroy();
      }
    });

    request.on("end", () => resolve(body));
    request.on("error", reject);
  });
}

function createHttpError(message, statusCode = 400, extras = {}) {
  const error = new Error(message);
  error.statusCode = statusCode;
  if (extras && typeof extras === "object") {
    Object.assign(error, extras);
  }
  return error;
}

function getRequestOrigin(request) {
  const protocolHeader = String(
    request.headers["x-forwarded-proto"] || "",
  ).trim().toLowerCase();
  const protocol = protocolHeader === "https" ? "https" : "http";
  const host = String(
    request.headers["x-forwarded-host"] ||
    request.headers.host ||
    `127.0.0.1:${PORT}`,
  ).trim();
  return `${protocol}://${host}`;
}

function sanitizeCompanyProfileData(profileData) {
  const data = profileData && typeof profileData === "object" ? { ...profileData } : {};
  delete data.sellerPinHash;
  delete data.companyPasswordHash;
  delete data.pinForgotTokenHash;
  delete data.pinForgotUnlockHash;
  if (data.payoutBank && typeof data.payoutBank === "object") {
    const number = String(data.payoutBank.accountNumber || "").replace(/\D/g, "");
    data.payoutBank = {
      bankName: String(data.payoutBank.bankName || "").trim(),
      accountName: String(data.payoutBank.accountName || "").trim(),
      accountNumberMasked: number.length >= 4 ? `•••• ${number.slice(-4)}` : "",
    };
  }
  return data;
}

function serializeUnifiedSessionEntry(entry) {
  if (!entry || typeof entry !== "object") {
    return null;
  }

  return {
    account: serializeAccountForList(entry.account || {}),
    availableModes: Array.isArray(entry.availableModes) ? entry.availableModes : [],
    activeMode: String(entry.activeMode ?? "").trim() || "buyer",
    activeCompanyId: entry.activeCompanyId || null,
    activeCompany: entry.activeCompany
      ? {
          id: entry.activeCompany.id,
          companyCode: "",
          type: entry.activeCompany.type || "",
          status: entry.activeCompany.status || "",
          name: entry.activeCompany.name || "",
          legalName: entry.activeCompany.legalName || "",
          publicName: entry.activeCompany.publicName || "",
          maskedPublicName: entry.activeCompany.maskedPublicName || "",
          email: entry.activeCompany.email || "",
          countryCode: entry.activeCompany.countryCode || "+63",
          mobileNumber: entry.activeCompany.mobileNumber || "",
          logoUrl: entry.activeCompany.logoUrl || "",
          businessType: entry.activeCompany.businessType || "",
          subscriptionStatus: entry.activeCompany.subscriptionStatus || "draft",
          verificationStatus: entry.activeCompany.verificationStatus || "unverified",
          profileData: sanitizeCompanyProfileData(entry.activeCompany.profileData),
        }
      : null,
    capabilities: Array.isArray(entry.capabilities) ? entry.capabilities : [],
    companies: Array.isArray(entry.companies)
      ? entry.companies.map((membership) => ({
          id: membership.id,
          companyId: membership.companyId,
          membershipRole: membership.membershipRole,
          membershipStatus: membership.membershipStatus,
          title: membership.title || "",
          isPrimary: Boolean(membership.isPrimary),
          metadata: membership.metadata || {},
          createdAt: membership.createdAt || null,
          updatedAt: membership.updatedAt || null,
          company: membership.company
            ? {
                id: membership.company.id,
                companyCode: "",
                type: membership.company.type || "",
                status: membership.company.status || "",
                name: membership.company.name || "",
                legalName: membership.company.legalName || "",
                publicName: membership.company.publicName || "",
                maskedPublicName: membership.company.maskedPublicName || "",
                email: membership.company.email || "",
                countryCode: membership.company.countryCode || "+63",
                mobileNumber: membership.company.mobileNumber || "",
                logoUrl: membership.company.logoUrl || "",
                businessType: membership.company.businessType || "",
                subscriptionStatus: membership.company.subscriptionStatus || "draft",
                verificationStatus: membership.company.verificationStatus || "unverified",
                profileData: sanitizeCompanyProfileData(membership.company.profileData),
              }
            : null,
        }))
      : [],
  };
}

function getUnifiedSessionRequestIdentity(request, requestUrl, payload = null) {
  const source = payload && typeof payload === "object" ? payload : {};
  return {
    accountId: String(request?.authSession?.accountId ?? "").trim(),
    email: String(request?.authSession?.email ?? "").trim().toLowerCase(),
    activeMode: String(
      source.activeMode ??
      requestUrl?.searchParams.get("activeMode") ??
      request.headers["x-gms-active-mode"] ??
      "",
    ).trim().toLowerCase(),
    companyId: String(
      source.companyId ??
      requestUrl?.searchParams.get("companyId") ??
      request.headers["x-gms-company-id"] ??
      "",
    ).trim(),
  };
}

async function requireUnifiedSessionEntry(request, requestUrl, payload = null) {
  if (!(await isUnifiedAccountsReady())) {
    throw createHttpError("Unified account session service is unavailable.", 503);
  }

  const identity = getUnifiedSessionRequestIdentity(request, requestUrl, payload);
  if (!identity.accountId && !identity.email) {
    throw createHttpError("A signed-in account session is required.", 401, {
      code: "APP_SESSION_INVALID",
    });
  }

  const entry = await resolveUnifiedSession(identity);
  if (!entry) {
    throw createHttpError("Unified account not found.", 401, {
      code: "ACCOUNT_NOT_FOUND",
    });
  }

  assertUnifiedAccountMayRemainSignedIn(entry.account);
  return entry;
}

function assertUnifiedAccountMayRemainSignedIn(account) {
  const status = getBuyerAccountStatus(account);
  if (status === "deleted") {
    throw createHttpError("This account no longer exists. Please sign in again.", 401, {
      code: "ACCOUNT_NOT_FOUND",
    });
  }
  if (status === "banned") {
    const banReason = String(account?.banReason || account?.lastBanReason || "")
      .replace(/\s+/g, " ")
      .trim();
    throw createHttpError(
      banReason
        ? `This account has been banned by Super Admin. Reason: ${banReason}`
        : "This account has been banned by Super Admin.",
      403,
      { code: "ACCOUNT_BANNED", accountStatus: "banned" },
    );
  }
  if (status === "restricted") {
    throw createHttpError(
      "This account has been restricted by Super Admin. Please sign in again.",
      403,
      { code: "ACCOUNT_RESTRICTED", accountStatus: "restricted" },
    );
  }
  if (status === "suspended" || status === "locked") {
    throw createHttpError(
      "This account is locked or suspended. Please sign in again.",
      403,
      {
        code: status === "locked" ? "ACCOUNT_LOCKED" : "ACCOUNT_SUSPENDED",
        accountStatus: status,
      },
    );
  }
}

async function forceBuyerRemoteSignOut(account, now = new Date().toISOString()) {
  if (!account || typeof account !== "object") {
    return account;
  }
  Object.assign(account, {
    isOnline: false,
    online: false,
    loggedIn: false,
    isLoggedIn: false,
    sessionActive: false,
    presenceStatus: "offline",
    forceLogoutAt: now,
    sessionVersion: Math.max(0, Number(account.sessionVersion) || 0) + 1,
  });
  try {
    const accountId = String(account.id ?? account.accountId ?? "").trim();
    if (accountId && typeof accountDevicesApi?.revokeAllForAccount === "function") {
      await accountDevicesApi.revokeAllForAccount(accountId);
    }
  } catch (deviceError) {
    console.warn("Unable to revoke buyer device sessions for forced sign-out.", deviceError);
  }
  return account;
}

function parseBinaryRequestBody(
  request,
  {
    maxBytes = MAX_UPLOAD_BYTES,
    maxSizeLabel = MAX_UPLOAD_SIZE_LABEL,
  } = {},
) {
  return new Promise((resolve, reject) => {
    const statedContentLength = Number.parseInt(
      String(request.headers["content-length"] ?? ""),
      10,
    );
    if (
      Number.isFinite(statedContentLength) &&
      statedContentLength > maxBytes
    ) {
      request.resume();
      reject(
        createHttpError(
          `Uploaded file is too large. Keep uploads under ${maxSizeLabel}.`,
          413,
        ),
      );
      return;
    }

    const chunks = [];
    let size = 0;
    let isSettled = false;

    function rejectOnce(error) {
      if (isSettled) {
        return;
      }

      isSettled = true;
      request.resume();
      reject(error);
    }

    request.on("data", (chunk) => {
      if (isSettled) {
        return;
      }

      chunks.push(chunk);
      size += chunk.length;

      if (size > maxBytes) {
        rejectOnce(
          createHttpError(
            `Uploaded file is too large. Keep uploads under ${maxSizeLabel}.`,
            413,
          ),
        );
      }
    });

    request.on("end", () => {
      if (isSettled) {
        return;
      }

      isSettled = true;
      resolve(Buffer.concat(chunks));
    });

    request.on("error", (error) => {
      rejectOnce(error);
    });
  });
}

function hasInputValue(value) {
  return value !== null && value !== undefined && String(value).trim() !== "";
}

function parsePriceInput(value) {
  if (!hasInputValue(value)) {
    return Number.NaN;
  }

  if (typeof value === "number") {
    return value;
  }

  const normalized = String(value)
    .trim()
    .replace(/^(?:PHP|\u20B1)\s*/i, "")
    .replace(/,/g, "")
    .replace(/\s+/g, "");

  return Number(normalized);
}

function parseNumberInput(value) {
  if (!hasInputValue(value)) {
    return Number.NaN;
  }

  if (typeof value === "number") {
    return value;
  }

  const normalized = String(value).trim().replace(/,/g, "").replace(/\s+/g, "");
  return Number(normalized);
}

function normalizeAccountPhoneForComparison(value) {
  let digits = String(value ?? "").replace(/\D/g, "");

  if (digits.startsWith("63") && digits.length > 10) {
    digits = digits.slice(2);
  }

  if (digits.startsWith("0") && digits.length > 10) {
    digits = digits.slice(1);
  }

  return digits;
}

function normalizeAccountNamePartForComparison(value) {
  return String(value ?? "")
    .trim()
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizeAccountApplicantNameForComparison(account) {
  const first = normalizeAccountNamePartForComparison(account?.firstName);
  const middle = normalizeAccountNamePartForComparison(account?.middleName);
  const last = normalizeAccountNamePartForComparison(account?.lastName);
  const suffix = normalizeAccountNamePartForComparison(account?.suffix);

  if (!first || !last) {
    return "";
  }

  return [first, middle, last, suffix].join("|");
}

const EMPLOYEE_SCHEDULE_PAID_HOURS = 8;
const EMPLOYEE_SCHEDULE_ELAPSED_HOURS = 9;

function normalizeEmployeeScheduleTime(value) {
  const match = String(value ?? "").trim().match(/^(\d{2}):(\d{2})$/);
  if (!match) {
    return "";
  }

  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  if (
    !Number.isInteger(hours)
    || !Number.isInteger(minutes)
    || hours < 0
    || hours > 23
    || minutes < 0
    || minutes > 59
  ) {
    return "";
  }

  return `${String(hours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}`;
}

function addEmployeeScheduleHours(timeValue, hoursToAdd) {
  const normalizedTime = normalizeEmployeeScheduleTime(timeValue);
  if (!normalizedTime) {
    return "";
  }

  const [hours, minutes] = normalizedTime.split(":").map(Number);
  const minutesInDay = 24 * 60;
  const totalMinutes =
    ((hours * 60 + minutes + hoursToAdd * 60) % minutesInDay + minutesInDay) % minutesInDay;
  return `${String(Math.floor(totalMinutes / 60)).padStart(2, "0")}:${String(totalMinutes % 60).padStart(2, "0")}`;
}

const employeeAccessPermissionKeys = new Set([
  "admin-dashboard",
  "insight",
  "product-insight",
  "products",
  "admin-inventory",
  "employee-data",
  "register",
  "employee-dashboard",
  "live-chat",
  "employee-order",
  "employee-inventory",
  "packing-dashboard",
  "existing-account",
  "settings",
  "sign-out",
]);

const employeeAccessPermissionDashboardPaths = [
  ["admin-dashboard", "/admin_dashboard.html"],
  ["live-chat", "/main.html#live-chat"],
  ["employee-order", "/employee_order_insight.html"],
  ["employee-inventory", "/employee_stock.html"],
  ["packing-dashboard", "/packing_dashboard.html"],
  ["insight", "/insight.html"],
  ["product-insight", "/product_insight.html"],
  ["products", "/product_panel.html"],
  ["admin-inventory", "/stock.html"],
  ["employee-data", "/Employee_data.html"],
  ["register", "/register.html"],
  ["employee-dashboard", "/employee_dashboard.html"],
];
const employeePanelAccessPermissionKeys = new Set([
  "live-chat",
  "employee-order",
  "employee-inventory",
]);
const inventoryAccessPermissionKeys = new Set([
  "admin-inventory",
  "employee-inventory",
]);

function isInventoryAccessPermission(permission) {
  return inventoryAccessPermissionKeys.has(
    String(permission ?? "").trim().toLowerCase(),
  );
}

function getEquivalentEmployeeAccessPermissionKeys(permission) {
  const key = String(permission ?? "").trim().toLowerCase();
  if (isInventoryAccessPermission(key)) {
    return [...inventoryAccessPermissionKeys];
  }
  return key ? [key] : [];
}

function normalizeEmployeeAccessPermissions(value) {
  const rawValues = Array.isArray(value)
    ? value
    : String(value ?? "")
      .split(",")
      .map((item) => item.trim());

  const seen = new Set();
  const permissions = [];
  for (const rawValue of rawValues) {
    const key = String(rawValue ?? "").trim().toLowerCase();
    if (!employeeAccessPermissionKeys.has(key) || seen.has(key)) {
      continue;
    }

    seen.add(key);
    permissions.push(key);
  }

  return permissions;
}

function ensureRequiredEmployeeAccessPermissions(permissions, position) {
  const normalizedPermissions = normalizeEmployeeAccessPermissions(permissions);
  const normalizedPosition = String(position ?? "").trim().toLowerCase();
  const filteredPermissions = normalizedPermissions.filter(
    (permission) => permission !== "packing-dashboard" || normalizedPosition === "packing",
  );
  const hasEmployeePanelAccess = normalizedPermissions.some((permission) =>
    employeePanelAccessPermissionKeys.has(permission),
  );

  if (
    normalizedPosition === "admin employee" &&
    !filteredPermissions.includes("live-chat")
  ) {
    filteredPermissions.push("live-chat");
  }

  if (
    ((normalizedPosition && normalizedPosition !== "packing") || hasEmployeePanelAccess) &&
    !filteredPermissions.includes("employee-dashboard")
  ) {
    filteredPermissions.unshift("employee-dashboard");
  }

  return filteredPermissions;
}

function normalizeIsoTimestamp(value, fallback = "") {
  if (value === null && fallback === null) {
    return null;
  }

  const rawValue = String(value ?? "").trim();
  if (!rawValue) {
    return fallback;
  }

  const parsedDate = new Date(rawValue);
  return Number.isNaN(parsedDate.getTime()) ? fallback : parsedDate.toISOString();
}

function getEmployeeAccessGrantFallbackTimestamp(account, defaultFallback = "") {
  if (!account || typeof account !== "object") {
    return normalizeIsoTimestamp(defaultFallback, "");
  }

  const preferredTimestamp = account.accessPermissionsConfigured
    ? account.updatedAt ?? account.createdAt
    : account.createdAt ?? account.updatedAt;
  return normalizeIsoTimestamp(preferredTimestamp, defaultFallback);
}

function buildEmployeeAccessPermissionGrantMap(accessPermissions, existingAccount, createdAt, updatedAt) {
  const permissions = normalizeEmployeeAccessPermissions(accessPermissions);
  const existingPermissionSet = new Set(
    ensureRequiredEmployeeAccessPermissions(
      existingAccount?.accessPermissions ?? [],
      existingAccount?.position,
    ),
  );
  const existingGrantMap =
    existingAccount?.accessPermissionGrantedAt &&
    typeof existingAccount.accessPermissionGrantedAt === "object"
      ? existingAccount.accessPermissionGrantedAt
      : {};
  const existingGrantFallback = getEmployeeAccessGrantFallbackTimestamp(
    existingAccount,
    createdAt || updatedAt || new Date().toISOString(),
  );
  const permissionGrantMap = {};

  for (const permission of permissions) {
    const existingGrantAt = normalizeIsoTimestamp(existingGrantMap[permission], "");
    const fallbackGrantAt = existingPermissionSet.has(permission)
      ? existingGrantFallback
      : normalizeIsoTimestamp(updatedAt, createdAt || new Date().toISOString());
    permissionGrantMap[permission] = existingGrantAt || fallbackGrantAt;
  }

  return permissionGrantMap;
}

function normalizeEmployeeAccessPermissionGrantMap(value, accessPermissions, fallbackTimestamp = "") {
  const permissions = normalizeEmployeeAccessPermissions(accessPermissions);
  const source = value && typeof value === "object" ? value : {};
  const normalizedGrantMap = {};

  for (const permission of permissions) {
    normalizedGrantMap[permission] = normalizeIsoTimestamp(
      source[permission],
      normalizeIsoTimestamp(fallbackTimestamp, ""),
    );
  }

  return normalizedGrantMap;
}

function normalizeAccountRecord(input, existingAccount = null) {
  const source = String(input.source ?? "").trim().toLowerCase() === "app"
    ? "app"
    : "web";
  const accountType = source === "app" ? "user" : "employee";
  const employeeId = String(input.employeeId ?? "").trim();
  const timeIn = normalizeEmployeeScheduleTime(input.timeIn ?? input.scheduleTimeIn);
  const expectedTimeOut = addEmployeeScheduleHours(
    timeIn,
    EMPLOYEE_SCHEDULE_ELAPSED_HOURS,
  );
  const timeOut =
    normalizeEmployeeScheduleTime(input.timeOut ?? input.scheduleTimeOut)
    || expectedTimeOut;
  const firstName = String(input.firstName ?? "").trim();
  const middleName = String(input.middleName ?? "").trim();
  const lastName = String(input.lastName ?? "").trim();
  const suffix = String(input.suffix ?? "").trim();
  const email = String(input.email ?? input.registerEmail ?? "").trim().toLowerCase();
  const address = String(input.address ?? "").trim();
  const countryCode = String(input.countryCode ?? "").trim();
  const mobileNumber = String(input.mobileNumber ?? "").replace(/\D/g, "").trim();
  const password = String(input.password ?? "").trim();
  const department = String(input.department ?? existingAccount?.department ?? "").trim();
  const employmentType = String(
    input.employmentType ?? existingAccount?.employmentType ?? "Regular",
  ).trim() || "Regular";
  const dateOfBirth = String(input.dateOfBirth ?? existingAccount?.dateOfBirth ?? "").trim();
  const gender = String(input.gender ?? existingAccount?.gender ?? "").trim();
  const startDate = String(
    input.startDate ?? input.dateHired ?? existingAccount?.startDate ?? existingAccount?.dateHired ?? "",
  ).trim();
  const supervisor = String(input.supervisor ?? existingAccount?.supervisor ?? "").trim();
  const username = String(input.username ?? existingAccount?.username ?? email).trim().toLowerCase();
  const employeeRole = String(
    input.employeeRole ?? input.accountRole ?? existingAccount?.employeeRole ?? "Employee",
  ).trim() || "Employee";
  const requestedStatus = String(
    input.status ?? input.accountStatus ?? existingAccount?.status ?? "active",
  ).trim().toLowerCase();
  const status = ["active", "inactive", "on-leave", "probation"].includes(requestedStatus)
    ? requestedStatus
    : "active";
  const adminId = normalizeAdminTenantId(
    input.adminId ??
      input.ownerAdminId ??
      input.tenantId ??
      existingAccount?.adminId,
    DEFAULT_ADMIN_ID,
  );
  const normalizeAccountTimestamp = (value, fallback = "") => {
    if (value === null && fallback === null) {
      return null;
    }

    const rawValue = String(value ?? "").trim();
    if (!rawValue) {
      return fallback;
    }

    const parsedDate = new Date(rawValue);
    return Number.isNaN(parsedDate.getTime()) ? fallback : parsedDate.toISOString();
  };
  const profileImageUrl = String(
    input.profileImageUrl
      ?? input.avatarUrl
      ?? input.photoUrl
      ?? existingAccount?.profileImageUrl
      ?? "",
  ).trim();
  const rawGmailBinding =
    input.gmailBinding && typeof input.gmailBinding === "object"
      ? input.gmailBinding
      : existingAccount?.gmailBinding && typeof existingAccount.gmailBinding === "object"
      ? existingAccount.gmailBinding
      : {};
  const gmailBindingEmail = String(
    input.gmailBindingEmail
      ?? input.boundGmail
      ?? rawGmailBinding.email
      ?? "",
  ).trim().toLowerCase();
  const gmailBinding = gmailBindingEmail
    ? {
      email: gmailBindingEmail,
      provider: "gmail",
      boundAt: rawGmailBinding.boundAt || new Date().toISOString(),
    }
    : null;
  const rawAccessPermissionsWereProvided =
    Object.prototype.hasOwnProperty.call(input, "accessPermissions")
    || Object.prototype.hasOwnProperty.call(input, "employeeAccessPermissions");
  const accessPermissionsWereProvided = existingAccount
    ? Boolean(input.__accessPermissionsWereProvided)
    : rawAccessPermissionsWereProvided;
  const isAccessPermissionUpdate = Boolean(
    source === "web"
    && existingAccount
    && accessPermissionsWereProvided,
  );
  const position = String(
    isAccessPermissionUpdate
      ? existingAccount?.position
      : (input.position ?? existingAccount?.position ?? ""),
  ).trim();
  const accessPermissions = ensureRequiredEmployeeAccessPermissions(
    input.accessPermissions ?? input.employeeAccessPermissions ?? existingAccount?.accessPermissions ?? [],
    position,
  );
  const accessPermissionsConfigured = Boolean(
    source === "web"
    && (
      input.accessPermissionsConfigured
      || existingAccount?.accessPermissionsConfigured
      || accessPermissionsWereProvided
    ),
  );
  const faceVerified = Boolean(input.faceVerified);
  const verifiedAt = faceVerified && input.verifiedAt
    ? new Date(input.verifiedAt).toISOString()
    : null;
  const rawDocument =
    input.eDocument && typeof input.eDocument === "object"
      ? input.eDocument
      : {};
  const eDocument = {
    type: String(rawDocument.type ?? rawDocument.documentType ?? "").trim(),
    label: String(rawDocument.label ?? "").trim(),
    fileName: String(rawDocument.fileName ?? "").trim(),
    fileExtension: String(rawDocument.fileExtension ?? "").trim().toLowerCase(),
    url: String(rawDocument.url ?? rawDocument.documentUrl ?? "").trim(),
    uploadedAt: rawDocument.uploadedAt
      ? new Date(rawDocument.uploadedAt).toISOString()
      : null,
  };

  if (firstName.length < 2 || lastName.length < 2) {
    throw new Error("First name and last name must be at least 2 characters long.");
  }

  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    throw new Error("Please enter a valid email address.");
  }

  if (gmailBindingEmail && !/^[^\s@]+@gmail\.com$/.test(gmailBindingEmail)) {
    throw new Error("Gmail binding must use a valid Gmail address.");
  }

  if (password.length < 6) {
    throw new Error("Password must be at least 6 characters long.");
  }

  if (source === "web") {
    if (!/^(?:[A-Z0-9]{2,8}-)?\d{6}$/.test(employeeId)) {
      throw new Error("Employee ID must be a 6-digit number or follow the ABC-012345 format.");
    }

    if (position.length < 2) {
      throw new Error("Position is required.");
    }

    if (!timeIn) {
      throw new Error("Time In is required.");
    }

    if (!timeOut || timeOut !== expectedTimeOut) {
      throw new Error("Time Out must be computed automatically from Time In.");
    }

    if (countryCode !== "+63") {
      throw new Error("Phone number must use the +63 country code.");
    }

    if (!/^9\d{9}$/.test(mobileNumber)) {
      throw new Error("Phone number must be a valid Philippine mobile number.");
    }
  }

  if (source === "app") {
    if (!countryCode) {
      throw new Error("Country code is required.");
    }

    if (mobileNumber.length < 7) {
      throw new Error("Mobile number must be at least 7 digits long.");
    }
  }

  const createdAt = normalizeAccountTimestamp(
    existingAccount?.createdAt ?? input.createdAt,
    new Date().toISOString(),
  );
  const updatedAt = normalizeAccountTimestamp(
    input.updatedAt,
    existingAccount?.updatedAt ?? createdAt,
  );
  const passwordUpdatedAt = normalizeAccountTimestamp(
    input.passwordUpdatedAt,
    existingAccount?.passwordUpdatedAt ?? (password ? createdAt : null),
  );
  const accessPermissionGrantedAt = buildEmployeeAccessPermissionGrantMap(
    accessPermissions,
    existingAccount,
    createdAt,
    updatedAt,
  );

  return {
    id: existingAccount?.id ?? `acct-${Date.now()}`,
    accountCode:
      existingAccount?.accountCode ??
      (source === "app" ? `USR-${String(Date.now()).slice(-6)}` : employeeId),
    employeeId: source === "web" ? employeeId : "",
    position: source === "web" ? position : "",
    timeIn: source === "web" ? timeIn : "",
    timeOut: source === "web" ? timeOut : "",
    workHours: source === "web" ? EMPLOYEE_SCHEDULE_PAID_HOURS : 0,
    firstName,
    middleName,
    lastName,
    suffix,
    email,
    address,
    department,
    employmentType,
    dateOfBirth,
    gender,
    startDate,
    supervisor,
    username,
    employeeRole,
    status,
    countryCode,
    mobileNumber,
    password,
    eDocument,
    profileImageUrl,
    gmailBinding,
    accessPermissions: source === "web" ? accessPermissions : [],
    accessPermissionGrantedAt: source === "web" ? accessPermissionGrantedAt : {},
    accessPermissionsConfigured,
    role: accountType,
    source,
    faceVerified,
    verifiedAt,
    passwordUpdatedAt,
    createdAt,
    updatedAt,
    adminId,
  };
}

function isAdminAccount(account) {
  return String(account?.role ?? "").trim().toLowerCase() === "admin";
}

function isAdminTemporaryBanExpired(account) {
  const banType = String(account?.banType ?? account?.ban_mode ?? "")
    .trim()
    .toLowerCase();
  if (banType !== "temporary") {
    return false;
  }

  const expiresAt = new Date(account?.banExpiresAt ?? account?.ban_expires_at ?? "");
  return Number.isFinite(expiresAt.getTime()) && expiresAt.getTime() <= Date.now();
}

function isAdminTemporaryRestrictionExpired(account) {
  const expiresAt = new Date(
    account?.restrictExpiresAt ?? account?.restrictionExpiresAt ?? account?.restrict_expires_at ?? "",
  );
  return Number.isFinite(expiresAt.getTime()) && expiresAt.getTime() <= Date.now();
}

function getAdminAccountRestrictionMessage(account) {
  const enforcementScope = String(account?.enforcementScope || "").trim().toLowerCase();
  // Company-scoped bans/restricts must not block the user login account.
  if (enforcementScope === "company") {
    const deletionStatusOnly = getSellerAccountDeletionStatus(account);
    if (deletionStatusOnly === "deleted") {
      return "This seller account has been deleted.";
    }
    return "";
  }

  const status = String(account?.status ?? account?.accountStatus ?? account?.accountState ?? "")
    .trim()
    .toLowerCase();
  const deletionStatus = getSellerAccountDeletionStatus(account);
  const isBannedAccount = status === "banned" || account?.isBanned === true;
  const isRestrictedAccount = isAdminAccountMarkedRestricted(account);
  const temporaryBanExpired = isBannedAccount && isAdminTemporaryBanExpired(account);

  if (deletionStatus === "deleted" || status === "deleted") {
    return "This seller account has been deleted.";
  }

  if (isBannedAccount && !temporaryBanExpired) {
    const expiresAt = new Date(account?.banExpiresAt ?? account?.ban_expires_at ?? "");
    if (
      String(account?.banType ?? "").trim().toLowerCase() === "temporary" &&
      Number.isFinite(expiresAt.getTime())
    ) {
      return `This admin account is banned until ${expiresAt.toLocaleString()}.`;
    }
    return "This admin account is banned.";
  }

  if (
    !temporaryBanExpired &&
    !isRestrictedAccount &&
    (
      status === "deactivated" ||
      status === "inactive" ||
      status === "disabled" ||
      account?.isActive === false ||
      account?.disabled === true
    )
  ) {
    return "This admin account is deactivated.";
  }

  return "";
}

function getSellerCompanyWorkspaceBlockMessage(company, seller = null) {
  const gate = resolveSellerWorkspaceGate(company, seller);
  if (!gate.workspaceBlocked) {
    return "";
  }
  if (gate.workspaceStatus === "banned") {
    return gate.banReason
      ? `This company is banned by Super Admin. Seller dashboard access is blocked. Reason: ${gate.banReason}`
      : "This company is banned by Super Admin. Seller dashboard access is blocked.";
  }
  if (gate.workspaceStatus === "deactivated" || gate.workspaceStatus === "suspended") {
    return "This company is deactivated. Seller dashboard access is blocked.";
  }
  if (gate.workspaceStatus === "pending_review" || gate.workspaceStatus === "pending_payment") {
    return "This company is still under Super Admin review. Seller dashboard access is blocked.";
  }
  if (seller) {
    const accountMessage = getAdminAccountRestrictionMessage(seller);
    if (accountMessage) {
      return accountMessage;
    }
  }
  return "Seller dashboard access is blocked for this company.";
}

function resolveSellerWorkspaceGate(company, seller = null) {
  const companyStatus = String(
    company?.status
      ?? company?.accountState
      ?? company?.enforcementStatus
      ?? company?.membershipStatus
      ?? "",
  )
    .trim()
    .toLowerCase()
    .replace(/[\s-]+/g, "_");
  const profile = company?.profileData && typeof company.profileData === "object"
    ? company.profileData
    : (company?.profile_data && typeof company.profile_data === "object"
      ? company.profile_data
      : {});
  const profileEnforcement = String(
    profile.lastEnforcementStatus || "",
  )
    .trim()
    .toLowerCase()
    .replace(/[\s-]+/g, "_");
  const sellerStatus = String(
    seller?.status
      ?? seller?.accountStatus
      ?? seller?.adminStatus
      ?? "",
  )
    .trim()
    .toLowerCase()
    .replace(/[\s-]+/g, "_");
  const sellerEnforcementScope = String(seller?.enforcementScope || "").trim().toLowerCase();
  // User-level bans block every company workspace. Company-scoped bans only
  // block via the company record itself (companyBanned below).
  const sellerBanned =
    sellerEnforcementScope !== "company"
    && (
      seller?.isBanned === true
      || seller?.banned === true
      || sellerStatus === "banned"
      || sellerStatus.includes("ban")
    );
  // Live company ban is driven by status / lastEnforcementStatus — not by a
  // leftover profile.banReason after Super Admin unban (jsonb merge used to keep it).
  const companyStatusIsBanned =
    companyStatus === "banned"
    || (companyStatus.includes("ban") && !companyStatus.includes("unban"));
  const profileEnforcementIsBanned =
    profileEnforcement === "banned"
    || (profileEnforcement.includes("ban") && !profileEnforcement.includes("unban"));
  const companyBanned = companyStatusIsBanned || profileEnforcementIsBanned;

  if (companyBanned || sellerBanned) {
    const banReason = String(
      profile.banReason
        || profile.lastEnforcementReason
        || seller?.banReason
        || "",
    )
      .replace(/\s+/g, " ")
      .trim();
    const banDescription = String(
      profile.banDescription
        || profile.lastEnforcementDescription
        || seller?.banDescription
        || seller?.banDetails
        || "",
    )
      .replace(/\s+/g, " ")
      .trim();
    return {
      workspaceBlocked: true,
      workspaceStatus: "banned",
      banReason,
      banDescription,
    };
  }

  if (
    companyStatus === "pending_payment"
    || companyStatus.includes("pending_payment")
  ) {
    return {
      workspaceBlocked: true,
      workspaceStatus: "pending_payment",
      banReason: "",
      banDescription: "",
    };
  }

  if (
    companyStatus === "pending_review"
    || companyStatus.includes("pending")
    || companyStatus.includes("review")
    || companyStatus === "draft"
    || String(company?.subscriptionStatus || "").trim().toLowerCase() === "pending_review"
    || String(company?.subscriptionStatus || "").trim().toLowerCase() === "pending_payment"
  ) {
    const sub = String(company?.subscriptionStatus || "").trim().toLowerCase();
    return {
      workspaceBlocked: true,
      workspaceStatus: sub === "pending_payment" ? "pending_payment" : "pending_review",
      banReason: "",
      banDescription: "",
    };
  }

  if (
    companyStatus === "deactivated"
    || companyStatus === "inactive"
    || companyStatus === "deleted"
    || profileEnforcement === "deactivated"
    || sellerStatus === "deactivated"
  ) {
    return {
      workspaceBlocked: true,
      workspaceStatus: "deactivated",
      banReason: "",
      banDescription: "",
    };
  }

  if (sellerStatus === "suspended" || sellerStatus.includes("suspend")) {
    return {
      workspaceBlocked: true,
      workspaceStatus: "suspended",
      banReason: "",
      banDescription: "",
    };
  }

  return {
    workspaceBlocked: false,
    workspaceStatus: "active",
    banReason: "",
    banDescription: "",
  };
}

function createAdminAccountId(input) {
  const stem = normalizeAdminTenantId(
    input?.companyName ??
      input?.storeName ??
      input?.businessName ??
      input?.email ??
      "admin",
    "admin",
  );
  return `admin-${stem}-${Date.now()}`;
}

function normalizeAdminPaymentCardMetadata(value) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null;
  }

  const last4 = String(value.last4 ?? "").replace(/\D/g, "").slice(-4);
  if (last4.length !== 4) {
    return null;
  }

  const expiryMonth = Number(value.expiryMonth);
  const expiryYear = Number(value.expiryYear);
  return {
    brand: String(value.brand ?? "Card").replace(/\s+/g, " ").trim().slice(0, 40) || "Card",
    last4,
    cardholderName: String(value.cardholderName ?? "")
      .replace(/\s+/g, " ")
      .trim()
      .slice(0, 120),
    expiryMonth: Number.isInteger(expiryMonth) && expiryMonth >= 1 && expiryMonth <= 12
      ? expiryMonth
      : null,
    expiryYear: Number.isInteger(expiryYear) && expiryYear >= 2000 && expiryYear <= 9999
      ? expiryYear
      : null,
  };
}

function normalizeAdminAccountRecord(input, existingAccount = null) {
  const email = String(input.email ?? input.registerEmail ?? "").trim().toLowerCase();
  const passwordFromInput = String(input.password ?? "").trim();
  const existingPassword = String(existingAccount?.password ?? "").trim();
  const password = passwordFromInput || existingPassword;
  const storeName = String(
    input.companyName ??
      input.storeName ??
      input.businessName ??
      existingAccount?.companyName ??
      existingAccount?.storeName ??
      "",
  ).replace(/\s+/g, " ").trim();
  const storeType = normalizeStoreTypeName(
    input.storeType ??
      input.storeTypeName ??
      input.businessType ??
      existingAccount?.storeType ??
      existingAccount?.storeTypeName ??
      existingAccount?.businessType ??
      "",
  );
  const firstName = String(input.firstName ?? existingAccount?.firstName ?? "").trim();
  const lastName = String(input.lastName ?? existingAccount?.lastName ?? "").trim();
  const mobileNumber = String(input.mobileNumber ?? existingAccount?.mobileNumber ?? "")
    .replace(/\D/g, "")
    .trim();
  const countryCode = String(input.countryCode ?? existingAccount?.countryCode ?? "+63").trim() || "+63";
  const now = normalizeIsoTimestamp(input.updatedAt, new Date().toISOString());
  const hasPaymentCardInput = Object.prototype.hasOwnProperty.call(input, "paymentCard");
  const paymentCard = hasPaymentCardInput
    ? normalizeAdminPaymentCardMetadata(input.paymentCard)
    : normalizeAdminPaymentCardMetadata(existingAccount?.paymentCard);
  const googleProfile =
    input.googleProfile && typeof input.googleProfile === "object"
      ? input.googleProfile
      : existingAccount?.googleProfile && typeof existingAccount.googleProfile === "object"
        ? existingAccount.googleProfile
        : null;
  const isGoogleLinked = Boolean(
    googleProfile ||
      String(input.authProvider ?? existingAccount?.authProvider ?? "").trim().toLowerCase() === "google" ||
      String(input.source ?? existingAccount?.source ?? "").trim().toLowerCase() === "google",
  );
  const isSettingNewPlainPassword =
    Boolean(passwordFromInput) && !looksLikeBcryptHash(passwordFromInput);

  if (storeName.length < 2) {
    throw new Error("Company name must be at least 2 characters long.");
  }

  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    throw new Error("Please enter a valid admin email address.");
  }

  // Profile updates: never block Save Changes on password.
  // Only enforce length when a new plaintext password is explicitly provided.
  if (isSettingNewPlainPassword && passwordFromInput.length < 6) {
    throw new Error("Admin password must be at least 6 characters long.");
  }
  if (existingAccount) {
    // Keep existing hash/empty Google password as-is during profile/picture updates.
  } else if (
    !looksLikeBcryptHash(password) &&
    password.length < 6 &&
    !isGoogleLinked
  ) {
    throw new Error("Admin password must be at least 6 characters long.");
  }

  const id = existingAccount?.id ?? createAdminAccountId({
    companyName: storeName,
    email,
  });
  const adminId = normalizeAdminTenantId(
    input.adminId ?? existingAccount?.adminId ?? id,
    id,
  );
  const createdAt = existingAccount?.createdAt || now;

  return {
    ...(existingAccount && typeof existingAccount === "object" ? existingAccount : {}),
    id,
    adminId,
    accountCode: existingAccount?.accountCode || adminId,
    role: "admin",
    source: "web",
    storeName,
    companyName: storeName,
    businessName: storeName,
    storeType,
    storeTypeName: storeType,
    businessType: storeType,
    storeTypeUpdatedAt: normalizeIsoTimestamp(
      input.storeTypeUpdatedAt,
      existingAccount?.storeTypeUpdatedAt ?? (storeType ? createdAt : null),
    ),
    firstName,
    middleName: String(input.middleName ?? existingAccount?.middleName ?? "").trim(),
    lastName,
    suffix: String(input.suffix ?? existingAccount?.suffix ?? "").trim(),
    email,
    countryCode,
    mobileNumber,
    password,
    emailVerified: input.emailVerified === true || existingAccount?.emailVerified === true,
    mobileVerified: input.mobileVerified === true || existingAccount?.mobileVerified === true,
    verificationSkipped: Object.prototype.hasOwnProperty.call(input, "verificationSkipped")
      ? input.verificationSkipped === true
      : existingAccount?.verificationSkipped === true,
    verificationChannel: ["email", "mobile"].includes(
      String(input.verificationChannel ?? existingAccount?.verificationChannel ?? "")
        .trim()
        .toLowerCase(),
    )
      ? String(input.verificationChannel ?? existingAccount?.verificationChannel).trim().toLowerCase()
      : "",
    verificationToken: String(input.verificationToken ?? "").trim(),
    googleProfile,
    paymentCard,
    paymentCardSkipped: Object.prototype.hasOwnProperty.call(input, "paymentCardSkipped")
      ? input.paymentCardSkipped === true
      : existingAccount?.paymentCardSkipped === true,
    planName: String(input.planName ?? existingAccount?.planName ?? "Free Plan")
      .replace(/\s+/g, " ")
      .trim()
      .slice(0, 80) || "Free Plan",
    planStatus: String(input.planStatus ?? existingAccount?.planStatus ?? "active")
      .replace(/\s+/g, " ")
      .trim()
      .toLowerCase()
      .slice(0, 40) || "active",
    planStartedAt: normalizeIsoTimestamp(
      input.planStartedAt,
      existingAccount?.planStartedAt ?? createdAt,
    ),
    profileImageUrl: String(
      input.profileImageUrl ??
        input.logoUrl ??
        existingAccount?.profileImageUrl ??
        "",
    ).trim(),
    companyPictureUrl: String(
      input.companyPictureUrl ??
        input.businessLogoUrl ??
        input.logoUrl ??
        input.profileImageUrl ??
        existingAccount?.companyPictureUrl ??
        existingAccount?.businessLogoUrl ??
        existingAccount?.logoUrl ??
        existingAccount?.profileImageUrl ??
        "",
    ).trim(),
    businessLogoUrl: String(
      input.businessLogoUrl ??
        input.companyPictureUrl ??
        input.logoUrl ??
        input.profileImageUrl ??
        existingAccount?.businessLogoUrl ??
        existingAccount?.companyPictureUrl ??
        existingAccount?.logoUrl ??
        existingAccount?.profileImageUrl ??
        "",
    ).trim(),
    logoUrl: String(
      input.logoUrl ??
        input.companyPictureUrl ??
        input.businessLogoUrl ??
        input.profileImageUrl ??
        existingAccount?.logoUrl ??
        existingAccount?.companyPictureUrl ??
        existingAccount?.businessLogoUrl ??
        existingAccount?.profileImageUrl ??
        "",
    ).trim(),
    companyBackgroundUrl: String(
      input.companyBackgroundUrl ??
        input.backgroundUrl ??
        input.coverImageUrl ??
        existingAccount?.companyBackgroundUrl ??
        existingAccount?.backgroundUrl ??
        existingAccount?.coverImageUrl ??
        "",
    ).trim(),
    backgroundUrl: String(
      input.backgroundUrl ??
        input.companyBackgroundUrl ??
        input.coverImageUrl ??
        existingAccount?.backgroundUrl ??
        existingAccount?.companyBackgroundUrl ??
        existingAccount?.coverImageUrl ??
        "",
    ).trim(),
    coverImageUrl: String(
      input.coverImageUrl ??
        input.companyBackgroundUrl ??
        input.backgroundUrl ??
        existingAccount?.coverImageUrl ??
        existingAccount?.companyBackgroundUrl ??
        existingAccount?.backgroundUrl ??
        "",
    ).trim(),
    accessPermissions: [],
    accessPermissionGrantedAt: {},
    accessPermissionsConfigured: false,
    createdAt,
    updatedAt: now,
    passwordUpdatedAt:
      passwordFromInput && passwordFromInput !== existingPassword
        ? now
        : existingAccount?.passwordUpdatedAt ?? createdAt,
  };
}

function isAdminPresenceTimestampFresh(account) {
  const rawTimestamp = account?.presenceUpdatedAt ?? account?.lastOnlineAt ?? account?.lastLoginAt ?? "";
  const timestamp = new Date(rawTimestamp);
  if (!Number.isFinite(timestamp.getTime())) {
    return false;
  }
  return Date.now() - timestamp.getTime() <= ADMIN_PRESENCE_STALE_MS;
}

function isAdminAccountPresenceOnline(account) {
  const statusToken = String(
    account?.presenceStatus ?? account?.onlineStatus ?? account?.sessionStatus ?? account?.loginStatus ?? "",
  )
    .trim()
    .toLowerCase();
  const hasOnlineFlag = Boolean(
    account?.isOnline === true ||
      account?.online === true ||
      account?.loggedIn === true ||
      account?.isLoggedIn === true ||
      account?.sessionActive === true ||
      statusToken === "online" ||
      statusToken === "logged-in" ||
      statusToken === "logged in",
  );
  return hasOnlineFlag && isAdminPresenceTimestampFresh(account);
}

function serializeAdminAccount(account, counts = null) {
  const { password, ...safeAccount } = account || {};
  const isPresenceOnline = isAdminAccountPresenceOnline(safeAccount);
  const companyName = [
    safeAccount.companyName,
    safeAccount.storeName,
    safeAccount.businessName,
  ]
    .map((value) => String(value ?? "").trim())
    .find(Boolean) || "";
  const storeType = [
    safeAccount.storeType,
    safeAccount.storeTypeName,
    safeAccount.businessType,
  ]
    .map((value) => String(value ?? "").trim())
    .find(Boolean) || "";
  const performanceBadge = evaluateSellerPerformanceBadge({
    ...safeAccount,
    counts,
    reportSummary: safeAccount.reportSummary,
    accountState:
      safeAccount.accountState
      || safeAccount.companyStatus
      || safeAccount.companyEnforcementStatus,
  });
  const topSellerRanking = scoreCompanyTopSeller({
    ...safeAccount,
    createdAt: safeAccount.createdAt ?? safeAccount.created_at,
    approvedAt: safeAccount.approvedAt ?? safeAccount.approved_at,
    registeredAt: safeAccount.registeredAt ?? safeAccount.registered_at,
    rating: counts?.rating,
    reviews: counts?.commentCount ?? counts?.reviewCount,
    completedOrders: counts?.completedOrders,
    unitsSold: counts?.completedOrders,
    cancelRate: counts?.cancelRate,
    chats: counts?.chatThreads ?? counts?.chats,
    timedReplies: counts?.timedReplies,
    avgFirstResponseHours: counts?.avgFirstResponseHours,
    openStaleConcerns: counts?.openStaleConcerns,
    openReports: counts?.openReports,
    needsWarning: safeAccount.reportSummary?.needsWarning === true,
    accountState:
      safeAccount.accountState
      || safeAccount.companyStatus
      || safeAccount.companyEnforcementStatus,
  });
  return {
    ...safeAccount,
    isOnline: isPresenceOnline,
    online: isPresenceOnline,
    loggedIn: isPresenceOnline,
    isLoggedIn: isPresenceOnline,
    sessionActive: isPresenceOnline,
    onlineStatus: isPresenceOnline ? "online" : "offline",
    presenceStatus: isPresenceOnline ? "online" : "offline",
    companyName,
    storeName: String(safeAccount.storeName ?? "").trim() || companyName,
    businessName: String(safeAccount.businessName ?? "").trim() || companyName,
    storeType,
    storeTypeName: storeType,
    businessType: storeType,
    adminId: getRecordAdminId(safeAccount, safeAccount?.adminId || safeAccount?.id),
    accountCode: String(safeAccount.accountCode ?? safeAccount.account_code ?? "").trim(),
    companyId: String(safeAccount.companyId ?? safeAccount.company_id ?? "").trim(),
    companyCode: "",
    sellerKind: String(safeAccount.sellerKind ?? safeAccount.seller_kind ?? "").trim(),
    planName: "Free",
    performanceBadge,
    legitimateBadge: performanceBadge.earned,
    topSellerRanking,
    countryCode: String(safeAccount.countryCode ?? safeAccount.country_code ?? "+63").trim() || "+63",
    displayName:
      [safeAccount.firstName, safeAccount.lastName].filter(Boolean).join(" ").trim() ||
      companyName ||
      String(safeAccount.email ?? "").trim() ||
      "Admin",
    ...(counts && typeof counts === "object" ? { counts } : {}),
  };
}

function assignOfficialCompanyRanks(admins = []) {
  const groups = new Map();
  for (const admin of Array.isArray(admins) ? admins : []) {
    if (admin?.topSellerRanking?.eligible !== true) {
      continue;
    }
    const storeType = normalizeStoreTypeName(
      admin?.storeType ?? admin?.storeTypeName ?? admin?.businessType,
    ).toLowerCase();
    if (!storeType) {
      continue;
    }
    const rows = groups.get(storeType);
    if (rows) {
      rows.push(admin);
    } else {
      groups.set(storeType, [admin]);
    }
  }

  const rankByAdminId = new Map();
  for (const rows of groups.values()) {
    rows
      .slice()
      .sort((left, right) => compareCompanyTopSellerRows(
        {
          score: left?.topSellerRanking?.score,
          rating: left?.counts?.rating ?? left?.rating,
          reviewCount: left?.counts?.commentCount ?? left?.counts?.reviewCount ?? left?.reviewCount,
          avgFirstResponseHours: left?.counts?.avgFirstResponseHours
            ?? left?.avgFirstResponseHours,
          companyName: left?.companyName || left?.storeName || "",
        },
        {
          score: right?.topSellerRanking?.score,
          rating: right?.counts?.rating ?? right?.rating,
          reviewCount: right?.counts?.commentCount ?? right?.counts?.reviewCount ?? right?.reviewCount,
          avgFirstResponseHours: right?.counts?.avgFirstResponseHours
            ?? right?.avgFirstResponseHours,
          companyName: right?.companyName || right?.storeName || "",
        },
      ))
      .forEach((admin, index) => {
        const adminId = String(getRecordAdminId(admin, admin?.id) || "").trim().toLowerCase();
        if (adminId) {
          rankByAdminId.set(adminId, index + 1);
        }
      });
  }

  return (Array.isArray(admins) ? admins : []).map((admin) => {
    const adminId = String(getRecordAdminId(admin, admin?.id) || "").trim().toLowerCase();
    const rank = rankByAdminId.get(adminId) || 0;
    if (rank < 1) {
      return admin;
    }
    return {
      ...admin,
      officialRank: rank,
      topSellerRanking: {
        ...(admin.topSellerRanking && typeof admin.topSellerRanking === "object"
          ? admin.topSellerRanking
          : {}),
        rank,
      },
    };
  });
}

function applyEarnedPerformanceBadge(admin) {
  if (!admin || typeof admin !== "object") {
    return admin;
  }
  const performanceBadge = evaluateSellerPerformanceBadge({
    ...admin,
    counts: admin.counts,
    reportSummary: admin.reportSummary,
    accountState:
      admin.accountState
      || admin.companyStatus
      || admin.companyEnforcementStatus,
  });
  return {
    ...admin,
    performanceBadge,
    legitimateBadge: performanceBadge.earned,
  };
}

function normalizeProductCompanyMetadataText(value) {
  return String(value ?? "").replace(/\s+/g, " ").trim();
}

function isPaidSellerPlan(planName, amount) {
  const paidAmount = Number(amount);
  if (Number.isFinite(paidAmount) && paidAmount > 0) {
    return true;
  }

  const name = String(planName ?? "").trim().toLowerCase();
  if (!name || name === "free" || name === "free plan" || name.startsWith("free ")) {
    return false;
  }

  return (
    name === "basic" ||
    name === "pro" ||
    name === "premium" ||
    name === "starter seller plan"
  );
}

function buildSellerPerformanceCountsByAdminId(sources = {}) {
  const countsByAdminId = new Map();
  for (const account of Array.isArray(sources.accounts) ? sources.accounts : []) {
    if (!isAdminAccount(account)) {
      continue;
    }
    const adminId = getRecordAdminId(account, account.id);
    if (!adminId) {
      continue;
    }
    countsByAdminId.set(adminId, getAdminWorkspaceCounts(adminId, sources));
  }
  return countsByAdminId;
}

function getProductCompanyMetadataByAdminId(accounts = [], countsByAdminId = null) {
  const metadataByAdminId = new Map();

  for (const account of Array.isArray(accounts) ? accounts : []) {
    if (!isAdminAccount(account)) {
      continue;
    }

    const adminId = getRecordAdminId(account, account.adminId || account.id);
    const counts = countsByAdminId instanceof Map ? countsByAdminId.get(adminId) : null;
    const serializedAccount = serializeAdminAccount(account, counts);
    if (!adminId) {
      continue;
    }

    const companyName = [
      serializedAccount.companyName,
      serializedAccount.storeName,
      serializedAccount.businessName,
      serializedAccount.displayName,
      serializedAccount.email,
    ]
      .map(normalizeProductCompanyMetadataText)
      .find(Boolean) || "";
    const companyPictureUrl = [
      serializedAccount.companyPictureUrl,
      serializedAccount.companyProfileImageUrl,
      serializedAccount.profileImageUrl,
      serializedAccount.logoUrl,
      serializedAccount.avatarUrl,
      serializedAccount.photoUrl,
    ]
      .map((value) => String(value ?? "").trim())
      .find(Boolean) || "";

    const storeTypeName = normalizeStoreTypeName(
      serializedAccount.storeType
        ?? serializedAccount.storeTypeName
        ?? serializedAccount.businessType,
    );

    const planName = "Free";
    const isLegitSeller = Boolean(serializedAccount.legitimateBadge);
    const companyIsBanned =
      isSellerAccountBannedForListings(serializedAccount) ||
      isSellerAccountRecordBanned(serializedAccount);
    const companyIsRestricted =
      isSellerAccountRestrictedForListings(serializedAccount) ||
      ["restricted"].includes(
        String(
          serializedAccount.companyStatus
            ?? serializedAccount.companyEnforcementStatus
            ?? serializedAccount.accountState
            ?? "",
        )
          .trim()
          .toLowerCase(),
      );
    const companyAccountState = companyIsBanned
      ? "banned"
      : companyIsRestricted
        ? "restricted"
        : String(
            serializedAccount.accountState
              ?? serializedAccount.accountStatus
              ?? serializedAccount.status
              ?? "active",
          )
            .trim()
            .toLowerCase() || "active";

    metadataByAdminId.set(adminId, {
      companyName,
      companyPictureUrl,
      storeType: storeTypeName,
      storeTypeName,
      businessType: storeTypeName,
      planName,
      hasPaidPlan: false,
      isLegitSeller,
      legitimateBadge: isLegitSeller,
      performanceBadge: serializedAccount.performanceBadge || null,
      companyAccountState,
      companyIsBanned,
      companyIsRestricted,
    });
  }

  return metadataByAdminId;
}

function attachProductCompanyMetadata(product, metadataByAdminId = new Map()) {
  if (!product || typeof product !== "object") {
    return product;
  }

  const adminId = getRecordAdminId(product);
  const metadata = metadataByAdminId.get(adminId) ?? {};
  const companyName = [
    product.companyName,
    product.storeName,
    product.businessName,
    metadata.companyName,
  ]
    .map(normalizeProductCompanyMetadataText)
    .find(Boolean) || "";
  const companyPictureUrl = [
    product.companyPictureUrl,
    product.companyProfileImageUrl,
    metadata.companyPictureUrl,
  ]
    .map((value) => String(value ?? "").trim())
    .find(Boolean) || "";
  const storeTypeName = normalizeStoreTypeName(
    product.storeType
      ?? product.storeTypeName
      ?? product.businessType
      ?? metadata.storeType
      ?? metadata.storeTypeName
      ?? metadata.businessType,
  );

  const isLegitSeller = Boolean(
    metadata.legitimateBadge ?? metadata.isLegitSeller,
  );
  const planName = "Free";
  const companyIsBanned = Boolean(
    metadata.companyIsBanned || product.companyIsBanned,
  );
  const companyIsRestricted = Boolean(
    metadata.companyIsRestricted || product.companyIsRestricted,
  );
  const companyAccountState = String(
    (companyIsBanned
      ? "banned"
      : companyIsRestricted
        ? "restricted"
        : (metadata.companyAccountState || product.companyAccountState || "active")),
  )
    .trim()
    .toLowerCase() || "active";

  return {
    ...product,
    companyName,
    storeName: String(product.storeName ?? "").trim() || companyName,
    businessName: String(product.businessName ?? "").trim() || companyName,
    companyPictureUrl,
    storeType: storeTypeName || String(product.storeType ?? "").trim(),
    storeTypeName: storeTypeName || String(product.storeTypeName ?? product.storeType ?? "").trim(),
    businessType: storeTypeName || String(product.businessType ?? product.storeType ?? "").trim(),
    planName,
    hasPaidPlan: false,
    isLegitSeller,
    legitimateBadge: isLegitSeller,
    companyAccountState,
    companyIsBanned,
    companyIsRestricted,
    isListingRestricted: isProductListingRestrictedForCustomers(product),
  };
}

function attachProductsCompanyMetadata(products, accounts = [], countsByAdminId = null) {
  const metadataByAdminId = getProductCompanyMetadataByAdminId(accounts, countsByAdminId);
  return (Array.isArray(products) ? products : []).map((product) =>
    attachProductCompanyMetadata(product, metadataByAdminId),
  );
}

function getEmployeeDashboardPath(accountOrPosition) {
  const account = accountOrPosition && typeof accountOrPosition === "object"
    ? accountOrPosition
    : null;
  const hasExplicitAccessPermissions =
    Boolean(account?.accessPermissionsConfigured);
  const hasStoredAccessPermissions =
    Array.isArray(account?.accessPermissions) && account.accessPermissions.length > 0;
  const accessPermissions = hasExplicitAccessPermissions || hasStoredAccessPermissions
    ? ensureRequiredEmployeeAccessPermissions(account.accessPermissions, account.position)
    : [];
  const normalizedPosition = String(account?.position ?? accountOrPosition ?? "").trim().toLowerCase();

  if (hasExplicitAccessPermissions || hasStoredAccessPermissions) {
    if (normalizedPosition === "packing") {
      return accessPermissions.includes("packing-dashboard")
        ? "/packing_dashboard.html"
        : "/employee_access_pending.html";
    }

    for (const [permissionKey, dashboardPath] of employeeAccessPermissionDashboardPaths) {
      if (accessPermissions.includes(permissionKey)) {
        return dashboardPath;
      }
    }

    return "/employee_access_pending.html";
  }

  if (normalizedPosition === "packing") {
    return "/packing_dashboard.html";
  }
  if (normalizedPosition) {
    return "/employee_dashboard.html";
  }

  return "/employee_access_pending.html";
}

function getAccountFaceProfileKey(account) {
  return String(account?.employeeId ?? account?.accountCode ?? account?.id ?? "")
    .trim()
    .toUpperCase();
}

function getFaceAttendanceSampleCount(profile) {
  const sampleCount = Number(profile?.sample_count ?? profile?.sampleCount ?? 0);
  if (Number.isFinite(sampleCount) && sampleCount > 0) {
    return Math.trunc(sampleCount);
  }

  const embeddings = profile?.embeddings;
  return Array.isArray(embeddings) ? embeddings.length : 0;
}

function getFaceAttendanceProfilesMap(faceAttendanceData = null) {
  if (faceAttendanceData instanceof Map) {
    return faceAttendanceData;
  }

  return faceAttendanceData?.profiles instanceof Map
    ? faceAttendanceData.profiles
    : null;
}

function getFaceAttendanceRecordsMap(faceAttendanceData = null) {
  return faceAttendanceData?.attendanceRecords instanceof Map
    ? faceAttendanceData.attendanceRecords
    : null;
}

function getFaceAttendanceRecordsForAccount(account, faceAttendanceData = null) {
  const recordsByEmployeeId = getFaceAttendanceRecordsMap(faceAttendanceData);
  if (!(recordsByEmployeeId instanceof Map)) {
    return [];
  }

  const accountKeys = getFaceAttendanceAccountKeys(account);
  for (const accountKey of accountKeys) {
    const records = recordsByEmployeeId.get(accountKey);
    if (Array.isArray(records)) {
      return records;
    }
  }

  return [];
}

function getRegisteredFaceProfile(account, faceAttendanceData = null) {
  const profileKey = getAccountFaceProfileKey(account);
  const faceAttendanceProfiles = getFaceAttendanceProfilesMap(faceAttendanceData);
  if (!profileKey || !(faceAttendanceProfiles instanceof Map)) {
    return null;
  }

  const profile = faceAttendanceProfiles.get(profileKey);
  if (!profile) {
    return null;
  }

  const sampleCount = getFaceAttendanceSampleCount(profile);
  if (sampleCount <= 0 && !profile.registered_at && !profile.registeredAt) {
    return null;
  }

  return {
    employeeId: String(profile.employee_id ?? profile.employeeId ?? profileKey).trim(),
    registeredAt: String(profile.registered_at ?? profile.registeredAt ?? "").trim(),
    sampleCount,
    source: "face_attendance_lh",
  };
}

function applyRegisteredFaceProfile(account, faceAttendanceData = null) {
  const registeredFaceProfile = getRegisteredFaceProfile(account, faceAttendanceData);
  const attendanceRecords = getFaceAttendanceRecordsForAccount(account, faceAttendanceData);
  if (!registeredFaceProfile && attendanceRecords.length === 0) {
    return account;
  }

  const faceAttendanceLh = {
    ...(registeredFaceProfile ?? {
      employeeId: String(account?.employeeId ?? account?.accountCode ?? account?.id ?? "").trim(),
      source: "face_attendance_lh",
    }),
    attendanceRecords,
    attendance_records: attendanceRecords,
  };

  return {
    ...account,
    faceVerified: registeredFaceProfile ? true : Boolean(account?.faceVerified),
    verifiedAt: registeredFaceProfile
      ? account?.verifiedAt || registeredFaceProfile.registeredAt || null
      : account?.verifiedAt,
    faceProfileRegistered: registeredFaceProfile ? true : Boolean(account?.faceProfileRegistered),
    registeredFaceProfile: registeredFaceProfile ?? account?.registeredFaceProfile ?? null,
    face_attendance_lh: faceAttendanceLh,
  };
}

function serializeEmployeeAccount(account, faceAttendanceData = null) {
  const safeAccount = applyRegisteredFaceProfile(account, faceAttendanceData);
  const accessPermissions = ensureRequiredEmployeeAccessPermissions(
    safeAccount.accessPermissions ?? [],
    safeAccount.position,
  );
  return {
    id: safeAccount.id,
    accountCode: safeAccount.accountCode,
    employeeId: safeAccount.employeeId,
    position: safeAccount.position,
    timeIn: safeAccount.timeIn,
    timeOut: safeAccount.timeOut,
    workHours: safeAccount.workHours,
    firstName: safeAccount.firstName,
    middleName: safeAccount.middleName,
    lastName: safeAccount.lastName,
    suffix: safeAccount.suffix,
    email: safeAccount.email,
    address: safeAccount.address,
    department: safeAccount.department || "",
    employmentType: safeAccount.employmentType || "Regular",
    dateOfBirth: safeAccount.dateOfBirth || "",
    gender: safeAccount.gender || "",
    startDate: safeAccount.startDate || "",
    supervisor: safeAccount.supervisor || "",
    username: safeAccount.username || safeAccount.email || "",
    employeeRole: safeAccount.employeeRole || "Employee",
    status: safeAccount.status || "active",
    countryCode: safeAccount.countryCode,
    mobileNumber: safeAccount.mobileNumber,
    profileImageUrl: safeAccount.profileImageUrl || "",
    gmailBinding: safeAccount.gmailBinding || null,
    accessPermissions,
    accessPermissionGrantedAt: normalizeEmployeeAccessPermissionGrantMap(
      safeAccount.accessPermissionGrantedAt,
      accessPermissions,
      getEmployeeAccessGrantFallbackTimestamp(safeAccount),
    ),
    accessPermissionsConfigured: Boolean(safeAccount.accessPermissionsConfigured),
    role: safeAccount.role,
    source: safeAccount.source,
    faceVerified: Boolean(safeAccount.faceVerified),
    verifiedAt: safeAccount.verifiedAt,
    passwordUpdatedAt: safeAccount.passwordUpdatedAt ?? null,
    updatedAt: safeAccount.updatedAt ?? safeAccount.createdAt ?? null,
    adminId: getRecordAdminId(safeAccount),
    faceProfileRegistered: Boolean(safeAccount.faceProfileRegistered),
    registeredFaceProfile: safeAccount.registeredFaceProfile ?? null,
    face_attendance_lh: safeAccount.face_attendance_lh ?? null,
  };
}

function serializeAccountForList(account, faceAttendanceData = null) {
  const accountWithFaceProfile = applyRegisteredFaceProfile(account, faceAttendanceData);
  const { password, ...safeAccount } = accountWithFaceProfile || {};
  const accessPermissions = ensureRequiredEmployeeAccessPermissions(
    safeAccount.accessPermissions ?? [],
    safeAccount.position,
  );
  return {
    ...safeAccount,
    adminId: getRecordAdminId(safeAccount),
    accessPermissions,
    accessPermissionGrantedAt: normalizeEmployeeAccessPermissionGrantMap(
      safeAccount.accessPermissionGrantedAt,
      accessPermissions,
      getEmployeeAccessGrantFallbackTimestamp(safeAccount),
    ),
  };
}

function sanitizeFileStem(value) {
  return String(value)
    .toLowerCase()
    .replace(/[^a-z0-9_-]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 50);
}

function getUploadExtension(filename, contentType) {
  const filenameExtension = path.extname(filename ?? "").toLowerCase();
  if (
    MIME_TYPES[filenameExtension]?.startsWith("image/") ||
    MIME_TYPES[filenameExtension]?.startsWith("video/") ||
    MIME_TYPES[filenameExtension]?.startsWith("model/") ||
    filenameExtension === ".fbx" ||
    filenameExtension === ".obj"
  ) {
    return filenameExtension;
  }

  switch (normalizeUploadMimeType(contentType)) {
    case "image/jpeg":
      return ".jpg";
    case "image/png":
      return ".png";
    case "image/webp":
      return ".webp";
    case "image/svg+xml":
      return ".svg";
    case "image/gif":
      return ".gif";
    case "video/mp4":
      return ".mp4";
    case "video/quicktime":
      return ".mov";
    case "video/x-m4v":
      return ".m4v";
    case "video/webm":
      return ".webm";
    case "video/x-msvideo":
      return ".avi";
    case "video/x-matroska":
      return ".mkv";
    case "video/3gpp":
      return ".3gp";
    case "model/gltf-binary":
      return ".glb";
    case "model/gltf+json":
      return ".gltf";
    default:
      return "";
  }
}

function isImageUploadType(contentType, extension) {
  const normalizedContentType = String(contentType ?? "").toLowerCase();
  if (normalizedContentType.startsWith("image/")) {
    return true;
  }

  return MIME_TYPES[String(extension ?? "").toLowerCase()]?.startsWith("image/") ?? false;
}

function isModelUploadType(contentType, extension) {
  const normalizedContentType = String(contentType ?? "").toLowerCase();
  if (normalizedContentType.startsWith("model/")) {
    return true;
  }

  return [".glb", ".gltf", ".obj", ".fbx"].includes(
    String(extension ?? "").toLowerCase(),
  );
}

async function convertUploadedImageToWebp(fileBuffer) {
  if (!sharp) {
    throw new Error(
      'Image upload conversion is unavailable because the "sharp" package is not installed.',
    );
  }

  try {
    return await sharp(fileBuffer, {
      animated: true,
    })
      .rotate()
      .webp({
        quality: UPLOAD_IMAGE_WEBP_QUALITY,
        effort: UPLOAD_IMAGE_WEBP_EFFORT,
      })
      .toBuffer();
  } catch (error) {
    throw new Error("Unable to convert the uploaded image to WebP.");
  }
}

function normalizeUploadMimeType(contentType) {
  return String(contentType ?? "")
    .split(";")[0]
    .trim()
    .toLowerCase();
}

function isSvgUploadBuffer(fileBuffer) {
  if (!Buffer.isBuffer(fileBuffer) || fileBuffer.length === 0) {
    return false;
  }
  const sampleSize = Math.min(fileBuffer.length, 1024);
  const head = fileBuffer.subarray(0, sampleSize).toString("utf8").trimStart().toLowerCase();
  if (head.startsWith("<svg")) {
    return true;
  }
  return head.startsWith("<?xml") && head.includes("<svg");
}

function shouldStoreUploadedImageAsPng(contentType, extension) {
  return (
    normalizeUploadMimeType(contentType) === "image/png" ||
    String(extension ?? "").toLowerCase() === ".png"
  );
}

function shouldStoreUploadedImageAsSvg(contentType, extension, fileBuffer = null) {
  if (
    normalizeUploadMimeType(contentType) === "image/svg+xml" ||
    String(extension ?? "").toLowerCase() === ".svg"
  ) {
    return true;
  }
  return isSvgUploadBuffer(fileBuffer);
}

function shouldPreserveUploadedImageFormat(contentType, extension, fileBuffer = null) {
  return (
    shouldStoreUploadedImageAsPng(contentType, extension) ||
    shouldStoreUploadedImageAsSvg(contentType, extension, fileBuffer)
  );
}

async function createVisualSearchFingerprint(fileBuffer) {
  if (!sharp) {
    throw new Error(
      'Visual product search is unavailable because the "sharp" package is not installed.',
    );
  }

  try {
    return await createVisualSearchFingerprintFromBuffer(fileBuffer, {
      trimEdges: true,
    });
  } catch (error) {
    try {
      return await createVisualSearchFingerprintFromBuffer(fileBuffer, {
        trimEdges: false,
      });
    } catch (_) {
      throw new Error("Unable to read the product photo for visual search.");
    }
  }
}

async function createVisualSearchFingerprintFromBuffer(fileBuffer, options = {}) {
  let pipeline = sharp(fileBuffer, {
    animated: false,
    failOn: "none",
  }).rotate();

  if (options.trimEdges) {
    pipeline = pipeline.trim({ threshold: 10 });
  }

  const { data } = await pipeline
    .resize(VISUAL_SEARCH_VECTOR_SIZE, VISUAL_SEARCH_VECTOR_SIZE, {
      fit: "fill",
    })
    .removeAlpha()
    .toColourspace("srgb")
    .normalize()
    .gamma()
    .sharpen()
    .raw()
    .toBuffer({ resolveWithObject: true });

  return data;
}

async function createVisualSearchNormalizedImageBuffer(fileBuffer) {
  const { data, info } = await sharp(fileBuffer, {
    animated: false,
    failOn: "none",
  })
    .rotate()
    .jpeg({ quality: 92 })
    .toBuffer({ resolveWithObject: true });

  return {
    buffer: data,
    width: Number(info?.width ?? 0),
    height: Number(info?.height ?? 0),
  };
}

function buildVisualSearchCenterCropRect(imageWidth, imageHeight, widthRatio, heightRatio) {
  const sourceWidth = Math.max(1, Math.floor(Number(imageWidth) || 0));
  const sourceHeight = Math.max(1, Math.floor(Number(imageHeight) || 0));
  const cropWidth = Math.max(
    1,
    Math.min(sourceWidth, Math.round(sourceWidth * Number(widthRatio || 1))),
  );
  const cropHeight = Math.max(
    1,
    Math.min(sourceHeight, Math.round(sourceHeight * Number(heightRatio || 1))),
  );

  return {
    left: Math.max(0, Math.floor((sourceWidth - cropWidth) / 2)),
    top: Math.max(0, Math.floor((sourceHeight - cropHeight) / 2)),
    width: cropWidth,
    height: cropHeight,
  };
}

async function createVisualSearchQueryFingerprints(fileBuffer) {
  const fingerprints = [];
  const seenFingerprints = new Set();

  async function addFingerprintFromBuffer(sourceBuffer) {
    const fingerprint = await createVisualSearchFingerprint(sourceBuffer);
    const fingerprintKey = fingerprint.toString("base64");
    if (seenFingerprints.has(fingerprintKey)) {
      return;
    }

    seenFingerprints.add(fingerprintKey);
    fingerprints.push(fingerprint);
  }

  await addFingerprintFromBuffer(fileBuffer);

  let normalizedImage = null;
  try {
    normalizedImage = await createVisualSearchNormalizedImageBuffer(fileBuffer);
  } catch (error) {
    return fingerprints;
  }

  if (normalizedImage.width < 96 || normalizedImage.height < 96) {
    return fingerprints;
  }

  for (const cropRatio of VISUAL_SEARCH_QUERY_CROP_RATIOS) {
    const cropRect = buildVisualSearchCenterCropRect(
      normalizedImage.width,
      normalizedImage.height,
      cropRatio.width,
      cropRatio.height,
    );

    if (
      cropRect.width >= normalizedImage.width &&
      cropRect.height >= normalizedImage.height
    ) {
      continue;
    }

    try {
      const cropBuffer = await sharp(normalizedImage.buffer, {
        animated: false,
        failOn: "none",
      })
        .extract(cropRect)
        .jpeg({ quality: 92 })
        .toBuffer();
      await addFingerprintFromBuffer(cropBuffer);
    } catch (error) {
      // Keep the remaining search candidates; one bad crop should not fail search.
    }
  }

  for (const rotationDegrees of VISUAL_SEARCH_QUERY_ROTATION_DEGREES) {
    try {
      const rotatedBuffer = await sharp(normalizedImage.buffer, {
        animated: false,
        failOn: "none",
      })
        .rotate(rotationDegrees)
        .jpeg({ quality: 92 })
        .toBuffer();
      await addFingerprintFromBuffer(rotatedBuffer);
    } catch (error) {
      // Rotation variants are best-effort for landscape or sideways captures.
    }
  }

  return fingerprints;
}

function createVisualSearchFingerprintMeta(fingerprint, imageUrl) {
  if (
    !Buffer.isBuffer(fingerprint) ||
    fingerprint.length !== VISUAL_SEARCH_FINGERPRINT_LENGTH
  ) {
    return null;
  }

  return {
    version: VISUAL_SEARCH_FINGERPRINT_VERSION,
    imageUrl: String(imageUrl ?? "").trim(),
    vectorSize: VISUAL_SEARCH_VECTOR_SIZE,
    data: fingerprint.toString("base64"),
    updatedAt: new Date().toISOString(),
  };
}

function normalizeVisualSearchFingerprintMeta(value, imageUrl) {
  const normalizedImageUrl = String(imageUrl ?? "").trim();
  if (!value || typeof value !== "object" || !normalizedImageUrl) {
    return null;
  }

  const version = String(value.version ?? "").trim();
  const fingerprintImageUrl = String(value.imageUrl ?? "").trim();
  const data = String(value.data ?? "").trim();
  const vectorSize = Number(value.vectorSize ?? 0);

  if (
    version !== VISUAL_SEARCH_FINGERPRINT_VERSION ||
    fingerprintImageUrl !== normalizedImageUrl ||
    vectorSize !== VISUAL_SEARCH_VECTOR_SIZE ||
    !data
  ) {
    return null;
  }

  try {
    const fingerprint = Buffer.from(data, "base64");
    if (fingerprint.length !== VISUAL_SEARCH_FINGERPRINT_LENGTH) {
      return null;
    }
  } catch (error) {
    return null;
  }

  return {
    version,
    imageUrl: fingerprintImageUrl,
    vectorSize,
    data,
    updatedAt: normalizeOptionalProductDateTime(value.updatedAt) || "",
  };
}

function normalizeProductVisualSearchImageAngles(product = {}) {
  const imageAngles = {};
  for (const angleKey of VISUAL_SEARCH_IMAGE_ANGLE_KEYS) {
    imageAngles[angleKey] = "";
  }

  const rawAngles = product?.visualSearchImageAngles;
  if (rawAngles && typeof rawAngles === "object" && !Array.isArray(rawAngles)) {
    for (const [rawKey, rawUrl] of Object.entries(rawAngles)) {
      const angleKey = normalizeVisualSearchImageAngleKey(rawKey);
      if (angleKey) {
        imageAngles[angleKey] = String(rawUrl ?? "").trim();
      }
    }
  }

  const rawUrls = Array.isArray(product?.visualSearchImageUrls)
    ? product.visualSearchImageUrls
    : [];
  rawUrls.forEach((url, index) => {
    const angleKey =
      VISUAL_SEARCH_IMAGE_ANGLE_KEYS[index] ??
      createVisualSearchOtherImageKey(
        index - VISUAL_SEARCH_IMAGE_ANGLE_KEYS.length + 1,
      );
    if (angleKey && !imageAngles[angleKey]) {
      imageAngles[angleKey] = String(url ?? "").trim();
    }
  });

  const legacyUrl = String(product?.visualSearchImageUrl ?? "").trim();
  if (legacyUrl && !imageAngles[VISUAL_SEARCH_PRIMARY_IMAGE_ANGLE]) {
    imageAngles[VISUAL_SEARCH_PRIMARY_IMAGE_ANGLE] = legacyUrl;
  }

  return imageAngles;
}

function isVisualSearchOtherImageKey(value) {
  return new RegExp(`^${VISUAL_SEARCH_OTHER_IMAGE_PREFIX}\\d+$`).test(
    String(value ?? "").trim().toLowerCase(),
  );
}

function createVisualSearchOtherImageKey(index) {
  return `${VISUAL_SEARCH_OTHER_IMAGE_PREFIX}${Math.max(1, Number(index) || 1)}`;
}

function getVisualSearchOtherImageIndex(angleKey) {
  const match = String(angleKey ?? "")
    .trim()
    .toLowerCase()
    .match(new RegExp(`^${VISUAL_SEARCH_OTHER_IMAGE_PREFIX}(\\d+)$`));
  return match ? Number(match[1]) : 0;
}

function normalizeVisualSearchImageAngleKey(value) {
  const requestedKey = String(value ?? "").trim().toLowerCase();
  if (VISUAL_SEARCH_IMAGE_ANGLE_KEYS.includes(requestedKey)) {
    return requestedKey;
  }

  if (isVisualSearchOtherImageKey(requestedKey)) {
    return requestedKey;
  }

  return "";
}

function getProductVisualSearchImageAngleKeys(imageAngles = {}) {
  const otherKeys = Object.keys(imageAngles)
    .filter((angleKey) => {
      const url = String(imageAngles?.[angleKey] ?? "").trim();
      return url && isVisualSearchOtherImageKey(angleKey);
    })
    .sort(
      (first, second) =>
        getVisualSearchOtherImageIndex(first) -
        getVisualSearchOtherImageIndex(second),
    );

  return [...VISUAL_SEARCH_IMAGE_ANGLE_KEYS, ...otherKeys];
}

function getProductVisualSearchImageUrlsFromAngles(imageAngles = {}) {
  const urls = [];
  const seen = new Set();

  for (const angleKey of getProductVisualSearchImageAngleKeys(imageAngles)) {
    const url = String(imageAngles?.[angleKey] ?? "").trim();
    const normalizedKey = url.toLowerCase();
    if (!url || seen.has(normalizedKey)) {
      continue;
    }

    seen.add(normalizedKey);
    urls.push(url);
  }

  return urls;
}

function normalizeProductVisualSearchImageUrls(product = {}) {
  return getProductVisualSearchImageUrlsFromAngles(
    normalizeProductVisualSearchImageAngles(product),
  );
}

function getPrimaryProductVisualSearchImageUrl(product = {}) {
  const imageAngles = normalizeProductVisualSearchImageAngles(product);
  return (
    String(imageAngles[VISUAL_SEARCH_PRIMARY_IMAGE_ANGLE] ?? "").trim() ||
    getProductVisualSearchImageUrlsFromAngles(imageAngles)[0] ||
    ""
  );
}

function normalizeVisualSearchFingerprintMetaList(value, imageUrls = []) {
  const sourceFingerprints = Array.isArray(value) ? value : [];

  return imageUrls
    .map((imageUrl, index) => {
      const normalizedUrl = String(imageUrl ?? "").trim();
      const matchingMeta = sourceFingerprints.find(
        (candidate) =>
          String(candidate?.imageUrl ?? "").trim().toLowerCase() ===
          normalizedUrl.toLowerCase(),
      );

      return normalizeVisualSearchFingerprintMeta(
        matchingMeta ?? sourceFingerprints[index],
        normalizedUrl,
      );
    })
    .filter(Boolean);
}

function findVisualSearchFingerprintMetaForUrl(sources, imageUrl) {
  const normalizedImageUrl = String(imageUrl ?? "").trim();
  if (!normalizedImageUrl) {
    return null;
  }

  for (const source of sources) {
    const normalizedMeta = normalizeVisualSearchFingerprintMeta(
      source,
      normalizedImageUrl,
    );
    if (normalizedMeta) {
      return normalizedMeta;
    }
  }

  return null;
}

function getStoredVisualSearchFingerprint(product) {
  const visualSearchImageUrl = String(product?.visualSearchImageUrl ?? "").trim();
  const fingerprintMeta = normalizeVisualSearchFingerprintMeta(
    product?.visualSearchFingerprint,
    visualSearchImageUrl,
  );

  if (!fingerprintMeta) {
    return null;
  }

  try {
    const fingerprint = Buffer.from(fingerprintMeta.data, "base64");
    return fingerprint.length === VISUAL_SEARCH_FINGERPRINT_LENGTH ? fingerprint : null;
  } catch (error) {
    return null;
  }
}

function getStoredVisualSearchFingerprintEntries(product) {
  const imageUrls = normalizeProductVisualSearchImageUrls(product);
  const fingerprintMetas = normalizeVisualSearchFingerprintMetaList(
    product?.visualSearchFingerprints,
    imageUrls,
  );
  const entries = [];

  for (const imageUrl of imageUrls) {
    const fingerprintMeta =
      fingerprintMetas.find(
        (meta) =>
          String(meta?.imageUrl ?? "").trim().toLowerCase() ===
          String(imageUrl ?? "").trim().toLowerCase(),
      ) ||
      normalizeVisualSearchFingerprintMeta(
        product?.visualSearchFingerprint,
        imageUrl,
      );

    if (!fingerprintMeta) {
      continue;
    }

    try {
      const fingerprint = Buffer.from(fingerprintMeta.data, "base64");
      if (fingerprint.length === VISUAL_SEARCH_FINGERPRINT_LENGTH) {
        entries.push({
          imageUrl,
          fingerprint,
          fingerprintMeta,
        });
      }
    } catch (error) {
      // Ignore corrupt fingerprint metadata and let the caller rebuild it.
    }
  }

  return entries;
}

async function createProductVisualSearchFingerprintMeta(product, imageUrl = null) {
  const visualSearchImageUrl = String(
    imageUrl ?? product?.visualSearchImageUrl ?? "",
  ).trim();
  if (!visualSearchImageUrl) {
    return null;
  }

  try {
    const imageBuffer = await readPublicImageBuffer(visualSearchImageUrl);
    if (!imageBuffer) {
      return null;
    }
    const fingerprint = await createVisualSearchFingerprint(imageBuffer);
    return createVisualSearchFingerprintMeta(fingerprint, visualSearchImageUrl);
  } catch (error) {
    return null;
  }
}

async function syncProductVisualSearchFingerprint(product, existingProduct = null) {
  const visualSearchImageAngles = normalizeProductVisualSearchImageAngles(product);
  const visualSearchImageUrls =
    getProductVisualSearchImageUrlsFromAngles(visualSearchImageAngles);
  const visualSearchImageUrl = getPrimaryProductVisualSearchImageUrl(product);
  if (!visualSearchImageUrls.length) {
    return {
      ...product,
      visualSearchImageUrl: "",
      visualSearchImageUrls: [],
      visualSearchImageAngles: {},
      visualSearchFingerprint: null,
      visualSearchFingerprints: [],
    };
  }

  const sourceFingerprintMetas = [
    ...normalizeVisualSearchFingerprintMetaList(
      product?.visualSearchFingerprints,
      visualSearchImageUrls,
    ),
    ...normalizeVisualSearchFingerprintMetaList(
      existingProduct?.visualSearchFingerprints,
      visualSearchImageUrls,
    ),
  ];
  const sourceSingleFingerprints = [
    product?.visualSearchFingerprint,
    existingProduct?.visualSearchFingerprint,
  ];
  const nextFingerprintMetas = [];

  for (const candidateImageUrl of visualSearchImageUrls) {
    let fingerprintMeta = findVisualSearchFingerprintMetaForUrl(
      [
        ...sourceFingerprintMetas,
        ...(candidateImageUrl === visualSearchImageUrl ? sourceSingleFingerprints : []),
      ],
      candidateImageUrl,
    );

    if (!fingerprintMeta) {
      fingerprintMeta = await createProductVisualSearchFingerprintMeta(
        product,
        candidateImageUrl,
      );
    }

    if (fingerprintMeta) {
      nextFingerprintMetas.push(fingerprintMeta);
    }
  }

  return {
    ...product,
    visualSearchImageUrl,
    visualSearchImageUrls,
    visualSearchImageAngles,
    visualSearchFingerprint: nextFingerprintMetas[0] ?? null,
    visualSearchFingerprints: nextFingerprintMetas,
  };
}

function compareVisualSearchFingerprints(firstFingerprint, secondFingerprint) {
  if (
    !Buffer.isBuffer(firstFingerprint) ||
    !Buffer.isBuffer(secondFingerprint) ||
    firstFingerprint.length === 0 ||
    firstFingerprint.length !== secondFingerprint.length
  ) {
    return 0;
  }

  let differenceTotal = 0;
  for (let index = 0; index < firstFingerprint.length; index += 1) {
    differenceTotal += Math.abs(firstFingerprint[index] - secondFingerprint[index]);
  }

  const averageDifference = differenceTotal / firstFingerprint.length;
  return Math.max(0, Math.min(1, 1 - averageDifference / 255));
}

function resolvePublicFilePath(fileUrl) {
  const rawUrl = String(fileUrl ?? "").trim();
  if (!rawUrl || rawUrl.startsWith("data:")) {
    return "";
  }

  let pathname = rawUrl;
  try {
    const parsedUrl = new URL(rawUrl, `http://127.0.0.1:${PORT}`);
    pathname = parsedUrl.pathname;
  } catch (error) {
    pathname = rawUrl;
  }

  let decodedPathname = "";
  try {
    decodedPathname = decodeURIComponent(pathname);
  } catch (error) {
    return "";
  }

  const normalizedRelativePath = path
    .normalize(decodedPathname.replace(/^[/\\]+/, ""))
    .replace(/^(\.\.[/\\])+/, "");
  const resolvedPublicDir = path.resolve(PUBLIC_DIR);
  const resolvedFilePath = path.resolve(PUBLIC_DIR, normalizedRelativePath);

  if (
    resolvedFilePath !== resolvedPublicDir &&
    !resolvedFilePath.startsWith(`${resolvedPublicDir}${path.sep}`)
  ) {
    return "";
  }

  const extension = path.extname(resolvedFilePath).toLowerCase();
  if (!MIME_TYPES[extension]?.startsWith("image/")) {
    return "";
  }

  return resolvedFilePath;
}

async function readPublicImageBuffer(fileUrl) {
  const filePath = resolvePublicFilePath(fileUrl);
  if (!filePath) {
    return null;
  }
  try {
    return await fsPromises.readFile(filePath);
  } catch (error) {
    if (path.dirname(filePath) !== path.resolve(UPLOADS_DIR)) {
      return null;
    }
    return objectStorage.readUpload(path.basename(filePath));
  }
}

function getProductVisualSearchImageUrls(product) {
  const urls = [];
  const seen = new Set();

  function addUrl(value) {
    const url = String(value ?? "").trim();
    const key = url.toLowerCase();
    if (!url || seen.has(key)) {
      return;
    }

    seen.add(key);
    urls.push(url);
  }

  for (const imageUrl of normalizeProductVisualSearchImageUrls(product)) {
    addUrl(imageUrl);
  }
  addUrl(product?.visualSearchImageUrl);
  addUrl(product?.imageUrl);
  addUrl(product?.mainImageUrl);
  addUrl(product?.cardImageUrl);
  addUrl(product?.buyModalImageUrl);

  for (const imageUrl of product?.imageUrls ?? []) {
    addUrl(imageUrl);
  }

  for (const imageUrl of normalizeProductDescriptionImageUrls(product?.descriptionImageUrls)) {
    addUrl(imageUrl);
  }

  for (const crop of product?.detailsImageCrops ?? []) {
    addUrl(crop?.croppedImageUrl);
    addUrl(crop?.sourceUrl);
  }

  for (const variant of product?.variants ?? []) {
    addUrl(variant?.imageUrl);
    addUrl(variant?.imageSourceUrl);
  }

  return urls;
}

function getDocumentUploadExtension(filename, contentType) {
  const filenameExtension = path.extname(filename ?? "").toLowerCase();
  if ([".pdf", ".doc", ".docx"].includes(filenameExtension)) {
    return filenameExtension;
  }

  switch (String(contentType ?? "").toLowerCase()) {
    case "application/pdf":
      return ".pdf";
    case "application/msword":
      return ".doc";
    case "application/vnd.openxmlformats-officedocument.wordprocessingml.document":
      return ".docx";
    default:
      return "";
  }
}

function isVideoAttachmentSource(url, name = "") {
  const normalizedUrl = String(url ?? "").trim().toLowerCase();
  const normalizedName = String(name ?? "").trim().toLowerCase();
  const videoExtensions = [".mp4", ".mov", ".m4v", ".webm", ".avi", ".mkv", ".3gp"];

  return videoExtensions.some(
    (extension) =>
      normalizedUrl.endsWith(extension) || normalizedName.endsWith(extension),
  );
}

function normalizeProductImageUrls(rawImageUrls, fallbackImageUrl = "") {
  const submittedImageUrls = Array.isArray(rawImageUrls) ? rawImageUrls : [];
  const seen = new Set();
  const normalizedImageUrls = [];

  for (const candidate of submittedImageUrls) {
    const imageUrl = String(candidate ?? "").trim();
    const normalizedKey = imageUrl.toLowerCase();

    if (!imageUrl || seen.has(normalizedKey)) {
      continue;
    }

    seen.add(normalizedKey);
    normalizedImageUrls.push(imageUrl);
  }

  const trimmedFallbackImageUrl = String(fallbackImageUrl ?? "").trim();
  if (!normalizedImageUrls.length && trimmedFallbackImageUrl) {
    normalizedImageUrls.push(trimmedFallbackImageUrl);
  }

  return normalizedImageUrls;
}

function normalizeUploadsRelativeProductImageUrls(rawImageUrls = []) {
  const normalizedImageUrls = normalizeProductImageUrls(rawImageUrls);
  const allowlistedImageUrls = [];
  const seen = new Set();

  for (const imageUrl of normalizedImageUrls) {
    let relativePath = "";
    try {
      const parsedUrl = new URL(imageUrl, `http://127.0.0.1:${PORT}`);
      relativePath = `${parsedUrl.pathname}${parsedUrl.search}${parsedUrl.hash}`;
    } catch (_) {
      relativePath = imageUrl;
    }

    const trimmedPath = String(relativePath || "").trim();
    if (!trimmedPath.startsWith("/uploads/")) {
      continue;
    }
    const normalizedKey = trimmedPath.toLowerCase();
    if (seen.has(normalizedKey)) {
      continue;
    }
    seen.add(normalizedKey);
    allowlistedImageUrls.push(trimmedPath);
  }

  return allowlistedImageUrls;
}

function normalizeProductDescriptionImageUrls(rawImageUrls, fallbackImageUrls = []) {
  const sourceImageUrls = Array.isArray(rawImageUrls)
    ? rawImageUrls
    : Array.isArray(fallbackImageUrls)
      ? fallbackImageUrls
      : [];
  const seen = new Set();
  const normalizedImageUrls = [];

  for (const candidate of sourceImageUrls) {
    const imageUrl = String(candidate ?? "").trim();
    const normalizedKey = imageUrl.toLowerCase();
    if (
      !imageUrl ||
      imageUrl.length > MAX_PRODUCT_DESCRIPTION_IMAGE_URL_LENGTH ||
      seen.has(normalizedKey)
    ) {
      continue;
    }

    seen.add(normalizedKey);
    normalizedImageUrls.push(imageUrl);
    if (normalizedImageUrls.length >= MAX_PRODUCT_DESCRIPTION_IMAGE_URLS) {
      break;
    }
  }

  return normalizedImageUrls;
}

function validateProductDescriptionImageUrls(rawImageUrls) {
  if (!Array.isArray(rawImageUrls)) {
    throw new Error("Description images must be submitted as an array.");
  }

  for (const candidate of rawImageUrls) {
    if (candidate != null && typeof candidate !== "string") {
      throw new Error("Each description image must be an uploaded image URL.");
    }
    const imageUrl = String(candidate ?? "").trim();
    if (imageUrl.length > MAX_PRODUCT_DESCRIPTION_IMAGE_URL_LENGTH) {
      throw new Error(
        `Each description image URL must be ${MAX_PRODUCT_DESCRIPTION_IMAGE_URL_LENGTH} characters or fewer.`,
      );
    }
  }

  const normalizedImageUrls = normalizeProductImageUrls(rawImageUrls);
  if (normalizedImageUrls.length > MAX_PRODUCT_DESCRIPTION_IMAGE_URLS) {
    throw new Error(
      `A product can have up to ${MAX_PRODUCT_DESCRIPTION_IMAGE_URLS} description images.`,
    );
  }
}

function normalizeProductVideoUrls(rawVideoUrls, fallbackVideoUrl = "") {
  const submittedVideoUrls = Array.isArray(rawVideoUrls) ? rawVideoUrls : [];
  const seen = new Set();
  const normalizedVideoUrls = [];

  for (const candidate of submittedVideoUrls) {
    const videoUrl = String(candidate ?? "").trim();
    const normalizedKey = videoUrl.toLowerCase();

    if (!videoUrl || seen.has(normalizedKey)) {
      continue;
    }

    seen.add(normalizedKey);
    normalizedVideoUrls.push(videoUrl);
  }

  const trimmedFallbackVideoUrl = String(fallbackVideoUrl ?? "").trim();
  if (!normalizedVideoUrls.length && trimmedFallbackVideoUrl) {
    normalizedVideoUrls.push(trimmedFallbackVideoUrl);
  }

  return normalizedVideoUrls;
}

function normalizeProductVideoThumbnailUrls(
  rawVideoThumbnailUrls,
  videoUrls,
  fallbackVideoThumbnailUrl = "",
) {
  const normalizedVideoUrls = Array.isArray(videoUrls) ? videoUrls : [];
  if (!normalizedVideoUrls.length) {
    return [];
  }

  const submittedThumbnailUrls = Array.isArray(rawVideoThumbnailUrls)
    ? rawVideoThumbnailUrls
    : [];
  const trimmedFallbackThumbnailUrl = String(fallbackVideoThumbnailUrl ?? "").trim();

  return normalizedVideoUrls.map((_, slotIndex) => {
    const submittedThumbnailUrl = String(submittedThumbnailUrls[slotIndex] ?? "").trim();
    if (submittedThumbnailUrl) {
      return submittedThumbnailUrl;
    }

    return slotIndex === 0 ? trimmedFallbackThumbnailUrl : "";
  });
}

function normalizeProductModelScanImageUrls(rawImageUrls = []) {
  const submittedImageUrls = Array.isArray(rawImageUrls) ? rawImageUrls : [];
  const seen = new Set();
  const normalizedImageUrls = [];

  for (const candidate of submittedImageUrls) {
    const imageUrl = String(candidate ?? "").trim();
    const normalizedKey = imageUrl.toLowerCase();
    if (!imageUrl || seen.has(normalizedKey)) {
      continue;
    }

    seen.add(normalizedKey);
    normalizedImageUrls.push(imageUrl);
  }

  return normalizedImageUrls;
}

function normalizeProductModelFrameKey(value) {
  const normalizedValue = String(value ?? "").trim().toLowerCase();
  switch (normalizedValue) {
    case "front":
      return "front";
    case "right":
    case "right-side":
    case "right_side":
      return "right";
    case "back":
      return "back";
    case "left":
    case "left-side":
    case "left_side":
      return "left";
    case "top":
    case "up":
      return "top";
    case "bottom":
    case "down":
    case "detail":
      return "bottom";
    default:
      return "";
  }
}

function normalizeProductModelFrameInputs(input) {
  const framesByKey = new Map();
  const rawFrames = Array.isArray(input?.frames) ? input.frames : [];
  const rawImageUrls = Array.isArray(input?.imageUrls) ? input.imageUrls : [];

  for (const [index, rawFrame] of rawFrames.entries()) {
    const frameKey =
      normalizeProductModelFrameKey(rawFrame?.key ?? rawFrame?.angle) ||
      PRODUCT_MODEL_FRAME_ORDER[index] ||
      "";
    const imageUrl = String(rawFrame?.imageUrl ?? rawFrame?.url ?? "").trim();
    if (frameKey && imageUrl) {
      framesByKey.set(frameKey, imageUrl);
    }
  }

  for (const [index, rawImageUrl] of rawImageUrls.entries()) {
    const frameKey = PRODUCT_MODEL_FRAME_ORDER[index] || "";
    const imageUrl = String(rawImageUrl ?? "").trim();
    if (frameKey && imageUrl && !framesByKey.has(frameKey)) {
      framesByKey.set(frameKey, imageUrl);
    }
  }

  return PRODUCT_MODEL_FRAME_ORDER.map((key) => ({
    key,
    imageUrl: String(framesByKey.get(key) ?? "").trim(),
  }));
}

function clampNumber(value, min, max) {
  const numberValue = Number(value);
  if (!Number.isFinite(numberValue)) {
    return min;
  }

  return Math.min(Math.max(numberValue, min), max);
}

function createProductModelBufferViewState() {
  return {
    chunks: [],
    bufferViews: [],
    byteLength: 0,
  };
}

function appendProductModelBuffer(state, buffer, target) {
  const padding = (4 - (state.byteLength % 4)) % 4;
  if (padding) {
    state.chunks.push(Buffer.alloc(padding));
    state.byteLength += padding;
  }

  const bufferViewIndex = state.bufferViews.length;
  state.bufferViews.push({
    buffer: 0,
    byteOffset: state.byteLength,
    byteLength: buffer.length,
    target,
  });
  state.chunks.push(buffer);
  state.byteLength += buffer.length;
  return bufferViewIndex;
}

function createFloat32Buffer(values) {
  const buffer = Buffer.alloc(values.length * 4);
  values.forEach((value, index) => {
    buffer.writeFloatLE(value, index * 4);
  });
  return buffer;
}

function createUint16Buffer(values) {
  const buffer = Buffer.alloc(values.length * 2);
  values.forEach((value, index) => {
    buffer.writeUInt16LE(value, index * 2);
  });
  return buffer;
}

function getProductModelVectorBounds(values) {
  const min = [Infinity, Infinity, Infinity];
  const max = [-Infinity, -Infinity, -Infinity];

  for (let index = 0; index < values.length; index += 3) {
    for (let axis = 0; axis < 3; axis += 1) {
      const value = values[index + axis];
      min[axis] = Math.min(min[axis], value);
      max[axis] = Math.max(max[axis], value);
    }
  }

  return { min, max };
}

function getProductModelDimensions(frameMetadataByKey) {
  const frontMetadata = frameMetadataByKey.front ?? {};
  const rightMetadata = frameMetadataByKey.right ?? {};
  const topMetadata = frameMetadataByKey.top ?? {};
  const frontAspect =
    Number(frontMetadata.width || 0) > 0 && Number(frontMetadata.height || 0) > 0
      ? frontMetadata.width / frontMetadata.height
      : 0.72;
  const rightAspect =
    Number(rightMetadata.width || 0) > 0 && Number(rightMetadata.height || 0) > 0
      ? rightMetadata.width / rightMetadata.height
      : 0.42;
  const topAspect =
    Number(topMetadata.width || 0) > 0 && Number(topMetadata.height || 0) > 0
      ? topMetadata.width / topMetadata.height
      : 0;

  const height = 2;
  const width = clampNumber(frontAspect * height, 0.72, 3);
  const sideDepth = clampNumber(rightAspect * height, 0.34, 2.2);
  const topDepth = topAspect > 0 ? clampNumber(width / topAspect, 0.34, 2.2) : sideDepth;
  const depth = clampNumber(sideDepth * 0.65 + topDepth * 0.35, 0.34, 2.2);

  return { width, height, depth };
}

function createTexturedProductBoxGltf(textureFileNames, frameMetadataByKey) {
  const { width, height, depth } = getProductModelDimensions(frameMetadataByKey);
  const x = width / 2;
  const y = height / 2;
  const z = depth / 2;
  const positions = [];
  const normals = [];
  const texcoords = [];
  const indices = [];
  const faceDefinitions = [
    {
      key: "front",
      normal: [0, 0, 1],
      vertices: [[-x, -y, z], [x, -y, z], [x, y, z], [-x, y, z]],
    },
    {
      key: "right",
      normal: [1, 0, 0],
      vertices: [[x, -y, z], [x, -y, -z], [x, y, -z], [x, y, z]],
    },
    {
      key: "back",
      normal: [0, 0, -1],
      vertices: [[x, -y, -z], [-x, -y, -z], [-x, y, -z], [x, y, -z]],
    },
    {
      key: "left",
      normal: [-1, 0, 0],
      vertices: [[-x, -y, -z], [-x, -y, z], [-x, y, z], [-x, y, -z]],
    },
    {
      key: "top",
      normal: [0, 1, 0],
      vertices: [[-x, y, z], [x, y, z], [x, y, -z], [-x, y, -z]],
    },
    {
      key: "bottom",
      normal: [0, -1, 0],
      vertices: [[-x, -y, -z], [x, -y, -z], [x, -y, z], [-x, -y, z]],
    },
  ];

  for (const face of faceDefinitions) {
    const baseIndex = positions.length / 3;
    for (const vertex of face.vertices) {
      positions.push(...vertex);
      normals.push(...face.normal);
    }
    texcoords.push(0, 1, 1, 1, 1, 0, 0, 0);
    indices.push(
      baseIndex,
      baseIndex + 1,
      baseIndex + 2,
      baseIndex,
      baseIndex + 2,
      baseIndex + 3,
    );
  }

  const bufferState = createProductModelBufferViewState();
  const positionBufferView = appendProductModelBuffer(
    bufferState,
    createFloat32Buffer(positions),
    34962,
  );
  const normalBufferView = appendProductModelBuffer(
    bufferState,
    createFloat32Buffer(normals),
    34962,
  );
  const texcoordBufferView = appendProductModelBuffer(
    bufferState,
    createFloat32Buffer(texcoords),
    34962,
  );
  const indexBufferView = appendProductModelBuffer(
    bufferState,
    createUint16Buffer(indices),
    34963,
  );
  const combinedBuffer = Buffer.concat(bufferState.chunks);
  const positionBounds = getProductModelVectorBounds(positions);
  const accessors = [
    {
      bufferView: positionBufferView,
      componentType: 5126,
      count: positions.length / 3,
      type: "VEC3",
      min: positionBounds.min,
      max: positionBounds.max,
    },
    {
      bufferView: normalBufferView,
      componentType: 5126,
      count: normals.length / 3,
      type: "VEC3",
    },
    {
      bufferView: texcoordBufferView,
      componentType: 5126,
      count: texcoords.length / 2,
      type: "VEC2",
    },
  ];

  for (let faceIndex = 0; faceIndex < faceDefinitions.length; faceIndex += 1) {
    accessors.push({
      bufferView: indexBufferView,
      byteOffset: faceIndex * 6 * 2,
      componentType: 5123,
      count: 6,
      type: "SCALAR",
    });
  }

  return {
    asset: {
      version: "2.0",
      generator: "Switch six-frame model generator",
    },
    scene: 0,
    scenes: [{ nodes: [0] }],
    nodes: [{ mesh: 0, name: "Generated six-frame product model" }],
    meshes: [
      {
        primitives: faceDefinitions.map((face, index) => ({
          attributes: {
            POSITION: 0,
            NORMAL: 1,
            TEXCOORD_0: 2,
          },
          indices: 3 + index,
          material: index,
          mode: 4,
        })),
      },
    ],
    materials: faceDefinitions.map((face, index) => ({
      name: `${face.key} texture`,
      pbrMetallicRoughness: {
        baseColorTexture: { index },
        metallicFactor: 0,
        roughnessFactor: 0.82,
      },
      doubleSided: true,
    })),
    textures: textureFileNames.map((_, index) => ({ source: index })),
    images: textureFileNames.map((textureFileName) => ({
      uri: textureFileName,
      mimeType: "image/jpeg",
    })),
    buffers: [
      {
        uri: `data:application/octet-stream;base64,${combinedBuffer.toString("base64")}`,
        byteLength: combinedBuffer.length,
      },
    ],
    bufferViews: bufferState.bufferViews,
    accessors,
  };
}

function createTexturedProductCurvedGltf(textureFileNames, frameMetadataByKey) {
  const { width, height, depth } = getProductModelDimensions(frameMetadataByKey);
  const radiusX = width / 2;
  const radiusZ = depth / 2;
  const y = height / 2;
  const positions = [];
  const normals = [];
  const texcoords = [];
  const indices = [];
  const primitiveDefinitions = [];
  const sideDefinitions = [
    { key: "front", material: 0, start: -Math.PI / 4, end: Math.PI / 4 },
    { key: "right", material: 1, start: Math.PI / 4, end: (3 * Math.PI) / 4 },
    { key: "back", material: 2, start: (3 * Math.PI) / 4, end: (5 * Math.PI) / 4 },
    { key: "left", material: 3, start: (5 * Math.PI) / 4, end: (7 * Math.PI) / 4 },
  ];
  const sideSegmentCount = 18;
  const capSegmentCount = 72;

  const getEllipsePoint = (theta, yValue) => ({
    x: radiusX * Math.sin(theta),
    y: yValue,
    z: radiusZ * Math.cos(theta),
  });
  const getEllipseNormal = (theta) => {
    const rawX = Math.sin(theta) / Math.max(radiusX, 0.0001);
    const rawZ = Math.cos(theta) / Math.max(radiusZ, 0.0001);
    const length = Math.hypot(rawX, rawZ) || 1;
    return [rawX / length, 0, rawZ / length];
  };

  for (const side of sideDefinitions) {
    const baseVertexIndex = positions.length / 3;
    const indexStart = indices.length;
    for (let segmentIndex = 0; segmentIndex <= sideSegmentCount; segmentIndex += 1) {
      const progress = segmentIndex / sideSegmentCount;
      const theta = side.start + (side.end - side.start) * progress;
      const bottom = getEllipsePoint(theta, -y);
      const top = getEllipsePoint(theta, y);
      const normal = getEllipseNormal(theta);
      positions.push(bottom.x, bottom.y, bottom.z, top.x, top.y, top.z);
      normals.push(...normal, ...normal);
      texcoords.push(progress, 1, progress, 0);
    }

    for (let segmentIndex = 0; segmentIndex < sideSegmentCount; segmentIndex += 1) {
      const current = baseVertexIndex + segmentIndex * 2;
      const next = current + 2;
      indices.push(current, current + 1, next + 1, current, next + 1, next);
    }

    primitiveDefinitions.push({
      key: side.key,
      material: side.material,
      indexStart,
      indexCount: indices.length - indexStart,
    });
  }

  const appendCap = (key, material, yValue, normalY) => {
    const baseVertexIndex = positions.length / 3;
    const indexStart = indices.length;
    positions.push(0, yValue, 0);
    normals.push(0, normalY, 0);
    texcoords.push(0.5, 0.5);

    for (let segmentIndex = 0; segmentIndex <= capSegmentCount; segmentIndex += 1) {
      const theta = (Math.PI * 2 * segmentIndex) / capSegmentCount;
      const point = getEllipsePoint(theta, yValue);
      positions.push(point.x, point.y, point.z);
      normals.push(0, normalY, 0);
      texcoords.push(
        0.5 + point.x / Math.max(width, 0.0001),
        0.5 - point.z / Math.max(depth, 0.0001),
      );
    }

    for (let segmentIndex = 0; segmentIndex < capSegmentCount; segmentIndex += 1) {
      if (normalY > 0) {
        indices.push(baseVertexIndex, baseVertexIndex + segmentIndex + 1, baseVertexIndex + segmentIndex + 2);
      } else {
        indices.push(baseVertexIndex, baseVertexIndex + segmentIndex + 2, baseVertexIndex + segmentIndex + 1);
      }
    }

    primitiveDefinitions.push({
      key,
      material,
      indexStart,
      indexCount: indices.length - indexStart,
    });
  };

  appendCap("top", 4, y, 1);
  appendCap("bottom", 5, -y, -1);

  const bufferState = createProductModelBufferViewState();
  const positionBufferView = appendProductModelBuffer(
    bufferState,
    createFloat32Buffer(positions),
    34962,
  );
  const normalBufferView = appendProductModelBuffer(
    bufferState,
    createFloat32Buffer(normals),
    34962,
  );
  const texcoordBufferView = appendProductModelBuffer(
    bufferState,
    createFloat32Buffer(texcoords),
    34962,
  );
  const indexBufferView = appendProductModelBuffer(
    bufferState,
    createUint16Buffer(indices),
    34963,
  );
  const combinedBuffer = Buffer.concat(bufferState.chunks);
  const positionBounds = getProductModelVectorBounds(positions);
  const accessors = [
    {
      bufferView: positionBufferView,
      componentType: 5126,
      count: positions.length / 3,
      type: "VEC3",
      min: positionBounds.min,
      max: positionBounds.max,
    },
    {
      bufferView: normalBufferView,
      componentType: 5126,
      count: normals.length / 3,
      type: "VEC3",
    },
    {
      bufferView: texcoordBufferView,
      componentType: 5126,
      count: texcoords.length / 2,
      type: "VEC2",
    },
  ];

  for (const primitive of primitiveDefinitions) {
    accessors.push({
      bufferView: indexBufferView,
      byteOffset: primitive.indexStart * 2,
      componentType: 5123,
      count: primitive.indexCount,
      type: "SCALAR",
    });
  }

  return {
    asset: {
      version: "2.0",
      generator: "Switch curved six-frame model generator",
    },
    scene: 0,
    scenes: [{ nodes: [0] }],
    nodes: [{ mesh: 0, name: "Generated curved six-frame product model" }],
    meshes: [
      {
        primitives: primitiveDefinitions.map((primitive, index) => ({
          attributes: {
            POSITION: 0,
            NORMAL: 1,
            TEXCOORD_0: 2,
          },
          indices: 3 + index,
          material: primitive.material,
          mode: 4,
        })),
      },
    ],
    materials: PRODUCT_MODEL_FRAME_ORDER.map((frameKey, index) => ({
      name: `${frameKey} texture`,
      pbrMetallicRoughness: {
        baseColorTexture: { index },
        metallicFactor: 0,
        roughnessFactor: 0.72,
      },
      doubleSided: true,
    })),
    textures: textureFileNames.map((_, index) => ({ source: index })),
    images: textureFileNames.map((textureFileName) => ({
      uri: textureFileName,
      mimeType: "image/jpeg",
    })),
    buffers: [
      {
        uri: `data:application/octet-stream;base64,${combinedBuffer.toString("base64")}`,
        byteLength: combinedBuffer.length,
      },
    ],
    bufferViews: bufferState.bufferViews,
    accessors,
  };
}

function normalizeProductModelShape(value) {
  const normalizedValue = String(value ?? "").trim().toLowerCase();
  if (["curve", "curved", "round", "rounded", "cylinder", "oval"].includes(normalizedValue)) {
    return "curved";
  }
  return "box";
}

function normalizeProductScanFrameInputs(input) {
  const rawFrames = Array.isArray(input?.frames)
    ? input.frames
    : Array.isArray(input?.imageUrls)
      ? input.imageUrls.map((imageUrl) => ({ imageUrl }))
      : [];

  const normalizedFrames = [];
  for (let index = 0; index < rawFrames.length; index += 1) {
    const frame = rawFrames[index];
    const imageUrl =
      typeof frame === "string"
        ? frame
        : frame?.imageUrl ?? frame?.url ?? frame?.src ?? "";
    const normalizedImageUrl = String(imageUrl ?? "").trim();
    if (!normalizedImageUrl) {
      continue;
    }

    normalizedFrames.push({
      key: `scan-${normalizedFrames.length + 1}`,
      imageUrl: normalizedImageUrl,
    });
  }

  return normalizedFrames.slice(0, 80);
}

function createAverageColorFromSamples(samples) {
  if (!samples.length) {
    return [245, 245, 245];
  }

  const totals = samples.reduce(
    (sum, sample) => [
      sum[0] + sample[0],
      sum[1] + sample[1],
      sum[2] + sample[2],
    ],
    [0, 0, 0],
  );
  return totals.map((value) => value / samples.length);
}

function getScanTextureBackgroundColor(data, info) {
  const sampleStride = Math.max(1, Math.floor(Math.min(info.width, info.height) / 48));
  const edgeSize = Math.max(10, Math.floor(Math.min(info.width, info.height) * 0.07));
  const samples = [];

  for (let y = 0; y < info.height; y += sampleStride) {
    for (let x = 0; x < info.width; x += sampleStride) {
      const isEdge =
        x < edgeSize ||
        y < edgeSize ||
        x >= info.width - edgeSize ||
        y >= info.height - edgeSize;
      if (!isEdge) {
        continue;
      }

      const offset = (y * info.width + x) * info.channels;
      samples.push([data[offset], data[offset + 1], data[offset + 2]]);
    }
  }

  return createAverageColorFromSamples(samples);
}

async function createProductScanTextureBuffer(frameImageBuffer) {
  const resizedImage = sharp(frameImageBuffer)
    .rotate()
    .resize({
      width: PRODUCT_MODEL_TEXTURE_MAX_SIZE,
      height: PRODUCT_MODEL_TEXTURE_MAX_SIZE,
      fit: "inside",
      withoutEnlargement: true,
    })
    .ensureAlpha();
  const { data, info } = await resizedImage
    .raw()
    .toBuffer({ resolveWithObject: true });
  const backgroundColor = getScanTextureBackgroundColor(data, info);
  const output = Buffer.alloc(info.width * info.height * 4);
  let left = info.width;
  let top = info.height;
  let right = -1;
  let bottom = -1;

  for (let y = 0; y < info.height; y += 1) {
    for (let x = 0; x < info.width; x += 1) {
      const sourceOffset = (y * info.width + x) * info.channels;
      const targetOffset = (y * info.width + x) * 4;
      const red = data[sourceOffset];
      const green = data[sourceOffset + 1];
      const blue = data[sourceOffset + 2];
      const sourceAlpha = info.channels >= 4 ? data[sourceOffset + 3] : 255;
      const maxChannel = Math.max(red, green, blue);
      const minChannel = Math.min(red, green, blue);
      const saturation = maxChannel > 0 ? (maxChannel - minChannel) / maxChannel : 0;
      const colorDistance =
        Math.abs(red - backgroundColor[0]) +
        Math.abs(green - backgroundColor[1]) +
        Math.abs(blue - backgroundColor[2]);
      const brightNeutral =
        maxChannel > 210 &&
        saturation < 0.15 &&
        colorDistance < 95;
      const foregroundStrength = brightNeutral
        ? Math.max(0, colorDistance - 36) / 52
        : Math.max(colorDistance / 72, saturation * 2.2);
      const alpha = clampNumber(foregroundStrength, 0, 1) * sourceAlpha;
      const roundedAlpha = Math.round(Math.min(255, Math.max(0, alpha)));

      output[targetOffset] = red;
      output[targetOffset + 1] = green;
      output[targetOffset + 2] = blue;
      output[targetOffset + 3] = roundedAlpha;

      if (roundedAlpha > 18) {
        left = Math.min(left, x);
        top = Math.min(top, y);
        right = Math.max(right, x);
        bottom = Math.max(bottom, y);
      }
    }
  }

  if (right < left || bottom < top) {
    left = 0;
    top = 0;
    right = info.width - 1;
    bottom = info.height - 1;
  }

  const marginX = Math.max(2, Math.round((right - left + 1) * 0.035));
  const marginY = Math.max(2, Math.round((bottom - top + 1) * 0.04));
  const crop = {
    left: Math.max(0, left - marginX),
    top: Math.max(0, top - marginY),
    width: Math.min(info.width - Math.max(0, left - marginX), right - left + 1 + marginX * 2),
    height: Math.min(info.height - Math.max(0, top - marginY), bottom - top + 1 + marginY * 2),
  };
  const pngBuffer = await sharp(output, {
    raw: {
      width: info.width,
      height: info.height,
      channels: 4,
    },
  })
    .extract(crop)
    .png({
      compressionLevel: 9,
      adaptiveFiltering: true,
    })
    .toBuffer();
  const metadata = await sharp(pngBuffer).metadata();

  return {
    buffer: pngBuffer,
    width: Number(metadata.width || crop.width),
    height: Number(metadata.height || crop.height),
  };
}

function createProductScanShellGltf(textureFileNames, frameMetadata) {
  const frameCount = Math.max(1, textureFileNames.length);
  const averageAspect =
    frameMetadata.reduce((sum, metadata) => {
      const width = Number(metadata?.width || 0);
      const height = Number(metadata?.height || 0);
      return sum + (width > 0 && height > 0 ? width / height : 0.72);
    }, 0) / frameCount;
  const height = 2;
  const planeWidth = clampNumber(averageAspect * height, 0.65, 2.2);
  const radius = clampNumber(planeWidth * 0.24, 0.18, 0.62);
  const positions = [];
  const normals = [];
  const texcoords = [];
  const indices = [];
  const primitiveDefinitions = [];

  for (let frameIndex = 0; frameIndex < frameCount; frameIndex += 1) {
    const angle = (Math.PI * 2 * frameIndex) / frameCount;
    const normal = [Math.sin(angle), 0, Math.cos(angle)];
    const tangent = [Math.cos(angle), 0, -Math.sin(angle)];
    const center = [normal[0] * radius, 0, normal[2] * radius];
    const halfWidth = planeWidth / 2;
    const halfHeight = height / 2;
    const baseIndex = positions.length / 3;
    const indexStart = indices.length;
    const corners = [
      [-halfWidth, -halfHeight],
      [halfWidth, -halfHeight],
      [halfWidth, halfHeight],
      [-halfWidth, halfHeight],
    ];

    for (const [xOffset, yOffset] of corners) {
      positions.push(
        center[0] + tangent[0] * xOffset,
        yOffset,
        center[2] + tangent[2] * xOffset,
      );
      normals.push(...normal);
    }
    texcoords.push(0, 1, 1, 1, 1, 0, 0, 0);
    indices.push(baseIndex, baseIndex + 1, baseIndex + 2, baseIndex, baseIndex + 2, baseIndex + 3);
    primitiveDefinitions.push({
      indexStart,
      indexCount: indices.length - indexStart,
      material: frameIndex,
    });
  }

  const bufferState = createProductModelBufferViewState();
  const positionBufferView = appendProductModelBuffer(
    bufferState,
    createFloat32Buffer(positions),
    34962,
  );
  const normalBufferView = appendProductModelBuffer(
    bufferState,
    createFloat32Buffer(normals),
    34962,
  );
  const texcoordBufferView = appendProductModelBuffer(
    bufferState,
    createFloat32Buffer(texcoords),
    34962,
  );
  const indexBufferView = appendProductModelBuffer(
    bufferState,
    createUint16Buffer(indices),
    34963,
  );
  const combinedBuffer = Buffer.concat(bufferState.chunks);
  const positionBounds = getProductModelVectorBounds(positions);
  const accessors = [
    {
      bufferView: positionBufferView,
      componentType: 5126,
      count: positions.length / 3,
      type: "VEC3",
      min: positionBounds.min,
      max: positionBounds.max,
    },
    {
      bufferView: normalBufferView,
      componentType: 5126,
      count: normals.length / 3,
      type: "VEC3",
    },
    {
      bufferView: texcoordBufferView,
      componentType: 5126,
      count: texcoords.length / 2,
      type: "VEC2",
    },
  ];

  for (const primitive of primitiveDefinitions) {
    accessors.push({
      bufferView: indexBufferView,
      byteOffset: primitive.indexStart * 2,
      componentType: 5123,
      count: primitive.indexCount,
      type: "SCALAR",
    });
  }

  return {
    asset: {
      version: "2.0",
      generator: "Switch any-shape photo scan generator",
    },
    scene: 0,
    scenes: [{ nodes: [0] }],
    nodes: [{ mesh: 0, name: "Generated any-shape photo scan shell" }],
    meshes: [
      {
        primitives: primitiveDefinitions.map((primitive, index) => ({
          attributes: {
            POSITION: 0,
            NORMAL: 1,
            TEXCOORD_0: 2,
          },
          indices: 3 + index,
          material: primitive.material,
          mode: 4,
        })),
      },
    ],
    materials: textureFileNames.map((_, index) => ({
      name: `scan frame ${index + 1}`,
      pbrMetallicRoughness: {
        baseColorTexture: { index },
        metallicFactor: 0,
        roughnessFactor: 0.85,
      },
      alphaMode: "BLEND",
      alphaCutoff: 0.04,
      doubleSided: true,
    })),
    textures: textureFileNames.map((_, index) => ({ source: index })),
    images: textureFileNames.map((textureFileName) => ({
      uri: textureFileName,
      mimeType: "image/png",
    })),
    buffers: [
      {
        uri: `data:application/octet-stream;base64,${combinedBuffer.toString("base64")}`,
        byteLength: combinedBuffer.length,
      },
    ],
    bufferViews: bufferState.bufferViews,
    accessors,
  };
}

async function createProductModelFromScanImages(input) {
  if (!sharp) {
    throw createHttpError(
      'Any-shape scan generation needs the "sharp" package to prepare scan textures.',
      503,
    );
  }

  const normalizedFrames = normalizeProductScanFrameInputs(input);
  if (normalizedFrames.length < 8) {
    throw new Error("Upload at least 8 scan photos. 30 or more photos gives a better 3D scan.");
  }

  const timestamp = Date.now();
  const safeStem =
    sanitizeFileStem(input?.name ?? input?.productName ?? "any-shape-product") ||
    "any-shape-product";
  const textureFileNames = [];
  const frameMetadata = [];

  for (let index = 0; index < normalizedFrames.length; index += 1) {
    const frame = normalizedFrames[index];
    const frameBuffer = await readPublicImageBuffer(frame.imageUrl);
    if (!frameBuffer) {
      throw new Error(`Invalid scan frame ${index + 1}.`);
    }

    const texture = await createProductScanTextureBuffer(frameBuffer);
    const textureFileName = `${safeStem}-scan-${String(index + 1).padStart(2, "0")}-${timestamp}.png`;
    await objectStorage.saveUpload(textureFileName, texture.buffer, { contentType: "image/png" });
    textureFileNames.push(textureFileName);
    frameMetadata.push({
      width: texture.width,
      height: texture.height,
    });
  }

  const gltf = createProductScanShellGltf(textureFileNames, frameMetadata);
  const modelFileName = `${safeStem}-any-shape-scan-${timestamp}.gltf`;
  await objectStorage.saveUpload(
    modelFileName,
    Buffer.from(`${JSON.stringify(gltf, null, 2)}\n`, "utf8"),
    { contentType: MIME_TYPES[".gltf"] || "model/gltf+json" },
  );

  return {
    modelUrl: `/uploads/${modelFileName}`,
    modelShape: "scan",
    textureUrls: textureFileNames.map((fileName) => `/uploads/${fileName}`),
    frameImageUrls: normalizedFrames.map((frame) => frame.imageUrl),
  };
}

async function createProductModelFromFrameImages(input) {
  if (!sharp) {
    throw createHttpError(
      '3D model generation needs the "sharp" package to prepare frame textures.',
      503,
    );
  }

  const normalizedFrames = normalizeProductModelFrameInputs(input);
  const missingFrame = normalizedFrames.find((frame) => !frame.imageUrl);
  if (missingFrame) {
    throw new Error("Upload all 6 product frames before generating the 3D model.");
  }

  const timestamp = Date.now();
  const safeStem =
    sanitizeFileStem(input?.name ?? input?.productName ?? "product-model") ||
    "product-model";
  const textureFileNamesByKey = {};
  const frameMetadataByKey = {};

  for (const frame of normalizedFrames) {
    const frameBuffer = await readPublicImageBuffer(frame.imageUrl);
    if (!frameBuffer) {
      throw new Error(`Invalid ${frame.key} frame image.`);
    }

    const textureFileName = `${safeStem}-3d-${frame.key}-${timestamp}.jpg`;
    const frameImage = sharp(frameBuffer).rotate();
    frameMetadataByKey[frame.key] = await frameImage.metadata();
    const textureBuffer = await frameImage
      .clone()
      .resize({
        width: PRODUCT_MODEL_TEXTURE_MAX_SIZE,
        height: PRODUCT_MODEL_TEXTURE_MAX_SIZE,
        fit: "inside",
        withoutEnlargement: true,
      })
      .jpeg({
        quality: 88,
        mozjpeg: true,
      })
      .toBuffer();

    await objectStorage.saveUpload(textureFileName, textureBuffer, { contentType: "image/jpeg" });
    textureFileNamesByKey[frame.key] = textureFileName;
  }

  const textureFileNames = PRODUCT_MODEL_FRAME_ORDER.map(
    (frameKey) => textureFileNamesByKey[frameKey],
  );
  const modelShape = normalizeProductModelShape(input?.shape ?? input?.modelShape);
  const gltf =
    modelShape === "curved"
      ? createTexturedProductCurvedGltf(textureFileNames, frameMetadataByKey)
      : createTexturedProductBoxGltf(textureFileNames, frameMetadataByKey);
  const modelFileName = `${safeStem}-${modelShape}-generated-3d-${timestamp}.gltf`;
  await objectStorage.saveUpload(
    modelFileName,
    Buffer.from(`${JSON.stringify(gltf, null, 2)}\n`, "utf8"),
    { contentType: MIME_TYPES[".gltf"] || "model/gltf+json" },
  );

  return {
    modelUrl: `/uploads/${modelFileName}`,
    modelShape,
    textureUrls: textureFileNames.map((fileName) => `/uploads/${fileName}`),
    frameImageUrls: normalizedFrames.map((frame) => frame.imageUrl),
  };
}

function resolveProductMainImageIndex(imageUrls, requestedMainImageIndex, fallbackImageUrl = "") {
  if (!imageUrls.length) {
    return 0;
  }

  const normalizedMainImageIndex = Number(requestedMainImageIndex);
  if (
    Number.isInteger(normalizedMainImageIndex) &&
    normalizedMainImageIndex >= 0 &&
    normalizedMainImageIndex < imageUrls.length
  ) {
    return normalizedMainImageIndex;
  }

  const trimmedFallbackImageUrl = String(fallbackImageUrl ?? "").trim();
  const fallbackIndex = trimmedFallbackImageUrl
    ? imageUrls.indexOf(trimmedFallbackImageUrl)
    : -1;

  return fallbackIndex >= 0 ? fallbackIndex : 0;
}

function normalizeProductCardImagePosition(value, fallback = 50) {
  const normalizedValue = Number(value ?? fallback);
  if (!Number.isFinite(normalizedValue)) {
    return fallback;
  }

  return Math.min(100, Math.max(0, normalizedValue));
}

function normalizeProductCropZoomPercent(value, fallback = 0) {
  const normalizedValue = Number(value ?? fallback);
  if (!Number.isFinite(normalizedValue)) {
    return fallback;
  }

  return Math.min(500, Math.max(0, Math.round(normalizedValue)));
}

function normalizeProductVisibleFraction(value, fallback = 0) {
  const normalizedValue = Number(value ?? fallback);
  if (!Number.isFinite(normalizedValue)) {
    return fallback;
  }

  return Math.min(1, Math.max(0, normalizedValue));
}

function normalizeProductMediaTimeMs(value, fallback = 0) {
  const normalizedValue = Number(value ?? fallback);
  if (!Number.isFinite(normalizedValue)) {
    return fallback;
  }

  return Math.max(0, Math.round(normalizedValue));
}

function normalizeProductDetailsImageCrops(
  rawDetailsImageCrops,
  imageUrls,
  existingDetailsImageCrops = [],
) {
  const submittedCrops = Array.isArray(rawDetailsImageCrops)
    ? rawDetailsImageCrops
    : Array.isArray(existingDetailsImageCrops)
      ? existingDetailsImageCrops
      : [];
  const validSourceKeys = new Set(
    (Array.isArray(imageUrls) ? imageUrls : [])
      .map((imageUrl) => String(imageUrl ?? "").trim().toLowerCase())
      .filter(Boolean),
  );
  const seen = new Set();
  const normalizedCrops = [];

  for (const cropEntry of submittedCrops) {
    const sourceUrl = String(cropEntry?.sourceUrl ?? "").trim();
    const croppedImageUrl = String(cropEntry?.croppedImageUrl ?? "").trim();
    const sourceKey = sourceUrl.toLowerCase();

    if (
      !sourceUrl ||
      !croppedImageUrl ||
      !validSourceKeys.has(sourceKey) ||
      seen.has(sourceKey)
    ) {
      continue;
    }

    seen.add(sourceKey);
    normalizedCrops.push({
      sourceUrl,
      croppedImageUrl,
      positionX: normalizeProductCardImagePosition(cropEntry?.positionX),
      positionY: normalizeProductCardImagePosition(cropEntry?.positionY),
    });
  }

  return normalizedCrops;
}

function normalizeStoredProductImageGallery(product) {
  const fallbackImageUrl = String(
    product?.imageUrl ?? product?.mainImageUrl ?? "",
  ).trim();
  const imageUrls = normalizeProductImageUrls(
    product?.imageUrls,
    fallbackImageUrl,
  );
  const mainImageIndex = resolveProductMainImageIndex(
    imageUrls,
    product?.mainImageIndex,
    String(product?.mainImageUrl ?? fallbackImageUrl).trim(),
  );
  const resolvedMainImageUrl = imageUrls[mainImageIndex] ?? "";
  const requestedCardImageUrl = String(product?.cardImageUrl ?? "").trim();
  const requestedCardImageSourceUrl = String(product?.cardImageSourceUrl ?? "").trim();
  const cardImageSourceUrl =
    requestedCardImageSourceUrl && requestedCardImageSourceUrl === resolvedMainImageUrl
      ? requestedCardImageSourceUrl
      : "";
  const cardImageUrl = cardImageSourceUrl && requestedCardImageUrl ? requestedCardImageUrl : "";
  const detailsImageCrops = normalizeProductDetailsImageCrops(
    product?.detailsImageCrops,
    imageUrls,
  );

  return {
    ...product,
    imageUrl: resolvedMainImageUrl,
    mainImageUrl: resolvedMainImageUrl,
    imageUrls,
    mainImageIndex,
    cardImageUrl,
    cardImageSourceUrl,
    detailsImageCrops,
    cardImagePositionX: normalizeProductCardImagePosition(product?.cardImagePositionX),
    cardImagePosition: normalizeProductCardImagePosition(product?.cardImagePosition),
  };
}

function normalizeVariantName(value) {
  return String(value ?? "").replace(/\s+/g, " ").trim();
}

function normalizeVariantQuantity(value) {
  return String(value ?? "").replace(/\s+/g, " ").trim();
}

function normalizeVariantAddOns(inputAddOns) {
  if (!Array.isArray(inputAddOns) || !inputAddOns.length) {
    return [];
  }

  const seen = new Set();
  const normalizedAddOns = [];

  for (const addOn of inputAddOns) {
    const id = String(addOn?.id ?? "").trim();
    const name = String(addOn?.name ?? "").replace(/\s+/g, " ").trim();
    const quantity = parseNumberInput(addOn?.quantity ?? 1);
    const normalizedKey = id.toLowerCase();

    if (
      !id ||
      !name ||
      seen.has(normalizedKey) ||
      !Number.isFinite(quantity) ||
      quantity < 1 ||
      !Number.isInteger(quantity)
    ) {
      continue;
    }

    seen.add(normalizedKey);
    normalizedAddOns.push({ id, name, quantity });
  }

  return normalizedAddOns;
}

function normalizeProductVariants(inputVariants, imageUrls, existingVariants = []) {
  const submittedVariants = Array.isArray(inputVariants) ? inputVariants : [];

  if (!submittedVariants.length) {
    return [];
  }

  return submittedVariants.map((variant, index) => {
    const submittedVariantId = String(variant?.id ?? "").trim();
    const existingVariant = Array.isArray(existingVariants)
      ? existingVariants.find(
          (candidate) => String(candidate?.id ?? "").trim() === submittedVariantId,
        ) ?? existingVariants[index] ?? null
      : null;
    const name = normalizeVariantName(variant?.name);
    const imageUrl = String(variant?.imageUrl ?? "").trim();
    const imageSourceUrl = String(
      variant?.imageSourceUrl ?? existingVariant?.imageSourceUrl ?? imageUrl,
    ).trim();
    const addOns = normalizeVariantAddOns(variant?.addOns);
    const originalPrice = parsePriceInput(variant?.originalPrice);
    const hasSalesPrice = hasInputValue(variant?.salesPrice);
    const salesPrice = hasSalesPrice ? parsePriceInput(variant?.salesPrice) : null;
    const imagePositionX = normalizeProductCardImagePosition(
      variant?.imagePositionX ?? existingVariant?.imagePositionX,
      50,
    );
    const imagePositionY = normalizeProductCardImagePosition(
      variant?.imagePositionY ?? existingVariant?.imagePositionY,
      50,
    );

    if (!name) {
      throw new Error(`Variant ${index + 1} name is required.`);
    }

    if (!imageUrl) {
      throw new Error(`Variant ${index + 1} image is required.`);
    }

    if (!Number.isFinite(originalPrice) || originalPrice < 0) {
      throw new Error(`Variant ${index + 1} original price must be valid.`);
    }

    if (hasSalesPrice) {
      if (!Number.isFinite(salesPrice) || salesPrice < 0) {
        throw new Error(`Variant ${index + 1} sales price must be valid.`);
      }

      if (salesPrice > originalPrice) {
        throw new Error(`Variant ${index + 1} sales price cannot be higher than original price.`);
      }
    }

    return {
      id: submittedVariantId || String(existingVariant?.id ?? `var-${Date.now()}-${index + 1}`),
      name,
      imageUrl,
      imageSourceUrl: imageSourceUrl || imageUrl,
      imagePositionX,
      imagePositionY,
      addOns,
      originalPrice,
      salesPrice,
      specifications: Array.isArray(variant?.specifications)
        ? variant.specifications
        : (Array.isArray(existingVariant?.specifications) ? existingVariant.specifications : []),
      quantity: "",
      stock: 0,
    };
  });
}

function syncProductVariantAddOnsWithInventory(product, inventoryProducts, adminId) {
  const productId = String(product?.id ?? "").trim().toLowerCase();
  const inventoryProductsById = new Map(
    (Array.isArray(inventoryProducts) ? inventoryProducts : [])
      .filter((inventoryProduct) =>
        isRecordInAdminScope(inventoryProduct, adminId)
        && normalizeProductApprovalStatus(inventoryProduct?.approvalStatus) === PRODUCT_APPROVAL_APPROVED
        && String(inventoryProduct?.id ?? "").trim().toLowerCase() !== productId)
      .map((inventoryProduct) => [
        String(inventoryProduct?.id ?? "").trim().toLowerCase(),
        inventoryProduct,
      ]),
  );

  return {
    ...product,
    variants: (Array.isArray(product?.variants) ? product.variants : []).map((variant) => {
      const seenAddOnIds = new Set();
      const addOns = normalizeVariantAddOns(variant?.addOns).reduce(
        (filteredAddOns, addOn) => {
          const addOnId = String(addOn?.id ?? "").trim().toLowerCase();
          const inventoryProduct = inventoryProductsById.get(addOnId);
          if (!addOnId || !inventoryProduct || seenAddOnIds.has(addOnId)) {
            return filteredAddOns;
          }

          seenAddOnIds.add(addOnId);
          filteredAddOns.push({
            id: String(inventoryProduct.id ?? "").trim(),
            name: String(inventoryProduct.name ?? "").replace(/\s+/g, " ").trim(),
            quantity: addOn.quantity,
          });
          return filteredAddOns;
        },
        [],
      );

      return { ...variant, addOns };
    }),
  };
}

function normalizeStoredProductVariants(product) {
  const variants = Array.isArray(product?.variants)
    ? product.variants.map((variant, index) => {
        const name = normalizeVariantName(variant?.name);
        const imageUrl = String(variant?.imageUrl ?? "").trim();
        const imageSourceUrl = String(variant?.imageSourceUrl ?? imageUrl).trim();
        const addOns = normalizeVariantAddOns(variant?.addOns);
        const originalPrice = Number(variant?.originalPrice ?? 0);
        const salesPrice = hasInputValue(variant?.salesPrice)
          ? Number(variant.salesPrice)
          : null;
        const stock = Number(variant?.stock ?? 0);
        const imagePositionX = normalizeProductCardImagePosition(
          variant?.imagePositionX,
          50,
        );
        const imagePositionY = normalizeProductCardImagePosition(
          variant?.imagePositionY,
          50,
        );

        if (
          !name ||
          !imageUrl ||
          !Number.isFinite(originalPrice) ||
          originalPrice < 0 ||
          !Number.isFinite(stock) ||
          stock < 0
        ) {
          return null;
        }

        const normalizedSalesPrice =
          salesPrice === null || !Number.isFinite(salesPrice) || salesPrice < 0
            ? null
            : salesPrice;

        return {
          id: String(variant?.id ?? `var-${product?.id ?? "product"}-${index + 1}`),
          name,
          imageUrl,
          imageSourceUrl: imageSourceUrl || imageUrl,
          imagePositionX,
          imagePositionY,
          addOns,
          originalPrice,
          salesPrice:
            normalizedSalesPrice !== null && normalizedSalesPrice <= originalPrice
              ? normalizedSalesPrice
              : null,
          specifications: Array.isArray(variant?.specifications) ? variant.specifications : [],
          quantity: "",
          stock: Math.trunc(stock),
        };
      }).filter(Boolean)
    : [];

  return {
    ...product,
    variants,
  };
}

function normalizeProductActiveState(value, fallback = true) {
  if (typeof value === "boolean") {
    return value;
  }

  if (typeof value === "number") {
    return Number.isFinite(value) ? value !== 0 : fallback;
  }

  if (typeof value === "string") {
    const normalizedValue = value.trim().toLowerCase();
    if (normalizedValue === "true") {
      return true;
    }
    if (normalizedValue === "false") {
      return false;
    }
  }

  return fallback;
}

function normalizeProductApprovalStatus(value, fallback = PRODUCT_APPROVAL_APPROVED) {
  const normalizedValue = String(value ?? "").trim().toLowerCase();
  if (
    normalizedValue === PRODUCT_APPROVAL_PENDING ||
    normalizedValue === PRODUCT_APPROVAL_APPROVED ||
    normalizedValue === PRODUCT_APPROVAL_REJECTED
  ) {
    return normalizedValue;
  }

  const normalizedFallback = String(fallback ?? "").trim().toLowerCase();
  return normalizedFallback === PRODUCT_APPROVAL_PENDING ||
    normalizedFallback === PRODUCT_APPROVAL_REJECTED
    ? normalizedFallback
    : PRODUCT_APPROVAL_APPROVED;
}

function isProductPendingApproval(product) {
  return normalizeProductApprovalStatus(
    product?.approvalStatus,
    PRODUCT_APPROVAL_APPROVED,
  ) === PRODUCT_APPROVAL_PENDING;
}

function isProductApprovedForApp(product) {
  return normalizeProductApprovalStatus(
    product?.approvalStatus,
    PRODUCT_APPROVAL_APPROVED,
  ) === PRODUCT_APPROVAL_APPROVED;
}

function isProductRejected(product) {
  return normalizeProductApprovalStatus(
    product?.approvalStatus,
    PRODUCT_APPROVAL_APPROVED,
  ) === PRODUCT_APPROVAL_REJECTED;
}

function getProductYoloInspectionImageUrls(product) {
  const variantImageUrls = Array.isArray(product?.variants)
    ? product.variants.flatMap((variant) => [
        variant?.imageUrl,
        variant?.imageSourceUrl,
        variant?.displayImageUrl,
      ])
    : [];
  // Description photos stay in description only — never feed YOLO evidence.
  return normalizeProductImageUrls(
    [
      ...(Array.isArray(product?.imageUrls) ? product.imageUrls : []),
      product?.imageUrl,
      product?.mainImageUrl,
      product?.cardImageUrl,
      product?.cardImageSourceUrl,
      product?.buyModalImageUrl,
      product?.buyModalImageSourceUrl,
      ...variantImageUrls,
      ...(Array.isArray(product?.visualSearchImageUrls) ? product.visualSearchImageUrls : []),
    ],
    product?.imageUrl ?? product?.mainImageUrl ?? "",
  );
}

function getProductDescriptionImageUrlKeySet(product = {}) {
  return new Set(
    normalizeProductDescriptionImageUrls(product?.descriptionImageUrls)
      .map((imageUrl) => String(imageUrl ?? "").trim().toLowerCase())
      .filter(Boolean),
  );
}

function excludeProductDescriptionImageUrls(imageUrls, product = {}) {
  const descriptionKeys = getProductDescriptionImageUrlKeySet(product);
  if (!descriptionKeys.size) {
    return Array.isArray(imageUrls) ? imageUrls : [];
  }
  return (Array.isArray(imageUrls) ? imageUrls : []).filter(
    (imageUrl) => !descriptionKeys.has(String(imageUrl ?? "").trim().toLowerCase()),
  );
}

function getProductApprovedTrainingImageUrls(product = {}) {
  const approvedEvidenceImageUrls = Array.isArray(product?.yoloInspection?.approvedEvidence?.imageUrls)
    ? product.yoloInspection.approvedEvidence.imageUrls
    : [];
  const inspectionImageUrls = Array.isArray(product?.yoloInspection?.imageUrls)
    ? product.yoloInspection.imageUrls
    : [];
  const detailCropImageUrls = Array.isArray(product?.detailsImageCrops)
    ? product.detailsImageCrops.flatMap((crop) => [
        crop?.croppedImageUrl,
        crop?.sourceUrl,
      ])
    : [];
  const variantImageUrls = Array.isArray(product?.variants)
    ? product.variants.flatMap((variant) => [
        variant?.imageUrl,
        variant?.imageSourceUrl,
        variant?.displayImageUrl,
      ])
    : [];

  return excludeProductDescriptionImageUrls(
    normalizeProductImageUrls(
      [
        ...approvedEvidenceImageUrls,
        ...inspectionImageUrls,
        ...getProductYoloInspectionImageUrls(product),
        ...getProductVisualSearchImageUrls(product),
        product?.visualSearchImageUrl,
        product?.cardImageSourceUrl,
        product?.buyModalImageSourceUrl,
        ...detailCropImageUrls,
        ...variantImageUrls,
      ],
      product?.imageUrl ?? product?.mainImageUrl ?? "",
    ),
    product,
  );
}

function normalizeYoloDetection(value) {
  if (!value || typeof value !== "object") {
    return null;
  }

  const rawConfidence = Number(value.confidence ?? value.score ?? value.probability);
  const confidence = Number.isFinite(rawConfidence)
    ? Math.max(0, Math.min(1, rawConfidence > 1 ? rawConfidence / 100 : rawConfidence))
    : 0;
  const rawBox = value.bbox ?? value.box ?? value.boundingBox;
  let box = null;
  if (Array.isArray(rawBox) && rawBox.length >= 4) {
    const [x, y, width, height] = rawBox.map(Number);
    if ([x, y, width, height].every(Number.isFinite)) {
      box = { x, y, width, height };
    }
  } else if (rawBox && typeof rawBox === "object") {
    const x = Number(rawBox.x ?? rawBox.left);
    const y = Number(rawBox.y ?? rawBox.top);
    const width = Number(rawBox.width ?? rawBox.w);
    const height = Number(rawBox.height ?? rawBox.h);
    if ([x, y, width, height].every(Number.isFinite)) {
      box = { x, y, width, height };
    }
  }

  const rawLabelCandidates = [
    value.label,
    value.className,
    value.name,
    value.object,
    value.tag,
    value.title,
    value.category,
    value.class,
  ];
  const rawLabel =
    rawLabelCandidates.find((candidate) => {
      const candidateLabel = String(candidate ?? "").trim();
      return candidateLabel && !/^\d+$/.test(candidateLabel);
    }) ??
    rawLabelCandidates.find((candidate) => String(candidate ?? "").trim()) ??
    "";

  return {
    label: String(rawLabel || "object").trim() || "object",
    confidence,
    box,
    flagged: value.flagged === true,
    reason: String(value.reason ?? "").trim(),
    imageUrl: String(value.imageUrl ?? value.url ?? value.mediaUrl ?? "").trim(),
  };
}

function normalizeYoloDetectionList(value) {
  return (Array.isArray(value) ? value : [])
    .map(normalizeYoloDetection)
    .filter(Boolean);
}

function normalizeRejectedEvidenceMatchScore(value) {
  const score = Number(value);
  if (!Number.isFinite(score)) {
    return 0;
  }

  return Math.max(0, Math.min(1, score > 1 ? score / 100 : score));
}

function normalizeConfidenceThreshold(value, fallback = 0) {
  const normalizedValue = normalizeRejectedEvidenceMatchScore(value);
  if (normalizedValue > 0) {
    return normalizedValue;
  }

  return normalizeRejectedEvidenceMatchScore(fallback);
}

function normalizeYoloRejectedEvidenceMatch(value) {
  if (!value || typeof value !== "object") {
    return null;
  }

  const score = normalizeRejectedEvidenceMatchScore(
    value.score ?? value.visualSearchScore ?? value.confidence,
  );
  const threshold = normalizeRejectedEvidenceMatchScore(
    value.threshold ?? REJECTED_PRODUCT_VISUAL_MATCH_MIN_SCORE,
  ) || REJECTED_PRODUCT_VISUAL_MATCH_MIN_SCORE;
  const status = String(value.status ?? "").trim().toLowerCase();
  const flagged =
    value.flagged === true ||
    status === "matched" ||
    score >= threshold;

  if (!flagged) {
    return null;
  }

  return {
    flagged: true,
    status: "matched",
    matchType:
      String(value.matchType ?? "rejected-visual-fingerprint").trim() ||
      "rejected-visual-fingerprint",
    score,
    threshold,
    productId: String(value.productId ?? value.sourceProductId ?? "").trim(),
    productName: String(value.productName ?? value.sourceProductName ?? "").trim(),
    imageUrl: String(value.imageUrl ?? value.sourceImageUrl ?? "").trim(),
    matchedProductId:
      String(value.matchedProductId ?? value.rejectedProductId ?? "").trim(),
    matchedProductName:
      String(value.matchedProductName ?? value.rejectedProductName ?? "").trim(),
    matchedImageUrl:
      String(value.matchedImageUrl ?? value.rejectedImageUrl ?? "").trim(),
    matchedRejectedAt: normalizeOptionalProductDateTime(
      value.matchedRejectedAt ?? value.rejectedAt,
    ),
    matchedRejectedBy: String(value.matchedRejectedBy ?? value.rejectedBy ?? "").trim(),
    reason:
      String(value.reason ?? "").trim() ||
      "Matches rejected product evidence.",
    updatedAt: normalizeOptionalProductDateTime(value.updatedAt, new Date().toISOString()),
  };
}

function normalizeYoloApprovedEvidence(value) {
  if (!value || typeof value !== "object") {
    return null;
  }

  const imageUrls = normalizeProductImageUrls(value.imageUrls ?? value.images);
  const approvedAt = normalizeOptionalProductDateTime(
    value.approvedAt ?? value.recordedAt ?? value.updatedAt,
  );
  const updatedAt = normalizeOptionalProductDateTime(
    value.updatedAt,
    approvedAt || new Date().toISOString(),
  );

  return {
    status: "approved",
    trainingBucket: "approved",
    source:
      String(value.source ?? "").trim() ||
      "manual-super-admin-approval",
    productId: String(value.productId ?? "").trim(),
    productName: String(value.productName ?? value.name ?? "").trim(),
    adminId: normalizeAdminTenantId(value.adminId, ""),
    categoryLabel: String(value.categoryLabel ?? value.category ?? "").trim(),
    categoryBuckets: Array.isArray(value.categoryBuckets)
      ? value.categoryBuckets.map((entry) => String(entry ?? "").trim()).filter(Boolean)
      : [],
    imageUrls,
    approvedAt,
    approvedBy: String(value.approvedBy ?? "").trim(),
    reason:
      String(value.reason ?? "").trim() ||
      "Product manually approved as clean YOLO training evidence.",
    updatedAt,
  };
}

function normalizeYoloRevisionEvidence(value) {
  if (!value || typeof value !== "object") {
    return null;
  }

  const imageUrls = normalizeProductImageUrls(value.imageUrls ?? value.images);
  const requestedAt = normalizeOptionalProductDateTime(
    value.requestedAt ?? value.recordedAt ?? value.updatedAt,
  );
  const updatedAt = normalizeOptionalProductDateTime(
    value.updatedAt,
    requestedAt || new Date().toISOString(),
  );

  return {
    status: "revision",
    trainingBucket: "revision",
    source:
      String(value.source ?? "").trim() ||
      "manual-super-admin-revision",
    productId: String(value.productId ?? "").trim(),
    productName: String(value.productName ?? value.name ?? "").trim(),
    adminId: normalizeAdminTenantId(value.adminId, ""),
    categoryLabel: String(value.categoryLabel ?? value.category ?? "").trim(),
    categoryBuckets: Array.isArray(value.categoryBuckets)
      ? value.categoryBuckets.map((entry) => String(entry ?? "").trim()).filter(Boolean)
      : [],
    imageBuckets: Array.isArray(value.imageBuckets)
      ? value.imageBuckets.map((entry) => String(entry ?? "").trim()).filter(Boolean)
      : [],
    imageUrls,
    requestedAt,
    requestedBy: String(value.requestedBy ?? "").trim(),
    reason:
      String(value.reason ?? "").trim() ||
      "Product manually sent for revision as YOLO training evidence.",
    message: String(value.message ?? "").trim(),
    updatedAt,
  };
}

function normalizeYoloInspection(value, fallbackImageUrls = []) {
  if (!value || typeof value !== "object") {
    return null;
  }

  const allowedStatuses = new Set(["queued", "clear", "flagged", "error"]);
  const requestedStatus = String(value.status ?? "queued").trim().toLowerCase();
  const status = allowedStatuses.has(requestedStatus) ? requestedStatus : "queued";
  const imageUrls = normalizeProductImageUrls(
    Array.isArray(value.imageUrls) ? value.imageUrls : fallbackImageUrls,
  );
  const rejectedEvidenceImageUrls = normalizeProductImageUrls(
    value.rejectedEvidenceImageUrls ??
      value.rejectedImageUrls ??
      value.rejectedTrainingImageUrls ??
      [],
  );
  const fingerprints = normalizeVisualSearchFingerprintMetaList(
    value.fingerprints ??
      value.rejectedEvidenceFingerprints ??
      value.visualSearchFingerprints,
    imageUrls,
  );
  const imageResults = (Array.isArray(value.images) ? value.images : [])
    .map((entry) => {
      if (!entry || typeof entry !== "object") {
        return null;
      }
      const imageUrl = String(entry.imageUrl ?? entry.url ?? "").trim();
      if (!imageUrl) {
        return null;
      }
      return {
        imageUrl,
        flagged: entry.flagged === true,
        detections: normalizeYoloDetectionList(entry.detections),
      };
    })
    .filter(Boolean);
  const detections = normalizeYoloDetectionList(value.detections);
  const rejectedEvidenceMatch = normalizeYoloRejectedEvidenceMatch(
    value.rejectedEvidenceMatch ??
      value.rejectedEvidence ??
      value.illegalProductMatch,
  );
  const approvedEvidence = normalizeYoloApprovedEvidence(
    value.approvedEvidence ??
      value.goodProductEvidence ??
      value.approvedProductEvidence,
  );
  const revisionEvidence = normalizeYoloRevisionEvidence(
    value.revisionEvidence ??
      value.revisionProductEvidence ??
      value.revisionTrainingEvidence,
  );
  const flagged =
    value.flagged === true ||
    status === "flagged" ||
    rejectedEvidenceMatch?.flagged === true ||
    detections.some((detection) => detection.flagged) ||
    imageResults.some((entry) => entry.flagged || entry.detections.some((detection) => detection.flagged));
  const confidence = normalizeRejectedEvidenceMatchScore(
    value.confidence ?? value.score ?? value.probability,
  );

  return {
    engine: "yolo",
    model: String(value.model ?? YOLO_INSPECTION_MODEL).trim() || YOLO_INSPECTION_MODEL,
    status: flagged ? "flagged" : status,
    flagged,
    confidence,
    autoReject: value.autoReject === true,
    datasetBucket: String(value.datasetBucket ?? "inspection").trim() || "inspection",
    imageUrls,
    rejectedEvidenceImageUrls,
    fingerprints,
    images: imageResults,
    detections,
    rejectedEvidenceMatch,
    approvedEvidence,
    revisionEvidence,
    requestedAt: normalizeOptionalProductDateTime(value.requestedAt),
    inspectedAt: normalizeOptionalProductDateTime(value.inspectedAt),
    updatedAt: normalizeOptionalProductDateTime(value.updatedAt),
    archivedAt: normalizeOptionalProductDateTime(value.archivedAt),
    error: String(value.error ?? "").trim(),
  };
}

function normalizeManualYoloDetectionLabel(value) {
  return String(value ?? "")
    .replace(/\s+/g, " ")
    .trim();
}

function validateManualYoloDetectionLabel(value) {
  const label = normalizeManualYoloDetectionLabel(value);
  const lowerLabel = label.toLowerCase();
  const blockedLabels = new Set([
    "object",
    "item",
    "thing",
    "product",
    "image",
    "picture",
    "photo",
    "unknown",
    "none",
    "null",
    "undefined",
    "n/a",
    "na",
    "test",
    "sample",
    "asdf",
    "qwerty",
    "haha",
    "hahaha",
    "lol",
    "yolo",
    "detection",
    "approve",
    "approved",
    "reject",
    "rejected",
    "safe",
    "clean",
    "illegal",
  ]);
  const abusivePattern = /\b(fuck|shit|puta|putang|tangina|gago|bobo|ulol)\b/i;

  if (label.length < 2 || label.length > 48) {
    return {
      label: "",
      message: "Use a real object label between 2 and 48 characters.",
    };
  }
  if (!/[a-z]/i.test(label)) {
    return {
      label: "",
      message: "Detection label must include letters, not only symbols or numbers.",
    };
  }
  if (!/^[a-z0-9][a-z0-9\s&'().,/-]*$/i.test(label)) {
    return {
      label: "",
      message: "Use only letters, numbers, spaces, and simple punctuation for the object label.",
    };
  }
  if (blockedLabels.has(lowerLabel) || abusivePattern.test(label)) {
    return {
      label: "",
      message: "Use a specific object name, not a generic, test, or abusive label.",
    };
  }
  if (/(.)\1{4,}/i.test(label) || /(asdf|qwer|zxcv|1234|0000|xxxx)/i.test(label)) {
    return {
      label: "",
      message: "Use a meaningful object label, not random or repeated characters.",
    };
  }
  if (label.split(/\s+/).filter(Boolean).length > 5) {
    return {
      label: "",
      message: "Keep the detection label short, like \"gummies\" or \"water bottle\".",
    };
  }

  return { label, message: "" };
}

function parseApprovedTrainingDisplayProductId(productId) {
  const normalizedProductId = String(productId ?? "").trim();
  const match = normalizedProductId.match(/^(.*)::approved-image::(\d+)$/);
  if (!match) {
    return {
      rawProductId: normalizedProductId,
      sourceProductId: normalizedProductId,
      approvedImageIndex: 0,
    };
  }

  return {
    rawProductId: normalizedProductId,
    sourceProductId: String(match[1] ?? "").trim(),
    approvedImageIndex: Math.max(0, Number(match[2]) || 0),
  };
}

function createManualYoloDetection(label, imageUrl = "", existingDetection = null) {
  const normalizedExisting = normalizeYoloDetection(existingDetection) || {};
  return normalizeYoloDetection({
    ...normalizedExisting,
    label,
    imageUrl: String(normalizedExisting.imageUrl || imageUrl || "").trim(),
    confidence: normalizedExisting.confidence || 1,
    reason: "Manual Super Admin correction.",
  });
}

function applyManualYoloDetectionLabel(product = {}, label = "", options = {}) {
  const correction = validateManualYoloDetectionLabel(label);
  if (!correction.label) {
    return product;
  }

  const approvalStatus = normalizeProductApprovalStatus(
    product?.approvalStatus,
    PRODUCT_APPROVAL_APPROVED,
  );
  const baseImageUrls = approvalStatus === PRODUCT_APPROVAL_APPROVED
    ? getProductApprovedTrainingImageUrls(product)
    : getProductYoloInspectionImageUrls(product);
  const targetImageUrl = String(options.targetImageUrl ?? "").trim();
  const imageUrls = normalizeProductImageUrls(
    targetImageUrl ? [...baseImageUrls, targetImageUrl] : baseImageUrls,
    product?.imageUrl ?? product?.mainImageUrl ?? "",
  );
  const targetKey = targetImageUrl.toLowerCase();
  const now = new Date().toISOString();
  const existingInspection = normalizeYoloInspection(
    product?.yoloInspection,
    imageUrls,
  ) || normalizeYoloInspection({
    status: approvalStatus === PRODUCT_APPROVAL_APPROVED ? "clear" : "queued",
    imageUrls,
    updatedAt: now,
  }, imageUrls);
  const topLevelDetections = normalizeYoloDetectionList(existingInspection?.detections);
  const nextTopLevelDetections = targetKey
    ? topLevelDetections
    : (
        topLevelDetections.length
          ? topLevelDetections.map((detection) =>
              createManualYoloDetection(correction.label, detection.imageUrl, detection),
            )
          : [createManualYoloDetection(correction.label, imageUrls[0] || "", null)]
      ).filter(Boolean);
  const imageResultUrls = normalizeProductImageUrls([
    ...imageUrls,
    ...(Array.isArray(existingInspection?.images)
      ? existingInspection.images.map((entry) => entry?.imageUrl || entry?.url)
      : []),
  ]);
  const imageResultsByKey = new Map(
    (Array.isArray(existingInspection?.images) ? existingInspection.images : [])
      .map((entry) => [String(entry?.imageUrl || entry?.url || "").trim().toLowerCase(), entry])
      .filter(([key]) => key),
  );
  const nextImageResults = imageResultUrls.map((imageUrl) => {
    const key = String(imageUrl || "").trim().toLowerCase();
    const existingImageResult = imageResultsByKey.get(key) || { imageUrl };
    const shouldUpdate = !targetKey || key === targetKey;
    let detections = normalizeYoloDetectionList(existingImageResult?.detections);
    if (shouldUpdate) {
      detections = detections.length
        ? detections.map((detection) =>
            createManualYoloDetection(correction.label, imageUrl, detection),
          ).filter(Boolean)
        : [createManualYoloDetection(correction.label, imageUrl, null)].filter(Boolean);
    }

    return {
      imageUrl,
      flagged: existingImageResult?.flagged === true,
      detections,
    };
  });

  return {
    ...product,
    yoloInspection: normalizeYoloInspection({
      ...(existingInspection || {}),
      status: existingInspection?.status || (approvalStatus === PRODUCT_APPROVAL_APPROVED ? "clear" : "queued"),
      imageUrls,
      detections: nextTopLevelDetections,
      images: nextImageResults,
      updatedAt: now,
    }, imageUrls),
    updatedAt: now,
  };
}

function getYoloServiceImageUrl(imageUrl) {
  const normalizedImageUrl = String(imageUrl ?? "").trim();
  if (!normalizedImageUrl || !YOLO_INSPECTION_PUBLIC_BASE_URL || /^https?:\/\//i.test(normalizedImageUrl)) {
    return normalizedImageUrl;
  }
  return normalizedImageUrl.startsWith("/")
    ? `${YOLO_INSPECTION_PUBLIC_BASE_URL}${normalizedImageUrl}`
    : `${YOLO_INSPECTION_PUBLIC_BASE_URL}/${normalizedImageUrl}`;
}

async function runYoloProductInspection(product) {
  const now = new Date().toISOString();
  const imageUrls = getProductYoloInspectionImageUrls(product);
  const datasetBucket = isProductRejected(product)
    ? "rejected"
    : String(product?.yoloInspection?.datasetBucket ?? "inspection").trim() || "inspection";
  const queuedInspection = normalizeYoloInspection({
    status: "queued",
    model: YOLO_INSPECTION_MODEL,
    datasetBucket,
    imageUrls,
    requestedAt: now,
    updatedAt: now,
  }, imageUrls);

  if (!YOLO_INSPECTION_ENDPOINT || !imageUrls.length) {
    return queuedInspection;
  }

  const abortController = new AbortController();
  const timeoutId = setTimeout(() => abortController.abort(), YOLO_INSPECTION_TIMEOUT_MS);
  try {
    const headers = { "Content-Type": "application/json", Accept: "application/json" };
    if (YOLO_INSPECTION_TOKEN) {
      headers.Authorization = `Bearer ${YOLO_INSPECTION_TOKEN}`;
    }
    const yoloResponse = await fetch(YOLO_INSPECTION_ENDPOINT, {
      method: "POST",
      headers,
      body: JSON.stringify({
        productId: String(product?.id ?? "").trim(),
        model: YOLO_INSPECTION_MODEL,
        images: imageUrls.map((imageUrl) => ({
          imageUrl,
          sourceUrl: getYoloServiceImageUrl(imageUrl),
        })),
        datasetBucket,
        autoReject: false,
      }),
      signal: abortController.signal,
    });
    const payload = await yoloResponse.json().catch(() => ({}));
    if (!yoloResponse.ok) {
      throw new Error(payload.message || `YOLO inspection failed (${yoloResponse.status}).`);
    }

    const imageResults = Array.isArray(payload.images)
      ? payload.images
      : Array.isArray(payload.results)
        ? payload.results
        : [];
    const flagged =
      payload.flagged === true ||
      imageResults.some((entry) => entry?.flagged === true);
    return normalizeYoloInspection({
      status: flagged ? "flagged" : "clear",
      flagged,
      confidence: payload.confidence ?? payload.score ?? payload.probability,
      model: payload.model || YOLO_INSPECTION_MODEL,
      datasetBucket,
      imageUrls,
      images: imageResults,
      detections: payload.detections,
      requestedAt: now,
      inspectedAt: now,
      updatedAt: now,
    }, imageUrls);
  } catch (error) {
    return normalizeYoloInspection({
      ...queuedInspection,
      status: "error",
      error: error instanceof Error ? error.message : "Unable to run YOLO inspection.",
      updatedAt: now,
    }, imageUrls);
  } finally {
    clearTimeout(timeoutId);
  }
}

