  async function handleSellerFollowersOverviewApi(request, response) {
    if (!requireSuperAdmin(request, response)) {
      return;
    }

    try {
      const [followers, products, accounts] = await Promise.all([readFollowers(), readProducts(), readAccounts()]);
      const perSeller = Object.keys(followers || {}).map((adminId) => {
        const normalized = normalizeAdminTenantId(adminId, "");
        return {
          adminId: normalized,
          followersCount: Array.isArray(followers[adminId]) ? followers[adminId].length : 0,
          productCount: products.filter((p) => normalizeAdminTenantId(getRecordAdminId(p, p.adminId), "") === normalized).length,
          account: accounts.find((a) => getRecordAdminId(a, a.adminId) === normalized) || null,
        };
      });

      const totalFollowers = perSeller.reduce((sum, s) => sum + Number(s.followersCount || 0), 0);
      sendJson(response, 200, { totalFollowers, perSeller });
    } catch (error) {
      sendJson(response, 500, { message: error instanceof Error ? error.message : "Unable to load followers overview." });
    }
  }

  function serializeSellerSummary(account, products = [], counts = null) {
    const safeAccount = serializeAdminAccount(account, counts);
    const adminId = getRecordAdminId(safeAccount, safeAccount.adminId);
    const sellerProducts = (Array.isArray(products) ? products : []).filter(
      (product) => getRecordAdminId(product, product?.adminId) === adminId,
    );
    const productCompanyPictureUrl = sellerProducts
      .map((product) => String(product?.companyPictureUrl ?? "").trim())
      .find(Boolean) || "";
    const companyName = [
      safeAccount.companyName,
      safeAccount.storeName,
      safeAccount.businessName,
      safeAccount.displayName,
    ]
      .map((value) => String(value ?? "").replace(/\s+/g, " ").trim())
      .find(Boolean) || "";
    const imageUrl = [
      safeAccount.companyPictureUrl,
      safeAccount.companyProfileImageUrl,
      safeAccount.profileImageUrl,
      safeAccount.logoUrl,
      safeAccount.avatarUrl,
      safeAccount.photoUrl,
      productCompanyPictureUrl,
    ]
      .map((value) => String(value ?? "").trim())
      .find(Boolean) || "";

    const isLegitSeller = Boolean(safeAccount.legitimateBadge);

    return {
      adminId,
      name: companyName || adminId,
      companyName,
      storeName: safeAccount.storeName || companyName,
      businessName: safeAccount.businessName || companyName,
      storeType: safeAccount.storeType || safeAccount.storeTypeName || safeAccount.businessType || "",
      storeTypeName: safeAccount.storeTypeName || safeAccount.storeType || safeAccount.storeTypeName || "",
      businessType: safeAccount.businessType || safeAccount.storeType || safeAccount.storeTypeName || "",
      profileImageUrl: imageUrl,
      companyPictureUrl: imageUrl,
      createdAt: safeAccount.createdAt || "",
      productCount: sellerProducts.length,
      planName: "Free",
      hasPaidPlan: false,
      isLegitSeller,
      legitimateBadge: isLegitSeller,
      performanceBadge: safeAccount.performanceBadge || null,
    };
  }

  async function handleSellersApi(request, response) {
    if (request.method !== "GET") {
      sendJson(response, 405, { message: "Method not allowed." });
      return;
    }

    try {
      const [accounts, products, storedStoreTypes, orders, chatThreads] = await Promise.all([
        readAccounts(),
        readProducts(),
        readStoreTypes(),
        readOrders(),
        readChatThreads(),
      ]);
      const performanceCountsByAdminId = buildSellerPerformanceCountsByAdminId({
        accounts,
        products,
        orders,
        chatThreads,
        storeTypes: storedStoreTypes,
      });
      const normalizedProducts = attachProductsCompanyMetadata(
        filterProductsHiddenBySellerOrStoreTypeInactivity(
          hideInactiveStoreTypeCategoriesFromProducts(
            products.map(normalizeStoredProductRecord),
            accounts,
            storedStoreTypes,
          ),
          accounts,
          storedStoreTypes,
        ),
        accounts,
        performanceCountsByAdminId,
      );
      const sellers = accounts
        .filter(isAdminAccount)
        .map((account) => serializeSellerSummary(
          account,
          normalizedProducts,
          performanceCountsByAdminId.get(getRecordAdminId(account, account.id)),
        ))
        .filter((seller) => seller.adminId)
        .sort((left, right) => {
          const leftName = String(left.companyName || left.name || "").toLowerCase();
          const rightName = String(right.companyName || right.name || "").toLowerCase();
          return leftName.localeCompare(rightName);
        });

      sendJson(response, 200, {
        sellers,
        total: sellers.length,
      });
    } catch (error) {
      sendJson(response, 500, {
        message:
          error instanceof Error
            ? error.message
            : "Unable to load sellers.",
      });
    }
  }

  // GET /api/sellers/:adminId/profile - Get seller profile info (name, picture, rating)
  async function handleSellerProfileApi(request, response, sellerAdminId) {
    try {
      const [products, accounts, followers, orders] = await Promise.all([
        readProducts(),
        readAccounts(),
        readFollowers(),
        readOrders(),
      ]);
      const normalized = normalizeAdminTenantId(sellerAdminId, "");
      const account = accounts.find((a) => normalizeAdminTenantId(getRecordAdminId(a, a.adminId), "") === normalized);
      const sellerProducts = products.filter((p) => normalizeAdminTenantId(getRecordAdminId(p, p.adminId), "") === normalized);
      const reviewSummary = summarizeProductReviewAggregatesForProducts(
        sellerProducts,
        buildProductReviewAggregates(orders, normalized),
      );

      const followerCount = getFollowersListForAdmin(followers, normalized).length;
      const productCompanyPictureUrl = sellerProducts
        .map((product) => String(product?.companyPictureUrl ?? "").trim())
        .find(Boolean) || "";

      const requestUrl = new URL(request.url, `http://127.0.0.1:${PORT}`);
      const companyId = [
        requestUrl.searchParams.get("companyId"),
        ...sellerProducts.map((product) => product?.companyId),
        account?.activeCompanyId,
        account?.companyId,
      ]
        .map((value) => String(value ?? "").trim())
        .find(Boolean) || "";
      let profileSource = account || {};
      let verified = false;
      if (companyId) {
        try {
          const company = await findCompanyById(companyId);
          if (company) {
            profileSource = applyCompanyWorkspaceOverlay({ ...profileSource }, company);
            verified = String(company.verificationStatus || "").trim().toLowerCase() === "verified";
          }
        } catch (companyError) {
          console.warn("Unable to load company branding for seller profile:", companyError);
        }
      }
      const companyBackgroundUrl = [
        profileSource.companyBackgroundUrl,
        profileSource.company_background_url,
        profileSource.backgroundUrl,
        profileSource.background_url,
        profileSource.coverImageUrl,
        profileSource.cover_image_url,
        profileSource.bannerUrl,
        profileSource.banner_url,
        profileSource.heroImageUrl,
        profileSource.profileData?.companyBackgroundUrl,
        profileSource.profileData?.backgroundUrl,
        profileSource.profileData?.coverImageUrl,
      ]
        .map((value) => String(value ?? "").trim())
        .find(Boolean) || "";

      sendJson(response, 200, {
        adminId: normalized,
        companyId,
        name: profileSource.storeName || profileSource.companyName || profileSource.businessName || profileSource.firstName || normalized,
        profileImageUrl: account?.profileImageUrl || productCompanyPictureUrl || "",
        companyPictureUrl: productCompanyPictureUrl || profileSource.companyPictureUrl || account?.profileImageUrl || "",
        companyBackgroundUrl,
        verified,
        storeType: String(profileSource.storeTypeName || profileSource.storeType || profileSource.businessType || "").trim(),
        rating: reviewSummary.rating,
        ratingCount: reviewSummary.ratingCount,
        ratingPoints: reviewSummary.ratingPoints,
        commentCount: reviewSummary.commentCount,
        reviewCount: reviewSummary.reviewCount,
        productCount: sellerProducts.length,
        followerCount,
      });
    } catch (error) {
      sendJson(response, 500, { message: error instanceof Error ? error.message : "Unable to load seller profile." });
    }
  }

  async function handleAdminFollowersCountApi(request, response) {
    try {
      const requestUrl = new URL(request.url, `http://127.0.0.1:${PORT}`);
      const requestAdminId = getRequestAdminId(request, requestUrl);
      const normalized = normalizeAdminTenantId(requestAdminId, "");

      if (!normalized) {
        sendJson(response, 401, { message: "Unauthorized. Admin ID required." });
        return;
      }

      const followers = await readFollowers();
      const followerCount = getFollowersListForAdmin(followers, normalized).length;

      sendJson(response, 200, {
        adminId: normalized,
        followerCount,
        followersCount: followerCount,
      });
    } catch (error) {
      sendJson(response, 500, { message: error instanceof Error ? error.message : "Unable to load followers count." });
    }
  }

async function handleSingleChatSupportApi(request, response, threadId, action = "") {
  const requestUrl = new URL(request.url, `http://127.0.0.1:${PORT}`);
  const requestAdminId = getRequestAdminId(request, requestUrl);
  const normalizedThreadId = String(threadId ?? "").trim();
  if (!normalizedThreadId) {
    sendJson(response, 400, { message: "Thread ID is required." });
    return;
  }

  if (request.method === "GET" && !action) {
    try {
      const threads = await readNormalizedChatThreads(requestAdminId);
      const thread = threads.find((candidate) => candidate.threadId === normalizedThreadId);

      if (!thread) {
        sendJson(response, 404, { message: "Chat thread not found." });
        return;
      }

      sendJson(response, 200, {
        thread,
        aiAssistant: await getChatAiAssistantStatusPayload(),
      });
    } catch (error) {
      sendJson(response, 500, {
        message: error instanceof Error ? error.message : "Unable to load chat thread.",
      });
    }
    return;
  }

  if (request.method === "DELETE" && !action) {
    try {
      const threads = await readNormalizedChatThreads(requestAdminId);
      const threadIndex = findChatThreadIndex(threads, normalizedThreadId);

      if (threadIndex < 0) {
        sendJson(response, 404, { message: "Chat thread not found." });
        return;
      }

      const nextThreads = threads.filter(
        (thread) => thread.threadId !== normalizedThreadId,
      );
      await writeNormalizedChatThreadsForAdmin(
        requestAdminId,
        sortChatThreadsByUpdatedAt(mergeChatThreadsByCustomer(nextThreads)),
      );
      sendJson(response, 200, {
        deletedId: normalizedThreadId,
        message: "Chat thread deleted.",
      });
    } catch (error) {
      sendJson(response, 500, {
        message: error instanceof Error ? error.message : "Unable to delete chat thread.",
      });
    }
    return;
  }

  if ((request.method === "POST" || request.method === "PUT") && action === "typing") {
    try {
      const payload = await parseRequestBody(request);
      const actor = String(payload?.actor ?? "").trim().toLowerCase();
      if (actor !== "user" && actor !== "employee") {
        sendJson(response, 400, { message: "Typing actor is required." });
        return;
      }

      const threads = await readNormalizedChatThreads(requestAdminId);
      let threadIndex = findChatThreadIndex(threads, normalizedThreadId);

      if (threadIndex < 0) {
        const threadInput =
          payload?.thread && typeof payload.thread === "object"
            ? {
                ...payload.thread,
                threadId: normalizedThreadId,
                adminId: requestAdminId,
              }
            : null;

        if (actor !== "user" || !threadInput) {
          sendJson(response, 404, { message: "Chat thread not found." });
          return;
        }

        try {
          const createdThread = normalizeIncomingChatThread(threadInput, null);
          threads.unshift(createdThread);
          threadIndex = findChatThreadIndex(threads, normalizedThreadId);
        } catch (error) {
          sendJson(response, 404, { message: "Chat thread not found." });
          return;
        }

        if (threadIndex < 0) {
          sendJson(response, 404, { message: "Chat thread not found." });
          return;
        }
      }

      const targetThread = threads[threadIndex];
      const fallbackDisplayName =
        actor === "employee"
          ? "Employee"
          : String(targetThread.customerLabel || "").trim() || "App User";
      const updatedThread = {
        ...targetThread,
        typing: updateChatTypingState(targetThread.typing, actor, {
          isTyping: payload?.isTyping === true,
          isOnline: Object.prototype.hasOwnProperty.call(payload ?? {}, "isOnline")
            ? payload?.isOnline === true
            : undefined,
          displayName:
            String(payload?.displayName ?? payload?.name ?? "").trim() ||
            fallbackDisplayName,
          avatarUrl:
            String(payload?.avatarUrl ?? payload?.profileImageUrl ?? "").trim() ||
            (actor === "user"
              ? String(targetThread.customerAvatarUrl ?? targetThread.profileImageUrl ?? "").trim()
              : ""),
        }),
      };

      threads[threadIndex] = updatedThread;
      const sortedThreads = sortChatThreadsByUpdatedAt(mergeChatThreadsByCustomer(threads));
      await writeNormalizedChatThreadsForAdmin(requestAdminId, sortedThreads);
      sendJson(response, 200, {
        thread: updatedThread,
        message: payload?.isTyping === true ? "Typing state updated." : "Typing state cleared.",
      });
    } catch (error) {
      sendJson(response, 400, {
        message:
          error instanceof Error ? error.message : "Unable to update typing state.",
      });
    }
    return;
  }

  if (request.method === "POST" && action === "reply") {
    try {
      if (
        !(await requirePlatformSettingEnabled(
          response,
          "liveChat",
          "Live chat is currently disabled by Super Admin.",
        ))
      ) {
        return;
      }
      const payload = await parseRequestBody(request);
      const replyText = String(payload?.text ?? "").replace(/\s+/g, " ").trim();
      const replyImageUrl = String(payload?.imageUrl ?? "").trim();
      const replyImageName = String(payload?.imageName ?? "").trim();
      const replyContentType = String(payload?.contentType ?? payload?.mimeType ?? "").trim();
      const replyTo = normalizeChatReplyReference(payload?.replyTo);
      const hasDeclaredActor = Boolean(
        normalizeChatSenderField(
          payload?.actorRole ??
            payload?.senderRole ??
            payload?.actor?.role,
        ) ||
        String(
          payload?.actorId ??
            payload?.senderId ??
            payload?.actor?.id ??
            payload?.actor?.accountId ??
            "",
        ).trim(),
      );
      const replyActor = hasDeclaredActor
        ? await resolveChatSupportActor(payload, requestAdminId)
        : null;
      if (!replyText && !replyImageUrl) {
        throw new Error("Reply message or attachment is required.");
      }
      if (hasDeclaredActor && !replyActor) {
        sendJson(response, 403, {
          message: "Unable to verify the support account sending this reply.",
        });
        return;
      }

      const threads = await readNormalizedChatThreads(requestAdminId);
      const threadIndex = findChatThreadIndex(threads, normalizedThreadId);

      if (threadIndex < 0) {
        sendJson(response, 404, { message: "Chat thread not found." });
        return;
      }

      const targetThread = threads[threadIndex];
      const replyMessage = normalizeChatMessage({
        id: createChatMessageId(true),
        text: replyText,
        imageUrl: replyImageUrl,
        imageName: replyImageName,
        contentType: replyContentType,
        isFromSupport: true,
        source: "support",
        timestamp: new Date().toISOString(),
        replyTo,
        ...(replyActor || { senderRole: "support" }),
      });
      if (!replyMessage) {
        throw new Error("Reply message or attachment is required.");
      }

      const updatedThread = normalizeIncomingChatThread(
        {
          ...targetThread,
          messages: [...targetThread.messages, replyMessage],
          updatedAt: replyMessage.timestamp,
          supportReadAt: replyMessage.timestamp,
        },
        targetThread,
      );

      const updatedThreadWithTyping = {
        ...updatedThread,
        typing: updateChatTypingState(updatedThread.typing, "employee", {
          isTyping: false,
        }),
      };

      threads[threadIndex] = updatedThreadWithTyping;
      const sortedThreads = sortChatThreadsByUpdatedAt(mergeChatThreadsByCustomer(threads));
      await writeNormalizedChatThreadsForAdmin(requestAdminId, sortedThreads);
      sendJson(response, 200, {
        thread: updatedThreadWithTyping,
        message: "Reply sent.",
      });
    } catch (error) {
      sendJson(response, 400, {
        message: error instanceof Error ? error.message : "Unable to send reply.",
      });
    }
    return;
  }

  if (
    (request.method === "PUT" || request.method === "POST") &&
    action === "edit-message"
  ) {
    try {
      const payload = await parseRequestBody(request);
      const messageId = String(payload?.messageId ?? "").trim();
      const nextText = String(payload?.text ?? "").replace(/\s+/g, " ").trim();
      if (!messageId || !nextText) {
        throw new Error("Message ID and updated text are required.");
      }
      if (!hasRequestAdminScope(request, requestUrl)) {
        sendJson(response, 401, { message: "Admin workspace identity is required." });
        return;
      }
      const editActor = await resolveChatSupportActor(payload, requestAdminId);
      if (!editActor || editActor.senderRole !== "admin") {
        sendJson(response, 403, {
          message: "Employees cannot edit messages. Only the admin who sent this message can edit it.",
        });
        return;
      }

      const threads = await readNormalizedChatThreads(requestAdminId);
      const threadIndex = findChatThreadIndex(threads, normalizedThreadId);

      if (threadIndex < 0) {
        sendJson(response, 404, { message: "Chat thread not found." });
        return;
      }

      const targetThread = threads[threadIndex];
      const targetMessage = Array.isArray(targetThread.messages)
        ? targetThread.messages.find((message) => String(message?.id || "").trim() === messageId)
        : null;
      if (!targetMessage) {
        sendJson(response, 404, { message: "Chat message not found." });
        return;
      }

      if (String(targetMessage.source || "").trim().toLowerCase() === "ai") {
        sendJson(response, 403, { message: "AI messages cannot be edited." });
        return;
      }

      if (targetMessage.deletedAt) {
        sendJson(response, 403, { message: "Deleted messages cannot be edited." });
        return;
      }

      const targetIsFromSupport = targetMessage.isFromSupport === true;
      const targetSenderRole = normalizeChatSupportActorRole(targetMessage.senderRole);
      const targetSenderId = String(targetMessage.senderId ?? "").trim().toLowerCase();
      const editActorId = String(editActor.senderId ?? "").trim().toLowerCase();
      if (
        !targetIsFromSupport ||
        targetSenderRole !== "admin" ||
        !targetSenderId ||
        !editActorId ||
        targetSenderId !== editActorId
      ) {
        sendJson(response, 403, {
          message: "Only your own admin messages can be edited.",
        });
        return;
      }
      const targetSource = String(targetMessage.source || "").trim().toLowerCase() || (
        targetIsFromSupport ? "support" : "user"
      );
      const nextEditedAt = new Date().toISOString();
      const nextMessages = (Array.isArray(targetThread.messages) ? targetThread.messages : [])
        .map((message, index) => {
          const currentMessageId = String(message?.id || "").trim();
          if (currentMessageId === messageId) {
            return normalizeChatMessage(
              {
                ...message,
                id: targetMessage.id,
                text: nextText,
                imageUrl: targetMessage.imageUrl,
                imageName: targetMessage.imageName,
                isFromSupport: targetIsFromSupport,
                source: targetSource,
                timestamp: targetMessage.timestamp,
                editedAt: nextEditedAt,
                replyTo: targetMessage.replyTo,
              },
              index,
            );
          }

          const replyTo = normalizeChatReplyReference(message?.replyTo);
          if (replyTo?.messageId === messageId) {
            return normalizeChatMessage(
              {
                ...message,
                replyTo: {
                  ...replyTo,
                  previewText: nextText,
                },
              },
              index,
            );
          }

          return normalizeChatMessage(message, index);
        })
        .filter(Boolean);

      const updatedThread = normalizeIncomingChatThread(
        {
          ...targetThread,
          messages: nextMessages,
          supportReadAt: targetThread.supportReadAt,
          lastReadAt: targetThread.lastReadAt,
        },
        null,
      );

      const updatedThreadWithTyping = {
        ...updatedThread,
        typing: updateChatTypingState(
          updatedThread.typing,
          targetIsFromSupport ? "employee" : "user",
          {
            isTyping: false,
          },
        ),
      };

      threads[threadIndex] = updatedThreadWithTyping;
      const sortedThreads = sortChatThreadsByUpdatedAt(mergeChatThreadsByCustomer(threads));
      await writeNormalizedChatThreadsForAdmin(requestAdminId, sortedThreads);
      sendJson(response, 200, {
        thread: updatedThreadWithTyping,
        message: "Message updated.",
      });
    } catch (error) {
      sendJson(response, 400, {
        message: error instanceof Error ? error.message : "Unable to update message.",
      });
    }
    return;
  }

  if (request.method === "POST" && action === "delete-message") {
    try {
      const payload = await parseRequestBody(request);
      const messageId = String(payload?.messageId ?? "").trim();
      const requestCustomerId = getChatThreadCustomerId(payload).toLowerCase();
      if (!messageId) {
        throw new Error("Message ID is required.");
      }

      const threads = await readNormalizedChatThreads(requestAdminId);
      const threadIndex = findChatThreadIndex(threads, normalizedThreadId);

      if (threadIndex < 0) {
        sendJson(response, 404, { message: "Chat thread not found." });
        return;
      }

      const targetThread = threads[threadIndex];
      const targetMessage = Array.isArray(targetThread.messages)
        ? targetThread.messages.find((message) => String(message?.id || "").trim() === messageId)
        : null;
      if (!targetMessage) {
        sendJson(response, 404, { message: "Chat message not found." });
        return;
      }

      if (String(targetMessage.source || "").trim().toLowerCase() === "ai") {
        sendJson(response, 403, { message: "AI messages cannot be deleted." });
        return;
      }

      if (targetMessage.isFromSupport !== true) {
        const threadCustomerId = getChatThreadCustomerId(targetThread).toLowerCase();
        if (!requestCustomerId || requestCustomerId !== threadCustomerId) {
          sendJson(response, 403, {
            message: "Customer messages can only be deleted by the message owner.",
          });
          return;
        }
      }

      if (targetMessage.deletedAt) {
        sendJson(response, 200, {
          thread: targetThread,
          message: "Message already deleted.",
        });
        return;
      }

      const targetIsFromSupport = targetMessage.isFromSupport === true;
      const targetSource = String(targetMessage.source || "").trim().toLowerCase() || (
        targetIsFromSupport ? "support" : "user"
      );
      const nextDeletedAt = new Date().toISOString();
      const nextMessages = (Array.isArray(targetThread.messages) ? targetThread.messages : [])
        .map((message, index) => {
          const currentMessageId = String(message?.id || "").trim();
          if (currentMessageId === messageId) {
            return normalizeChatMessage(
              {
                ...message,
                id: targetMessage.id,
                text: "",
                imageUrl: "",
                imageName: "",
                isFromSupport: targetIsFromSupport,
                source: targetSource,
                timestamp: targetMessage.timestamp,
                editedAt: null,
                deletedAt: nextDeletedAt,
                replyTo: null,
              },
              index,
            );
          }

          const replyTo = normalizeChatReplyReference(message?.replyTo);
          if (replyTo?.messageId === messageId) {
            return normalizeChatMessage(
              {
                ...message,
                replyTo: null,
              },
              index,
            );
          }

          return normalizeChatMessage(message, index);
        })
        .filter(Boolean);

      const updatedThread = normalizeIncomingChatThread(
        {
          ...targetThread,
          messages: nextMessages,
          updatedAt: nextDeletedAt,
          supportReadAt: targetThread.supportReadAt,
          lastReadAt: targetThread.lastReadAt,
        },
        null,
      );

      const updatedThreadWithTyping = {
        ...updatedThread,
        typing: updateChatTypingState(
          updatedThread.typing,
          targetIsFromSupport ? "employee" : "user",
          {
            isTyping: false,
          },
        ),
      };

      threads[threadIndex] = updatedThreadWithTyping;
      const sortedThreads = sortChatThreadsByUpdatedAt(mergeChatThreadsByCustomer(threads));
      await writeNormalizedChatThreadsForAdmin(requestAdminId, sortedThreads);
      sendJson(response, 200, {
        thread: updatedThreadWithTyping,
        message: "Message deleted.",
      });
    } catch (error) {
      sendJson(response, 400, {
        message: error instanceof Error ? error.message : "Unable to delete message.",
      });
    }
    return;
  }

  if (request.method === "POST" && action === "ai-reply") {
    try {
      const threads = await readNormalizedChatThreads(requestAdminId);
      const threadIndex = findChatThreadIndex(threads, normalizedThreadId);

      if (threadIndex < 0) {
        sendJson(response, 404, { message: "Chat thread not found." });
        return;
      }

      const targetThread = threads[threadIndex];
      const aiReplyText = await requestChatAiReply(targetThread, "chatbot");
      const aiReplyMessage = normalizeChatMessage({
        id: createChatMessageId(true),
        text: aiReplyText,
        isFromSupport: true,
        source: "ai",
        timestamp: new Date().toISOString(),
      });

      const updatedThread = normalizeIncomingChatThread(
        {
          ...targetThread,
          messages: [...targetThread.messages, aiReplyMessage],
          updatedAt: aiReplyMessage.timestamp,
        },
        targetThread,
      );

      threads[threadIndex] = updatedThread;
      const sortedThreads = sortChatThreadsByUpdatedAt(mergeChatThreadsByCustomer(threads));
      await writeNormalizedChatThreadsForAdmin(requestAdminId, sortedThreads);
      sendJson(response, 200, {
        thread: updatedThread,
        aiAssistant: await getChatAiAssistantStatusPayload(),
        message: "AI reply sent.",
      });
    } catch (error) {
      sendJson(response, 503, {
        message: error instanceof Error ? error.message : "Unable to get AI reply.",
      });
    }
    return;
  }

  if (request.method === "POST" && action === "read-support") {
    try {
      const threads = await readNormalizedChatThreads(requestAdminId);
      const threadIndex = findChatThreadIndex(threads, normalizedThreadId);

      if (threadIndex < 0) {
        sendJson(response, 404, { message: "Chat thread not found." });
        return;
      }

      const targetThread = threads[threadIndex];
      const latestSeenTimestamp = targetThread.messages.length
        ? normalizeChatTimestamp(targetThread.messages[targetThread.messages.length - 1].timestamp)
        : normalizeChatTimestamp(targetThread.updatedAt);
      const currentSupportReadAt = normalizeOptionalChatTimestamp(targetThread.supportReadAt);
      const effectiveSupportReadAt =
        currentSupportReadAt && currentSupportReadAt.getTime() > latestSeenTimestamp.getTime()
          ? currentSupportReadAt
          : latestSeenTimestamp;

      const updatedThread = normalizeIncomingChatThread(
        {
          ...targetThread,
          supportReadAt: effectiveSupportReadAt.toISOString(),
        },
        targetThread,
      );

      threads[threadIndex] = updatedThread;
      const sortedThreads = sortChatThreadsByUpdatedAt(mergeChatThreadsByCustomer(threads));
      await writeNormalizedChatThreadsForAdmin(requestAdminId, sortedThreads);
      sendJson(response, 200, {
        thread: updatedThread,
        message: "Chat thread marked as seen by support.",
      });
    } catch (error) {
      sendJson(response, 400, {
        message:
          error instanceof Error
            ? error.message
            : "Unable to mark chat thread as seen by support.",
      });
    }
    return;
  }

  sendJson(response, 405, { message: "Method not allowed." });
}

async function handleProductIllegalContentCheckApi(request, response) {
  const requestUrl = new URL(request.url, `http://127.0.0.1:${PORT}`);
  const requestAdminId = getExplicitRequestAdminId(request, requestUrl);

  if (request.method !== "POST") {
    sendJson(response, 405, { message: "Method not allowed." });
    return;
  }

  if (
    !(await requirePlatformSettingEnabled(
      response,
      "yoloAutoInspection",
      "YOLO auto inspection is currently disabled by Super Admin.",
    ))
  ) {
    return;
  }

  if (!isUsableProductAdminScope(requestAdminId)) {
    sendProductAdminScopeRequired(response);
    return;
  }

  try {
    const contentType = normalizeUploadMimeType(request.headers["content-type"]);
    const sourceFilename = String(request.headers["x-file-name"] ?? "product-image").trim();
    const extension = getUploadExtension(sourceFilename, contentType);
    const isImageUpload = isImageUploadType(contentType, extension);
    if (!isImageUpload) {
      throw new Error("Please send a valid product photo.");
    }

    const fileBuffer = await parseBinaryRequestBody(request);
    if (!fileBuffer.length) {
      throw new Error("Product photo is empty.");
    }

    const safety = await inspectSellerImageBufferIllegalContent(fileBuffer, {
      sourceFilename,
    });
    sendJson(response, 200, {
      checked: true,
      blocked: safety.action === "auto-reject",
      requiresReview: safety.action === "manual-review",
      yoloSafety: safety,
      message: safety.message,
    });
  } catch (error) {
    const statusCode =
      Number.isInteger(error?.statusCode) && error.statusCode >= 400
        ? error.statusCode
        : 400;
    sendJson(response, statusCode, {
      message:
        error instanceof Error
          ? error.message
          : "Unable to check product image safety.",
    });
  }
}

async function handleProductsApi(request, response) {
  const requestUrl = new URL(request.url, `http://127.0.0.1:${PORT}`);
  const requestAdminId = getExplicitRequestAdminId(request, requestUrl);
  const requestCompanyId = getExplicitRequestCompanyId(request, requestUrl);
  const requestIsAdminScoped = hasRequestAdminScope(request, requestUrl);

  if (request.method === "GET") {
    const requestedApprovalStatus = normalizeProductApprovalStatus(
      requestUrl.searchParams.get("approvalStatus"),
      "",
    );
    const hasApprovalStatusFilter = requestUrl.searchParams.has("approvalStatus");
    const allowPublicApprovedCatalog =
      !requestIsAdminScoped &&
      hasApprovalStatusFilter &&
      requestedApprovalStatus === PRODUCT_APPROVAL_APPROVED;
    if (requestIsAdminScoped && !isUsableProductAdminScope(requestAdminId)) {
      sendProductAdminScopeRequired(response);
      return;
    }

    if (!requestIsAdminScoped && !allowPublicApprovedCatalog) {
      sendProductAdminScopeRequired(response);
      return;
    }

    const [allProducts, accounts, allOrders, storedStoreTypes, chatThreads] = await Promise.all([
      requestIsAdminScoped
        ? readProducts({
            adminId: requestAdminId,
            companyId: requestCompanyId,
          })
        : readProducts({ publicCatalog: true }),
      readAccounts(),
      requestIsAdminScoped
        ? readOrders({ adminId: requestAdminId })
        : readOrders(),
      readStoreTypes(),
      readChatThreads(),
    ]);
    const reviewAggregates = buildProductReviewAggregates(
      allOrders,
      requestIsAdminScoped ? requestAdminId : null,
    );
    let products = (requestIsAdminScoped
      ? filterRecordsByAdminId(allProducts, requestAdminId)
      : allProducts
    ).map(normalizeStoredProductRecord).map((product) =>
      applyProductReviewAggregate(product, reviewAggregates),
    );
    products = hideInactiveStoreTypeCategoriesFromProducts(
      products,
      accounts,
      storedStoreTypes,
    );
    if (allowPublicApprovedCatalog) {
      products = filterProductsHiddenBySellerOrStoreTypeInactivity(
        products,
        accounts,
        storedStoreTypes,
      );
    }
    if (hasApprovalStatusFilter) {
      products = products.filter((product) =>
        normalizeProductApprovalStatus(product?.approvalStatus) === requestedApprovalStatus
      );
    }
    if (allowPublicApprovedCatalog) {
      products = products.filter((product) =>
        !isProductListingRestrictedForCustomers(product)
      );
    }
    products = attachProductsCompanyMetadata(
      products,
      accounts,
      buildSellerPerformanceCountsByAdminId({
        accounts,
        products: allProducts,
        orders: allOrders,
        chatThreads,
        storeTypes: storedStoreTypes,
      }),
    );
    const pagination = parsePagination(requestUrl.searchParams);
    const page = paginateArray(products, pagination);
    const payload = { products: page.items };
    if (pagination.enabled) {
      payload.pagination = buildPaginationMeta(page);
    }
    sendJson(response, 200, payload);
    return;
  }

  if (request.method === "POST") {
    try {
      if (!isUsableProductAdminScope(requestAdminId)) {
        sendProductAdminScopeRequired(response);
        return;
      }

      if (
        !(await requirePlatformSettingEnabled(
          response,
          "sellerProductSubmissions",
          "Product submissions are currently disabled by Super Admin.",
        ))
      ) {
        return;
      }

      if (
        !(await requireAdminRestrictionAllowed(
          request,
          response,
          requestUrl,
          "post_products",
          requestAdminId,
        ))
      ) {
        return;
      }

      const payload = await parseRequestBody(request);
      assertSessionPayloadIdentity(request, payload, { admin: true });
      if (
        doesProductPayloadChangePromotion(payload) &&
        !(await requirePlatformSettingEnabled(
          response,
          "promosAndDiscounts",
          "Promos and discounts are currently disabled by Super Admin.",
        ))
      ) {
        return;
      }
      if (
        doesProductPayloadChangePromotion(payload) &&
        !(await requireAdminRestrictionAllowed(
          request,
          response,
          requestUrl,
          "create_promos",
          requestAdminId,
        ))
      ) {
        return;
      }

      const stampedCompanyId =
        requestCompanyId
        || String(payload.companyId ?? "").trim()
        || legacyCompanyIdForAdmin(requestAdminId);
      const submittedAt = new Date().toISOString();
      let product = applyAdminId(normalizeProduct({
        ...payload,
        adminId: requestAdminId,
        companyId: stampedCompanyId,
        approvalStatus: PRODUCT_APPROVAL_PENDING,
        submittedAt,
        approvedAt: "",
        approvedBy: "",
        approvalUpdatedAt: submittedAt,
      }), requestAdminId);
      product = {
        ...product,
        companyId: stampedCompanyId,
      };
      product = await applyAdminBusinessTypeCategoryScope(product, requestAdminId);
      product = await validateProductPartnerSelections(product, requestAdminId);
      assertProductSpecificationsComplete(product);
      let products = await readProducts();
      product = syncProductVariantAddOnsWithInventory(product, products, requestAdminId);

      // Check for duplicate barcode
      const barcodeValue = String(product.barcode ?? "").trim();
      if (barcodeValue) {
        const duplicateBarcode = products.find((p) =>
          isRecordInAdminScope(p, requestAdminId) &&
          String(p.barcode ?? "").trim() === barcodeValue
        );
        if (duplicateBarcode) {
          throw new Error("Barcode already exists. Please use a different barcode.");
        }
      }

      product = await syncProductVisualSearchFingerprint(product);
      const illegalContentGate = await inspectSellerProductIllegalContent(product, products);
      product = illegalContentGate.product;
      products = illegalContentGate.products;
      if (illegalContentGate.safety.action === "auto-reject") {
        product = await applySellerIllegalContentAutoReject(
          product,
          illegalContentGate.safety,
        );
        products.unshift(product);
        await writeProducts(products, catalogWriteScope({
          adminId: requestAdminId,
          companyId: stampedCompanyId,
        }));
        await syncRejectedProductTrainingArchive([product]);
        await logActivitySafely(createProductActivityEntry("updated", product, payload?.__activityActor), request);
        const companyMetadataByAdminId = getProductCompanyMetadataByAdminId(await readAccounts());
        sendJson(response, 422, {
          code: "PRODUCT_ILLEGAL_CONTENT_AUTO_REJECTED",
          product: attachProductCompanyMetadata(
            normalizeStoredProductRecord(product),
            companyMetadataByAdminId,
          ),
          yoloSafety: illegalContentGate.safety,
          message: "This content is illegal and cannot be listed.",
        });
        return;
      }
      const evidenceMatch = await applyRejectedProductEvidenceMatch(product, products);
      product = evidenceMatch.product;
      products = evidenceMatch.products;
      const autoApproval = await applyApprovedProductEvidenceAutoApproval(product, products);
      product = autoApproval.product;
      products = autoApproval.products;
      if (!autoApproval.match) {
        const approvedEvidenceMatch = await applyApprovedProductEvidenceCategoryMatch(product, products);
        product = approvedEvidenceMatch.product;
        products = approvedEvidenceMatch.products;
        product = applyProductRevisionSignal(product);
      }
      product = {
        ...product,
        companyId: stampedCompanyId,
        ...normalizeProductListingInsightHistory(product),
      };
      products.unshift(product);
      await writeProducts(products, catalogWriteScope({
        adminId: requestAdminId,
        companyId: stampedCompanyId,
      }));
      if (isApprovedProductYoloTrainingRecord(product)) {
        await syncApprovedProductTrainingArchive([product]);
      }
      await logActivitySafely(createProductActivityEntry("created", product, payload?.__activityActor), request);
      if (isProductPendingApproval(product)) {
        const actorLabel = String(
          payload?.__activityActor?.displayName ||
            payload?.__activityActor?.name ||
            "Seller",
        ).trim() || "Seller";
        await notifySuperAdminListingSubmission(product, {
          action: "submitted",
          actorLabel,
        });
      }
      const companyMetadataByAdminId = getProductCompanyMetadataByAdminId(await readAccounts());
      sendJson(response, 201, {
        product: attachProductCompanyMetadata(
          normalizeStoredProductRecord(product),
          companyMetadataByAdminId,
        ),
        message: evidenceMatch.match
          ? "Product submitted for super admin review and flagged against rejected YOLO evidence."
          : autoApproval.match
            ? "Product auto-approved from the approved YOLO database."
          : illegalContentGate.safety.action === "manual-review"
            ? "Product submitted for super admin review because YOLO detected a possible policy issue."
          : "Product submitted for super admin review.",
      });
    } catch (error) {
      sendJson(response, 400, {
        message: error instanceof Error ? error.message : "Unable to save product.",
      });
    }
    return;
  }

  sendJson(response, 405, { message: "Method not allowed." });
}

// Super admin: get products by company (adminId)
async function handleSuperAdminProductsApi(request, response, adminId) {
  if (request.method === "DELETE") {
    if (!requireSuperAdmin(request, response)) {
      return;
    }

    const target = parseApprovedTrainingDisplayProductId(adminId);
    const targetIds = new Set([
      target.rawProductId,
      target.sourceProductId,
    ].map((value) => String(value || "").trim()).filter(Boolean));
    if (!targetIds.size) {
      sendJson(response, 400, { message: "Product ID is required." });
      return;
    }

    try {
      const [products, approvedTrainingRecords] = await Promise.all([
        readProducts(),
        readApprovedProductTrainingRecords(),
      ]);
      let deletedProduct = null;
      const nextProducts = products.filter((product) => {
        const productId = String(product?.id ?? "").trim();
        const shouldDelete = targetIds.has(productId);
        if (shouldDelete && !deletedProduct) {
          deletedProduct = product;
        }
        return !shouldDelete;
      });
      let didDeleteApprovedRecord = false;
      const nextApprovedTrainingRecords = approvedTrainingRecords.filter((record) => {
        const normalizedRecord = normalizeApprovedProductTrainingArchiveRecord(record);
        const archiveKey = normalizedRecord ? getApprovedProductTrainingArchiveKey(normalizedRecord) : "";
        const shouldDelete = archiveKey && targetIds.has(archiveKey);
        if (shouldDelete) {
          didDeleteApprovedRecord = true;
        }
        return !shouldDelete;
      });

      if (!deletedProduct && !didDeleteApprovedRecord) {
        sendJson(response, 404, { message: "Product not found." });
        return;
      }

      if (nextProducts.length !== products.length) {
        await writeProducts(nextProducts);
      }
      if (didDeleteApprovedRecord) {
        await writeApprovedProductTrainingRecords(nextApprovedTrainingRecords);
      }
      if (deletedProduct) {
        await logActivitySafely(createProductActivityEntry("deleted", deletedProduct, SUPER_ADMIN_USERNAME));
        const productName = String(deletedProduct?.name ?? "Product").trim() || "Product";
        await fanOutListingLifecycleNotifications({
          product: deletedProduct,
          type: "product-deleted",
          title: "Listing deleted by Super Admin",
          reason: "Super Admin deleted listing",
          message: `Listing "${productName}" was deleted by Super Admin.`,
          sellerTitle: "Listing Deleted",
          sellerMessage: `Your listing "${productName}" was deleted by Super Admin.`,
          sellerTargetUrl: "/product_panel.html",
          saTargetUrl: "/super_admin.html#product-requests",
          notifySuperAdmin: false,
          persistAccounts: true,
        });
      }

      sendJson(response, 200, {
        message: "Product deleted.",
        deletedId: target.rawProductId,
        sourceProductId: target.sourceProductId,
      });
    } catch (error) {
      sendJson(response, 500, {
        message: error instanceof Error ? error.message : "Unable to delete product.",
      });
    }
    return;
  }

  if (request.method !== "GET") {
    sendJson(response, 405, { message: "Method not allowed." });
    return;
  }

  try {
    const [allProducts, accounts, allOrders] = await Promise.all([
      readProducts(),
      readAccounts(),
      readOrders(),
    ]);

    // Filter products by adminId (company)
    const companyProducts = filterRecordsByAdminId(allProducts, adminId).map(normalizeStoredProductRecord);

    // Get company info
    const companyAccount = accounts.find((acc) => acc.id === adminId);
    const companyName = companyAccount?.companyName || companyAccount?.businessName || "Unknown Company";

    const reviewAggregates = buildProductReviewAggregates(allOrders, adminId);
    const productsWithReviews = companyProducts.map((product) =>
      applyProductReviewAggregate(product, reviewAggregates),
    );

    sendJson(response, 200, {
      products: attachProductsCompanyMetadata(productsWithReviews, accounts),
      companyName,
      companyId: adminId,
    });
  } catch (error) {
    sendJson(response, 500, { message: "Unable to fetch company products." });
  }
}

async function handleProductVisualSearchApi(request, response) {
  const requestUrl = new URL(request.url, `http://127.0.0.1:${PORT}`);
  const requestAdminId = getRequestAdminId(request, requestUrl);

  if (request.method !== "POST") {
    sendJson(response, 405, { message: "Method not allowed." });
    return;
  }

  if (!sharp) {
    sendJson(response, 503, {
      message:
        'Visual product search is unavailable because the "sharp" package is not installed.',
    });
    return;
  }

  try {
    const contentType = String(request.headers["content-type"] ?? "").toLowerCase();
    const sourceFilename = String(request.headers["x-file-name"] ?? "camera.jpg");
    const extension = getUploadExtension(sourceFilename, contentType);
    const isImageUpload = isImageUploadType(contentType, extension);

    if (!isImageUpload) {
      throw new Error("Please send a valid product photo.");
    }

    const fileBuffer = await parseBinaryRequestBody(request);
    if (fileBuffer.length === 0) {
      throw new Error("Product photo is empty.");
    }

    const searchFingerprints = await createVisualSearchQueryFingerprints(fileBuffer);
    const [allStoredProducts, accounts, storedStoreTypes] = await Promise.all([
      readProducts(),
      readAccounts(),
      readStoreTypes(),
    ]);
    const storedProducts = filterRecordsByAdminId(allStoredProducts, requestAdminId);
    const inactiveCategoryIndexes = buildInactiveStoreTypeCategoryIndexes(accounts, storedStoreTypes);
    const matches = [];
    let didUpdateStoredFingerprints = false;

    for (let index = 0; index < storedProducts.length; index += 1) {
      let product = normalizeStoredProductRecord(storedProducts[index]);
      product = hideInactiveStoreTypeCategoriesFromProduct(product, inactiveCategoryIndexes);
      if (!product) {
        continue;
      }
      const visualSearchImageUrls = normalizeProductVisualSearchImageUrls(product);
      if (
        !String(product?.name ?? "").trim() ||
        !isProductApprovedForApp(product) ||
        !normalizeProductActiveState(product?.isActive, true) ||
        normalizeOptionalWholeNumber(product?.stock, 0) <= 0 ||
        !visualSearchImageUrls.length
      ) {
        continue;
      }

      let fingerprintEntries = getStoredVisualSearchFingerprintEntries(product);
      if (fingerprintEntries.length < visualSearchImageUrls.length) {
        const nextFingerprintMetas = [...(product.visualSearchFingerprints ?? [])];

        for (const imageUrl of visualSearchImageUrls) {
          const hasFingerprint = fingerprintEntries.some(
            (entry) =>
              String(entry.imageUrl ?? "").trim().toLowerCase() ===
              String(imageUrl ?? "").trim().toLowerCase(),
          );
          if (hasFingerprint) {
            continue;
          }

          const fingerprintMeta = await createProductVisualSearchFingerprintMeta(
            product,
            imageUrl,
          );
          if (fingerprintMeta) {
            nextFingerprintMetas.push(fingerprintMeta);
          }
        }

        product = {
          ...product,
          visualSearchFingerprints: normalizeVisualSearchFingerprintMetaList(
            nextFingerprintMetas,
            visualSearchImageUrls,
          ),
        };
        product.visualSearchFingerprint = product.visualSearchFingerprints[0] ?? null;
        fingerprintEntries = getStoredVisualSearchFingerprintEntries(product);
      }

      if (!fingerprintEntries.length) {
        const fingerprintMeta = await createProductVisualSearchFingerprintMeta(
          product,
          visualSearchImageUrls[0],
        );
        if (!fingerprintMeta) {
          continue;
        }

        product = {
          ...product,
          visualSearchFingerprint: fingerprintMeta,
          visualSearchFingerprints: [fingerprintMeta],
        };
        fingerprintEntries = getStoredVisualSearchFingerprintEntries(product);
      }

      if (!fingerprintEntries.length) {
        continue;
      }

      let bestScore = 0;
      let matchedImageUrl = "";
      for (const entry of fingerprintEntries) {
        for (const searchFingerprint of searchFingerprints) {
          const score = compareVisualSearchFingerprints(
            searchFingerprint,
            entry.fingerprint,
          );
          if (score > bestScore) {
            bestScore = score;
            matchedImageUrl = String(entry.imageUrl ?? "").trim();
          }
        }
      }

      if (JSON.stringify(storedProducts[index]?.visualSearchFingerprints ?? []) !==
        JSON.stringify(product.visualSearchFingerprints ?? [])) {
        storedProducts[index] = {
          ...storedProducts[index],
          visualSearchImageUrl: product.visualSearchImageUrl,
          visualSearchImageUrls: product.visualSearchImageUrls,
          visualSearchImageAngles: product.visualSearchImageAngles,
          visualSearchFingerprint: product.visualSearchFingerprint,
          visualSearchFingerprints: product.visualSearchFingerprints,
        };
        didUpdateStoredFingerprints = true;
      }

      if (bestScore >= VISUAL_SEARCH_MIN_SCORE) {
        matches.push({
          ...product,
          visualSearchScore: Number(bestScore.toFixed(4)),
          visualSearchMatchedImageUrl: matchedImageUrl,
        });
      }
    }

    if (didUpdateStoredFingerprints) {
      const updatedProductsById = new Map(
        storedProducts.map((product) => [String(product?.id ?? "").trim(), product]),
      );
      await writeProducts(
        allStoredProducts.map((product) =>
          updatedProductsById.get(String(product?.id ?? "").trim()) ?? product,
        ),
        catalogWriteScope({ adminId: requestAdminId }),
      );
    }

    matches.sort(
      (first, second) =>
        Number(second.visualSearchScore ?? 0) - Number(first.visualSearchScore ?? 0),
    );

    sendJson(response, 200, {
      products: attachProductsCompanyMetadata(
        matches.slice(0, VISUAL_SEARCH_MAX_RESULTS),
        accounts,
      ),
      total: matches.length,
      message: matches.length
        ? "Visual matches found."
        : "No visual match found.",
    });
  } catch (error) {
    const statusCode =
      Number.isInteger(error?.statusCode) && error.statusCode >= 400
        ? error.statusCode
        : 400;
    sendJson(response, statusCode, {
      message:
        error instanceof Error
          ? error.message
          : "Unable to search products by photo.",
    });
  }
}

function getPartnerResourceConfig(partnerType) {
  if (partnerType === "delivery") {
    return {
      type: "delivery",
      label: "Delivery partner",
      pluralLabel: "delivery partners",
      referenceField: "deliveryPartnerIds",
      read: readDeliveryPartners,
      write: writeDeliveryPartners,
      normalize: normalizeDeliveryPartnerRecord,
      permission: "",
    };
  }
  return {
    type: "payment",
    label: "Payment partner",
    pluralLabel: "payment partners",
    referenceField: "paymentPartnerIds",
    read: readPaymentPartners,
    write: writePaymentPartners,
    normalize: normalizePaymentPartnerRecord,
    permission: "access_payouts",
  };
}

function createPartnerApiError(statusCode, message, code = "PARTNER_REQUEST_FAILED", details = {}) {
  const error = new Error(message);
  error.statusCode = statusCode;
  error.code = code;
  error.details = details && typeof details === "object" ? details : {};
  return error;
}

function sendPartnerApiError(response, error, fallbackMessage) {
  const statusCode = Number.isInteger(error?.statusCode)
    ? error.statusCode
    : error?.code === "INVALID_STORAGE_DATA"
      ? 500
      : 400;
  sendJson(response, statusCode, {
    message: error instanceof Error ? error.message : fallbackMessage,
    ...(String(error?.code ?? "").trim() ? { code: String(error.code).trim() } : {}),
    ...(error?.details && typeof error.details === "object" ? error.details : {}),
  });
}

function serializePartnerRecord(partner, usage = null) {
  const record = partner && typeof partner === "object" ? partner : {};
  const { apiKey: storedApiKey, ...publicRecord } = record;
  const hasApiKey = Boolean(String(storedApiKey ?? "").trim());
  const archived = isPartnerArchived(record);
  const isActive = !archived && normalizePartnerEnabledState(record);
  const createdAt = String(record.createdAt ?? "").trim();
  const updatedAt = String(record.updatedAt ?? "").trim() || createdAt;
  return {
    ...publicRecord,
    hasApiKey,
    apiKeyMasked: hasApiKey ? "*******" : "",
    isActive,
    enabled: isActive,
    isEnabled: isActive,
    disabled: !isActive,
    status: archived ? "archived" : isActive ? "active" : "inactive",
    version: getPartnerVersion(record),
    createdAt,
    updatedAt,
    ...(usage ? {
      usage,
      connectedProductCount: usage.connectedProductCount,
    } : {}),
  };
}

function parsePartnerQueryBoolean(value, fallback = false) {
  const normalizedValue = String(value ?? "").trim().toLowerCase();
  if (["1", "true", "yes", "on"].includes(normalizedValue)) return true;
  if (["0", "false", "no", "off"].includes(normalizedValue)) return false;
  return fallback;
}

function getPartnerSearchText(partner) {
  return [
    partner?.id,
    partner?.branch,
    partner?.name,
    partner?.description,
    partner?.adminId,
    partner?.status,
  ].join(" ").toLowerCase();
}

function getPartnerDateValue(partner, field) {
  const timestamp = Date.parse(String(partner?.[field] ?? ""));
  return Number.isFinite(timestamp) ? timestamp : 0;
}

function getPartnerCollectionSummary(records) {
  const sourceRecords = Array.isArray(records) ? records : [];
  const archived = sourceRecords.filter(isPartnerArchived).length;
  const currentRecords = sourceRecords.filter((partner) => !isPartnerArchived(partner));
  const active = currentRecords.filter(normalizePartnerEnabledState).length;
  const inactive = Math.max(0, currentRecords.length - active);
  const merchantScoped = sourceRecords.filter((partner) => Boolean(getPartnerScopeKey(partner))).length;
  return {
    total: currentRecords.length,
    all: sourceRecords.length,
    active,
    inactive,
    archived,
    global: Math.max(0, sourceRecords.length - merchantScoped),
    merchantScoped,
  };
}

function buildPartnerProductUsageMap(products, partnerType) {
  const config = getPartnerResourceConfig(partnerType);
  const usageByPartnerId = new Map();
  for (const product of Array.isArray(products) ? products : []) {
    const productId = String(product?.id ?? product?.productId ?? "").trim();
    if (!productId) continue;
    for (const partnerId of normalizePartnerIdList(product?.[config.referenceField])) {
      const key = partnerId.toLowerCase();
      const currentUsage = usageByPartnerId.get(key) || {
        connectedProductCount: 0,
        activeProductCount: 0,
        productIds: [],
      };
      currentUsage.connectedProductCount += 1;
      if (normalizeProductActiveState(product?.isActive, true)) {
        currentUsage.activeProductCount += 1;
      }
      if (currentUsage.productIds.length < 25) {
        currentUsage.productIds.push(productId);
      }
      usageByPartnerId.set(key, currentUsage);
    }
  }
  return usageByPartnerId;
}

function getPartnerUsage(usageByPartnerId, partnerId) {
  return usageByPartnerId?.get(String(partnerId ?? "").trim().toLowerCase()) || {
    connectedProductCount: 0,
    activeProductCount: 0,
    productIds: [],
  };
}

async function buildPartnerCollectionPayload({
  partnerType,
  records,
  requestUrl,
  requestAdminId,
  requestIsSuperAdmin,
  productOptions,
}) {
  const sourceRecords = Array.isArray(records) ? records : [];
  const scopedRecords = requestIsSuperAdmin
    ? sourceRecords
    : productOptions
      ? sourceRecords.filter((partner) => isPartnerAvailableToAdmin(partner, requestAdminId))
      : filterRecordsByAdminId(sourceRecords, requestAdminId);

  if (productOptions) {
    const partners = getActiveProductPartnerOptionRecords(scopedRecords)
      .filter((partner) => !isPartnerArchived(partner))
      .map((partner) => serializePartnerRecord(partner));
    return {
      partners,
      summary: getPartnerCollectionSummary(scopedRecords),
      pagination: {
        page: partners.length ? 1 : 0,
        pageSize: partners.length,
        total: partners.length,
        totalPages: partners.length ? 1 : 0,
        hasPrevious: false,
        hasNext: false,
      },
    };
  }

  const searchParams = requestUrl.searchParams;
  const searchTerm = String(searchParams.get("search") ?? searchParams.get("q") ?? "")
    .trim()
    .toLowerCase();
  const requestedStatus = String(searchParams.get("status") ?? "all").trim().toLowerCase();
  const status = ["all", "active", "inactive", "archived"].includes(requestedStatus)
    ? requestedStatus
    : "all";
  const requestedScope = String(
    searchParams.get("partnerScope") ?? searchParams.get("managementScope") ?? "all",
  ).trim().toLowerCase();
  const scope = ["all", "global", "merchant"].includes(requestedScope)
    ? requestedScope
    : "all";
  const includeArchived = status === "archived"
    || parsePartnerQueryBoolean(searchParams.get("includeArchived"), false);
  const includeUsage = parsePartnerQueryBoolean(searchParams.get("includeUsage"), false);
  const requestedSort = String(searchParams.get("sort") ?? "updated-desc").trim().toLowerCase();
  const sort = [
    "updated-desc",
    "updated-asc",
    "created-desc",
    "created-asc",
    "name-asc",
    "name-desc",
    "status-asc",
  ].includes(requestedSort) ? requestedSort : "updated-desc";

  let filteredRecords = scopedRecords.filter((partner) => includeArchived || !isPartnerArchived(partner));
  if (status === "archived") {
    filteredRecords = filteredRecords.filter(isPartnerArchived);
  } else if (status === "active") {
    filteredRecords = filteredRecords.filter(
      (partner) => !isPartnerArchived(partner) && normalizePartnerEnabledState(partner),
    );
  } else if (status === "inactive") {
    filteredRecords = filteredRecords.filter(
      (partner) => !isPartnerArchived(partner) && !normalizePartnerEnabledState(partner),
    );
  }
  if (scope === "global") {
    filteredRecords = filteredRecords.filter((partner) => !getPartnerScopeKey(partner));
  } else if (scope === "merchant") {
    filteredRecords = filteredRecords.filter((partner) => Boolean(getPartnerScopeKey(partner)));
  }
  if (searchTerm) {
    filteredRecords = filteredRecords.filter((partner) =>
      getPartnerSearchText(partner).includes(searchTerm)
    );
  }

  filteredRecords.sort((left, right) => {
    if (sort === "name-asc" || sort === "name-desc") {
      const direction = sort === "name-desc" ? -1 : 1;
      return direction * String(left?.branch ?? left?.name ?? "").localeCompare(
        String(right?.branch ?? right?.name ?? ""),
        undefined,
        { sensitivity: "base" },
      );
    }
    if (sort === "status-asc") {
      const leftStatus = isPartnerArchived(left)
        ? "archived"
        : normalizePartnerEnabledState(left) ? "active" : "inactive";
      const rightStatus = isPartnerArchived(right)
        ? "archived"
        : normalizePartnerEnabledState(right) ? "active" : "inactive";
      return leftStatus.localeCompare(rightStatus)
        || String(left?.branch ?? "").localeCompare(String(right?.branch ?? ""));
    }
    const field = sort.startsWith("created") ? "createdAt" : "updatedAt";
    const direction = sort.endsWith("-asc") ? 1 : -1;
    return direction * (getPartnerDateValue(left, field) - getPartnerDateValue(right, field));
  });

  const paginationRequested = searchParams.has("page") || searchParams.has("pageSize");
  const requestedPage = Math.trunc(Number(searchParams.get("page") ?? 1));
  const requestedPageSize = Math.trunc(Number(searchParams.get("pageSize") ?? 25));
  const pageSize = paginationRequested
    ? Math.min(MAX_PARTNER_PAGE_SIZE, Math.max(1, requestedPageSize || 25))
    : Math.max(1, filteredRecords.length);
  const total = filteredRecords.length;
  const totalPages = total ? Math.ceil(total / pageSize) : 0;
  const page = totalPages ? Math.min(Math.max(1, requestedPage || 1), totalPages) : 0;
  const pageStart = page ? (page - 1) * pageSize : 0;
  const pageRecords = paginationRequested
    ? filteredRecords.slice(pageStart, pageStart + pageSize)
    : filteredRecords;

  let usageByPartnerId = null;
  if (includeUsage) {
    const storedProducts = await readProducts();
    const products = requestIsSuperAdmin
      ? storedProducts
      : filterRecordsByAdminId(storedProducts, requestAdminId);
    usageByPartnerId = buildPartnerProductUsageMap(products, partnerType);
  }

  return {
    partners: pageRecords.map((partner) => serializePartnerRecord(
      partner,
      usageByPartnerId ? getPartnerUsage(usageByPartnerId, partner?.id) : null,
    )),
    summary: getPartnerCollectionSummary(scopedRecords),
    pagination: {
      page,
      pageSize: total ? (paginationRequested ? pageSize : total) : 0,
      total,
      totalPages,
      hasPrevious: page > 1,
      hasNext: page > 0 && page < totalPages,
    },
    query: {
      search: searchTerm,
      status,
      scope,
      sort,
      includeArchived,
      includeUsage,
    },
  };
}

function getPartnerAuditActor(payload, requestAdminId, requestIsSuperAdmin) {
  const suppliedActor = payload?.__activityActor;
  if (suppliedActor && typeof suppliedActor === "object") {
    return {
      role: String(suppliedActor.role ?? (requestIsSuperAdmin ? "super-admin" : "admin")).trim(),
      accountId: String(
        suppliedActor.accountId ?? suppliedActor.id ?? (requestIsSuperAdmin ? "super-admin" : requestAdminId),
      ).trim(),
      displayName: String(
        suppliedActor.displayName ?? suppliedActor.name ?? (requestIsSuperAdmin ? SUPER_ADMIN_USERNAME : requestAdminId),
      ).trim(),
    };
  }
  return {
    role: requestIsSuperAdmin ? "super-admin" : "admin",
    accountId: requestIsSuperAdmin ? "super-admin" : requestAdminId,
    displayName: requestIsSuperAdmin ? SUPER_ADMIN_USERNAME : requestAdminId,
  };
}

function createPartnerAuditSnapshot(partner) {
  if (!partner || typeof partner !== "object") return null;
  return {
    id: String(partner.id ?? "").trim(),
    branch: String(partner.branch ?? partner.name ?? "").trim(),
    description: String(partner.description ?? "").trim(),
    imageUrl: String(partner.imageUrl ?? "").trim(),
    adminId: getPartnerScopeKey(partner),
    status: isPartnerArchived(partner)
      ? "archived"
      : normalizePartnerEnabledState(partner) ? "active" : "inactive",
    version: getPartnerVersion(partner),
    archivedAt: String(partner.archivedAt ?? "").trim(),
  };
}

function getPartnerChangedFields(before, after) {
  const previous = createPartnerAuditSnapshot(before) || {};
  const next = createPartnerAuditSnapshot(after) || {};
  return [
    "branch",
    "description",
    "imageUrl",
    "adminId",
    "status",
    "archivedAt",
  ].filter((field) => JSON.stringify(previous[field] ?? null) !== JSON.stringify(next[field] ?? null));
}

async function logPartnerAuditSafely({
  partnerType,
  action,
  before = null,
  after = null,
  partnerIds = [],
  payload = null,
  request = null,
  requestAdminId = "",
  requestIsSuperAdmin = false,
  metadata = {},
}) {
  try {
    const normalizedPartnerIds = normalizePartnerIdList([
      ...partnerIds,
      before?.id,
      after?.id,
    ]);
    const actor = getPartnerAuditActor(payload, requestAdminId, requestIsSuperAdmin);
    const now = new Date().toISOString();
    const entry = {
      id: `partner-audit-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`,
      partnerType: partnerType === "delivery" ? "delivery" : "payment",
      partnerId: normalizedPartnerIds[0] || "",
      partnerIds: normalizedPartnerIds,
      action: String(action ?? "updated").trim().toLowerCase() || "updated",
      adminId: getPartnerScopeKey(after || before) || normalizeAdminTenantId(requestAdminId, ""),
      actor,
      before: createPartnerAuditSnapshot(before),
      after: createPartnerAuditSnapshot(after),
      changedFields: getPartnerChangedFields(before, after),
      metadata: metadata && typeof metadata === "object" ? metadata : {},
      requestId: String(request?.headers?.["x-request-id"] ?? "").trim(),
      ipAddress: getRequestIpAddress(request),
      createdAt: now,
    };
    await enqueueSerializedMutation("partner:audit", async () => {
      const entries = await readPartnerAuditLog();
      entries.unshift(entry);
      await writePartnerAuditLog(entries.slice(0, MAX_PARTNER_AUDIT_ENTRIES));
    });
    return entry;
  } catch (error) {
    console.error("Unable to record partner audit event:", error);
    return null;
  }
}

function getPartnerMutationActorId(payload, requestAdminId, requestIsSuperAdmin) {
  const actor = getPartnerAuditActor(payload, requestAdminId, requestIsSuperAdmin);
  return actor.displayName || actor.accountId || (requestIsSuperAdmin ? SUPER_ADMIN_USERNAME : requestAdminId);
}

async function requirePartnerResourcePermission({
  request,
  response,
  requestUrl,
  config,
  requestAdminId,
  requestIsSuperAdmin,
  productOptions = false,
}) {
  if (requestIsSuperAdmin || productOptions) {
    return true;
  }
  if (!hasRequestAdminScope(request, requestUrl)) {
    sendJson(response, 403, {
      message: "Signed store scope is required to manage partners.",
      code: "PARTNER_ADMIN_SCOPE_REQUIRED",
    });
    return false;
  }
  if (!config.permission) {
    return true;
  }
  return requireAdminRestrictionAllowed(
    request,
    response,
    requestUrl,
    config.permission,
    requestAdminId,
  );
}

async function handlePartnerCollectionApi(request, response, partnerType) {
  const config = getPartnerResourceConfig(partnerType);
  const requestUrl = new URL(request.url, `http://127.0.0.1:${PORT}`);
  const requestAdminId = getRequestAdminId(request, requestUrl);
  const requestIsSuperAdmin = isSuperAdminAuthorized(request);
  const requestIsProductOptions = isProductPartnerOptionsRequest(requestUrl);

  if (request.method === "GET") {
    try {
      if (!(await requirePartnerResourcePermission({
        request,
        response,
        requestUrl,
        config,
        requestAdminId,
        requestIsSuperAdmin,
        productOptions: requestIsProductOptions,
      }))) return;

      const storedPartners = await config.read();
      const responsePayload = await buildPartnerCollectionPayload({
        partnerType: config.type,
        records: storedPartners,
        requestUrl,
        requestAdminId,
        requestIsSuperAdmin,
        productOptions: requestIsProductOptions,
      });
      sendJson(response, 200, responsePayload);
    } catch (error) {
      sendPartnerApiError(response, error, `Unable to load ${config.pluralLabel}.`);
    }
    return;
  }

  if (request.method === "POST") {
    try {
      if (
        partnerType === "payment"
        && !(await requirePlatformSettingEnabled(
          response,
          "sellerPayoutRequests",
          "Payout and payment partner changes are currently disabled by Super Admin.",
        ))
      ) {
        return;
      }

      if (!(await requirePartnerResourcePermission({
        request,
        response,
        requestUrl,
        config,
        requestAdminId,
        requestIsSuperAdmin,
      }))) return;

      const payload = await parseRequestBody(request);
      const actorId = getPartnerMutationActorId(payload, requestAdminId, requestIsSuperAdmin);
      const partner = await runPartnerMutation(config.type, async () => {
        const partners = await config.read();
        let nextPartner = config.normalize(payload);
        if (!requestIsSuperAdmin) {
          nextPartner = applyAdminId(nextPartner, requestAdminId);
        }
        if (partners.some((record) =>
          String(record?.id ?? "").trim().toLowerCase()
            === String(nextPartner.id ?? "").trim().toLowerCase()
        )) {
          throw createPartnerApiError(
            409,
            `${config.label} ID already exists.`,
            "PARTNER_ID_CONFLICT",
          );
        }
        if (config.type === "delivery" && isSwitchRiderPartnerName(nextPartner.branch ?? nextPartner.name)) {
          throw createPartnerApiError(409, SWITCH_RIDER_RESERVED_PARTNER_MESSAGE, "PARTNER_NAME_RESERVED");
        }
        if (hasDuplicatePartnerInScope(partners, nextPartner)) {
          throw createPartnerApiError(
            409,
            `A ${config.label.toLowerCase()} with this name already exists in this scope.`,
            "PARTNER_NAME_CONFLICT",
          );
        }
        nextPartner = {
          ...nextPartner,
          createdBy: actorId,
          updatedBy: actorId,
        };
        partners.unshift(nextPartner);
        await config.write(partners);
        return nextPartner;
      });
      await logPartnerAuditSafely({
        partnerType: config.type,
        action: "created",
        after: partner,
        payload,
        request,
        requestAdminId,
        requestIsSuperAdmin,
      });
      sendJson(response, 201, {
        partner: serializePartnerRecord(partner),
        message: `${config.label} saved.`,
      });
    } catch (error) {
      sendPartnerApiError(response, error, `Unable to save ${config.label.toLowerCase()}.`);
    }
    return;
  }

  sendJson(response, 405, { message: "Method not allowed." });
}

async function handleDeliveryPartnersApi(request, response) {
  await handlePartnerCollectionApi(request, response, "delivery");
}

function normalizeEmployeeLoginId(value) {
  return String(value ?? "").trim().toUpperCase();
}

function normalizeEmployeeLoginIdNumber(value) {
  return String(value ?? "").replace(/\D/g, "").slice(0, 6);
}

function parseEmployeeLoginId(value) {
  const normalized = normalizeEmployeeLoginId(value).replace(/\s+/g, "");
  const dashedMatch = normalized.match(/^([A-Z0-9]{2,8})-(\d{1,6})$/);
  if (dashedMatch) {
    return {
      acronym: dashedMatch[1],
      number: dashedMatch[2].padStart(6, "0"),
      hasAcronym: true,
    };
  }

  const compactMatch = normalized.match(/^([A-Z0-9]*?[A-Z][A-Z0-9]*?)(\d{1,6})$/);
  if (compactMatch) {
    return {
      acronym: compactMatch[1],
      number: compactMatch[2].padStart(6, "0"),
      hasAcronym: true,
    };
  }

  const number = normalizeEmployeeLoginIdNumber(normalized);
  return {
    acronym: "",
    number: number ? number.padStart(6, "0") : "",
    hasAcronym: false,
  };
}

function isEmployeeLoginIdentifierMatch(inputValue, accountValue) {
  const inputId = parseEmployeeLoginId(inputValue);
  const accountId = parseEmployeeLoginId(accountValue);
  if (!inputId.number || !accountId.number) {
    return false;
  }

  if (inputId.hasAcronym) {
    return inputId.acronym === accountId.acronym && inputId.number === accountId.number;
  }

  return inputId.number === accountId.number;
}

function getEmployeeLoginAccountMatches(accounts, employeeId) {
  const normalizedEmployeeId = normalizeEmployeeLoginId(employeeId);
  const employeeAccounts = accounts.filter(
    (candidate) => String(candidate.role ?? "").trim().toLowerCase() === "employee",
  );

  const exactMatches = employeeAccounts.filter((candidate) =>
    normalizeEmployeeLoginId(candidate.employeeId) === normalizedEmployeeId
  );
  const exactMatchSet = new Set(exactMatches);
  const flexibleMatches = employeeAccounts.filter((candidate) =>
    !exactMatchSet.has(candidate) &&
    isEmployeeLoginIdentifierMatch(normalizedEmployeeId, candidate.employeeId)
  );

  return [...exactMatches, ...flexibleMatches];
}

function findEmployeeLoginAccount(accounts, employeeId) {
  return getEmployeeLoginAccountMatches(accounts, employeeId)[0] || null;
}

async function findEmployeeLoginAccountWithPassword(accounts, employeeId, password) {
  const submittedPassword = String(password ?? "").trim();
  for (const candidate of getEmployeeLoginAccountMatches(accounts, employeeId)) {
    if (await verifyPassword(submittedPassword, candidate.password)) {
      return candidate;
    }
  }
  return null;
}

function setAdminAccountPresence(account, isOnline, options = {}) {
  if (!account || typeof account !== "object") {
    return account;
  }

  const now = new Date().toISOString();
  const presenceEvent = String(options.event ?? "").trim().toLowerCase()
    || (isOnline === true ? "heartbeat" : "logout");
  account.isOnline = isOnline === true;
  account.online = account.isOnline;
  account.loggedIn = account.isOnline;
  account.isLoggedIn = account.isOnline;
  account.sessionActive = account.isOnline;
  account.onlineStatus = isOnline === true ? "online" : "offline";
  account.presenceStatus = account.onlineStatus;
  account.presenceUpdatedAt = now;

  if (isOnline === true) {
    account.lastOnlineAt = now;
    if (presenceEvent === "login" || !account.lastLoginAt) {
      account.lastLoginAt = now;
    }
  } else if (presenceEvent === "logout") {
    account.lastLogoutAt = now;
  }

  return account;
}

function getAdminPresenceMatchValues(source) {
  return [
    source?.adminId,
    source?.id,
    source?.accountCode,
    source?.email,
  ]
    .map((value) => String(value ?? "").trim().toLowerCase())
    .filter(Boolean);
}

function findAdminPresenceAccount(accounts, source) {
  const matchValues = new Set(getAdminPresenceMatchValues(source));
  if (!matchValues.size) {
    return null;
  }

  return accounts.find((candidate) => {
    if (!isAdminAccount(candidate)) {
      return false;
    }

    return getAdminPresenceMatchValues({
      ...candidate,
      adminId: getRecordAdminId(candidate, candidate?.adminId || candidate?.id),
    }).some((value) => matchValues.has(value));
  }) || null;
}

async function handleAdminLoginApi(request, response) {
  if (request.method !== "POST") {
    sendJson(response, 405, { message: "Method not allowed." });
    return;
  }

  try {
    if (
      !(await requirePlatformSettingEnabled(
        response,
        "sellerLoginAccess",
        "Seller login is currently disabled by Super Admin.",
      ))
    ) {
      return;
    }

    const payload = await parseRequestBody(request);
    const email = String(payload.email ?? "").trim().toLowerCase();
    const password = String(payload.password ?? "").trim();

    if (!email || !password) {
      sendJson(response, 400, {
        message: "Please enter both the admin email and password.",
      });
      return;
    }

    const loginAttempt = await beginLoginAttempt(request, response, email);
    if (!loginAttempt) {
      return;
    }

    if (await isSellerPostgresReady()) {
      await processDueSellerAccountDeletions();
      const pgLogin = await loginSeller({ email, password });
      if (pgLogin.ok) {
        const account = pgLogin.account;
        const restrictionMessage = getAdminAccountRestrictionMessage(account);
        if (restrictionMessage) {
          const accountStatus = String(account?.status ?? account?.accountStatus ?? account?.accountState ?? "")
            .trim()
            .toLowerCase();
          const isBannedAccount = accountStatus === "banned" ||
            account?.isBanned === true ||
            account?.banned === true;
          const isRestrictedAccount = accountStatus === "restricted" ||
            account?.isRestricted === true ||
            account?.restricted === true;
          sendJson(response, 403, {
            message: restrictionMessage,
            accountStatus: isBannedAccount
              ? "banned"
              : isRestrictedAccount
                ? "restricted"
                : accountStatus,
            isBanned: isBannedAccount,
            isRestricted: isRestrictedAccount,
            banReason: String(account?.banReason ?? account?.lastBanReason ?? "")
              .replace(/\s+/g, " ")
              .trim(),
            banDescription: String(account?.banDescription ?? account?.banDetails ?? "")
              .replace(/\s+/g, " ")
              .trim(),
            restrictionReason: String(account?.restrictionReason ?? account?.restrictReason ?? "")
              .replace(/\s+/g, " ")
              .trim(),
            restrictionDescription: getAdminRestrictionDescription(account),
            authStore: "postgres",
          });
          recordLoginSuccess(loginAttempt);
          return;
        }

        const platformSettings = await getPlatformSettings();
        if (
          platformSettings.requireSellerVerification
          && !isSellerAccountVerifiedForPlatform(account)
        ) {
          recordLoginSuccess(loginAttempt);
          sendJson(response, 403, {
            message: "Seller verification is required before login.",
            code: "SELLER_VERIFICATION_REQUIRED",
            setting: "requireSellerVerification",
            authStore: "postgres",
          });
          return;
        }

        const sessionFields = issueAppSessionForAccount(
          request,
          response,
          account,
          "seller",
        );
        recordLoginSuccess(loginAttempt);
        sendJson(response, 200, {
          admin: serializeAdminAccount(account),
          dashboardPath: "/admin_dashboard.html",
          redirectPath: "/main.html",
          message: "Seller login verified.",
          authStore: "postgres",
          ...sessionFields,
        });
        return;
      }

      recordLoginFailure(loginAttempt);
      sendJson(response, 401, {
        message: "Admin email or password is incorrect.",
      });
      return;
    }

    await processDueSellerAccountDeletions();
    const accounts = await readAccounts();
    const account = accounts.find((candidate) =>
      isAdminAccount(candidate) &&
      String(candidate.email ?? "").trim().toLowerCase() === email
    );

    if (!account || !(await verifyPassword(password, account.password))) {
      recordLoginFailure(loginAttempt);
      sendJson(response, 401, {
        message: "Admin email or password is incorrect.",
      });
      return;
    }

    const restrictionMessage = getAdminAccountRestrictionMessage(account);
    if (restrictionMessage) {
      const accountStatus = String(account?.status ?? account?.accountStatus ?? account?.accountState ?? "")
        .trim()
        .toLowerCase();
      const isBannedAccount = accountStatus === "banned" ||
        account?.isBanned === true ||
        account?.banned === true;
      const isRestrictedAccount = accountStatus === "restricted" ||
        account?.isRestricted === true ||
        account?.restricted === true;
      sendJson(response, 403, {
        message: restrictionMessage,
        accountStatus: isBannedAccount
          ? "banned"
          : isRestrictedAccount
            ? "restricted"
            : accountStatus,
        isBanned: isBannedAccount,
        isRestricted: isRestrictedAccount,
        banReason: String(account?.banReason ?? account?.lastBanReason ?? "")
          .replace(/\s+/g, " ")
          .trim(),
        banDescription: String(account?.banDescription ?? account?.banDetails ?? "")
          .replace(/\s+/g, " ")
          .trim(),
        restrictionReason: String(account?.restrictionReason ?? account?.restrictReason ?? "")
          .replace(/\s+/g, " ")
          .trim(),
        restrictionDescription: getAdminRestrictionDescription(account),
      });
      recordLoginSuccess(loginAttempt);
      return;
    }

    const filePlatformSettings = await getPlatformSettings();
    if (
      filePlatformSettings.requireSellerVerification
      && !isSellerAccountVerifiedForPlatform(account)
    ) {
      recordLoginSuccess(loginAttempt);
      sendJson(response, 403, {
        message: "Seller verification is required before login.",
        code: "SELLER_VERIFICATION_REQUIRED",
        setting: "requireSellerVerification",
        authStore: "json",
      });
      return;
    }

    setAdminAccountPresence(account, true, { event: "login" });
    await writeAccounts(accounts);

    const sessionFields = issueAppSessionForAccount(
      request,
      response,
      account,
      "seller",
    );
    recordLoginSuccess(loginAttempt);
    sendJson(response, 200, {
      admin: serializeAdminAccount(account),
      dashboardPath: "/admin_dashboard.html",
      redirectPath: "/main.html",
      message: "Seller login verified.",
      authStore: "json",
      ...sessionFields,
    });
  } catch (error) {
    sendJson(response, 400, {
      message:
        error instanceof Error
          ? error.message
          : "Unable to verify admin login.",
    });
  }
}

async function handleAdminLookupApi(request, response) {
  if (request.method !== "GET") {
    sendJson(response, 405, { message: "Method not allowed." });
    return;
  }

  try {
    const requestUrl = new URL(request.url, `http://127.0.0.1:${PORT}`);
    const email = String(requestUrl.searchParams.get("email") ?? "").trim().toLowerCase();

    if (!email) {
      sendJson(response, 400, { message: "Seller email is required." });
      return;
    }

    let account = null;
    if (await isSellerPostgresReady()) {
      account = await findSellerByEmail(email);
    }
    if (!account) {
      const accounts = await readAccounts();
      account = accounts.find((candidate) =>
        isAdminAccount(candidate) &&
        String(candidate.email ?? "").trim().toLowerCase() === email
      ) || null;
    }

    if (!account) {
      sendJson(response, 404, { message: "Registered seller account not found." });
      return;
    }

    const restrictionMessage = getAdminAccountRestrictionMessage(account);
    if (restrictionMessage) {
      sendJson(response, 403, {
        message: restrictionMessage,
        accountStatus: String(account?.status ?? account?.accountStatus ?? account?.accountState ?? "")
          .trim()
          .toLowerCase(),
      });
      return;
    }

    const serializedAccount = serializeAdminAccount(stripSellerInternalFields(account) || account);
    const companyPictureUrl = [
      serializedAccount.companyPictureUrl,
      serializedAccount.companyProfileImageUrl,
      serializedAccount.businessLogoUrl,
      serializedAccount.profileImageUrl,
      serializedAccount.avatarUrl,
      serializedAccount.photoUrl,
      serializedAccount.logoUrl,
    ]
      .map((value) => String(value ?? "").trim())
      .find(Boolean) || "";
    sendJson(response, 200, {
      account: {
        email: String(serializedAccount.email ?? email).trim().toLowerCase(),
        role: "admin",
        adminId: serializedAccount.adminId,
        displayName: serializedAccount.displayName,
        companyName: serializedAccount.companyName,
        storeName: serializedAccount.storeName,
        businessName: serializedAccount.businessName,
        businessLogoSkipped: serializedAccount.businessLogoSkipped === true,
        companyPictureUrl:
          serializedAccount.businessLogoSkipped === true ? "" : companyPictureUrl,
        companyProfileImageUrl: String(serializedAccount.companyProfileImageUrl ?? "").trim(),
        businessLogoUrl: String(serializedAccount.businessLogoUrl ?? "").trim(),
        profileImageUrl:
          serializedAccount.businessLogoSkipped === true
            ? ""
            : String(serializedAccount.profileImageUrl ?? companyPictureUrl).trim(),
        logoUrl: String(serializedAccount.logoUrl ?? "").trim(),
      },
      message: "Registered seller account found.",
    });
  } catch (error) {
    sendJson(response, 500, {
      message:
        error instanceof Error
          ? error.message
          : "Unable to check seller account.",
    });
  }
}

async function handleAdminPresenceApi(request, response) {
  if (request.method !== "POST") {
    sendJson(response, 405, { message: "Method not allowed." });
    return;
  }

  try {
    const payload = await parseRequestBody(request);
    assertSessionPayloadIdentity(request, payload, { admin: true });
    const sessionIdentity = {
      adminId: request.authSession.adminId,
      id: request.authSession.accountId,
      accountCode: request.authSession.accountId,
      email: request.authSession.email,
    };

    if (await isSellerPostgresReady()) {
      const matchValues = [
        sessionIdentity.adminId,
        sessionIdentity.id,
        sessionIdentity.accountCode,
        sessionIdentity.email,
      ]
        .map((value) => String(value ?? "").trim())
        .filter(Boolean);

      let pgAccount = null;
      for (const value of matchValues) {
        pgAccount = await findSellerByAdminId(value);
        if (!pgAccount && value.includes("@")) {
          pgAccount = await findSellerByEmail(value);
        }
        if (pgAccount) {
          break;
        }
      }

      if (pgAccount) {
        const updated = await updateSellerPresence(
          pgAccount.id,
          payload?.isOnline === true,
          { event: payload?.presenceEvent },
        );
        sendJson(response, 200, {
          admin: serializeAdminAccount(stripSellerInternalFields(updated) || updated),
          message: updated?.isOnline ? "Admin is online." : "Admin is offline.",
          authStore: "postgres",
        });
        return;
      }
    }

    const accounts = await readAccounts();
    const account = findAdminPresenceAccount(accounts, sessionIdentity);
    if (!account) {
      sendJson(response, 404, { message: "Admin account not found." });
      return;
    }

    setAdminAccountPresence(account, payload?.isOnline === true, {
      event: payload?.presenceEvent,
    });
    await writeAccounts(accounts);

    sendJson(response, 200, {
      admin: serializeAdminAccount(account),
      message: account.isOnline ? "Admin is online." : "Admin is offline.",
      authStore: "json",
    });
  } catch (error) {
    sendJson(response, 400, {
      message:
        error instanceof Error
          ? error.message
          : "Unable to update admin presence.",
    });
  }
}

async function handleAuthVerificationSendApi(request, response) {
  if (request.method !== "POST") {
    sendJson(response, 405, { message: "Method not allowed." });
    return;
  }

  try {
    if (!(await isCustomerPostgresReady())) {
      sendJson(response, 503, { message: "Verification service is unavailable." });
      return;
    }

    const payload = await parseRequestBody(request);
    const purpose = String(payload.purpose ?? "registration").trim().toLowerCase() || "registration";
    const channel = String(payload.channel ?? "email").trim().toLowerCase() === "mobile"
      ? "mobile"
      : "email";
    const target = channel === "mobile"
      ? String(payload.mobileNumber ?? payload.target ?? "").trim()
      : String(payload.email ?? payload.target ?? "").trim();

    // OTP email/SMS must still work while Test Mode is on (sandbox testing).
    // Account *creation* stays IP-locked separately.

    if (purpose === "password_reset") {
      const registered = await isSwitchRegisteredAccountForPasswordReset({
        channel,
        target,
      });
      if (!registered) {
        sendJson(response, 404, {
          message:
            channel === "mobile"
              ? "This mobile number is not registered on Switch."
              : "This email is not registered on Switch.",
        });
        return;
      }
    }

    const result = await sendVerificationCode({ purpose, channel, target });
    sendJson(response, 200, {
      message: "Verification code sent.",
      channel: result.channel,
      target: result.target,
      expiresAt: result.expiresAt,
      createdAt: result.createdAt,
      resendAvailableAt: result.resendAvailableAt,
      resendCooldownSeconds: result.resendCooldownSeconds,
      delivery: result.delivery,
    });
  } catch (error) {
    sendJson(response, 400, {
      message: error instanceof Error ? error.message : "Unable to send verification code.",
    });
  }
}

async function handleUnifiedAuthSessionApi(request, response) {
  if (request.method !== "GET") {
    sendJson(response, 405, { message: "Method not allowed." });
    return;
  }

  try {
    const requestUrl = new URL(request.url, `http://127.0.0.1:${PORT}`);
    const entry = await requireUnifiedSessionEntry(request, requestUrl);
    sendJson(response, 200, {
      session: serializeUnifiedSessionEntry(entry),
      message: "Unified session loaded.",
    });
  } catch (error) {
    sendJson(response, error?.statusCode || 500, {
      message: error instanceof Error ? error.message : "Unable to load unified session.",
      ...(error?.code ? { code: error.code } : {}),
      ...(error?.accountStatus ? { accountStatus: error.accountStatus } : {}),
    });
  }
}

