async function handleAuthGoogleLoginApi(request, response) {
  if (request.method !== "POST") {
    sendJson(response, 405, { message: "Method not allowed." });
    return;
  }

  try {
    if (
      !(await requirePlatformSettingEnabled(
        response,
        "buyerLoginAccess",
        "Buyer login is currently disabled by Super Admin.",
      ))
    ) {
      return;
    }

    if (!(await isCustomerPostgresReady())) {
      sendJson(response, 503, { message: "Google sign-in is unavailable." });
      return;
    }

    const payload = await parseRequestBody(request);
    const createIfMissing =
      payload.createIfMissing === undefined
        ? true
        : Boolean(payload.createIfMissing);
    const platformSettings = await getPlatformSettings();
    const registrationAllowed = !isPlatformSettingBlocking(
      platformSettings,
      "buyerRegistration",
    );

    // Test Mode: only the Super Admin IP may create accounts. Existing logins stay open.
    let allowCreate = Boolean(createIfMissing && registrationAllowed);
    let testModeCreateBlock = null;
    if (allowCreate) {
      try {
        await assertTestModeAccountCreationAllowed(request);
      } catch (error) {
        if (error?.code === "TEST_MODE_REGISTRATION_LOCKED") {
          allowCreate = false;
          testModeCreateBlock = error.payload || {
            message: error.message,
            code: "TEST_MODE_REGISTRATION_LOCKED",
            maintenance: true,
          };
        } else {
          throw error;
        }
      }
    }

    const loginResult = await loginCustomerWithGoogle({
      idToken: payload.idToken,
      accessToken: payload.accessToken,
      createIfMissing: allowCreate,
      verificationToken: allowCreate ? payload.verificationToken : undefined,
      preferredLanguage: payload.preferredLanguage,
    });

    if (
      !loginResult.ok
      && (loginResult.code === "not_found" || loginResult.code === "verification_required")
      && testModeCreateBlock
    ) {
      sendJson(response, 403, testModeCreateBlock);
      return;
    }

    if (
      !loginResult.ok
      && loginResult.code === "not_found"
      && createIfMissing
      && !registrationAllowed
    ) {
      sendJson(
        response,
        403,
        buildPlatformBlockedPayload(
          "buyerRegistration",
          "Buyer registration is currently disabled by Super Admin.",
        ),
      );
      return;
    }

    if (!loginResult.ok) {
      const statusCode =
        loginResult.code === "not_found"
          ? 404
          : loginResult.code === "verification_required"
            ? 409
            : 400;
      sendJson(response, statusCode, {
        message: loginResult.message,
        code: loginResult.code,
        profile: loginResult.profile
          ? {
              email: loginResult.profile.email,
              firstName: loginResult.profile.firstName,
              lastName: loginResult.profile.lastName,
            }
          : undefined,
      });
      return;
    }

    const restrictionMessage = getBuyerRestrictionMessage(loginResult.account);
    if (restrictionMessage) {
      sendJson(response, 403, {
        message: restrictionMessage,
        accountStatus: getBuyerAccountStatus(loginResult.account),
        authStore: "postgres",
      });
      return;
    }

    const sessionFields = issueAppSessionForAccount(
      request,
      response,
      loginResult.account,
      "buyer",
    );
    sendJson(response, 200, {
      account: serializeAccountForList(stripInternalFields(loginResult.account)),
      message: loginResult.created
        ? "Welcome! Your Switch account was created with Google."
        : "Login successful.",
      created: Boolean(loginResult.created),
      authStore: "postgres",
      ...sessionFields,
    });
  } catch (error) {
    sendJson(response, 400, {
      message: error instanceof Error ? error.message : "Unable to sign in with Google.",
    });
  }
}

