async function readProductSpecificationBusinessTypes() {
  try {
    return (await readStoreTypes())
      .map(normalizeStoreTypeRecord)
      .filter(Boolean)
      .map((storeType) => ({
        name: storeType.name,
        status: storeType.status,
        categories: getUniqueCategoryList([storeType.categories]),
      }));
  } catch (error) {
    return [];
  }
}

async function buildProductSpecificationsResponse(businessTypes = null) {
  return {
    ...getProductSpecificationConfig(),
    businessTypes: businessTypes ?? await readProductSpecificationBusinessTypes(),
  };
}

async function handleSuperAdminProductSpecificationsApi(request, response) {
  if (!requireSuperAdmin(request, response)) {
    return;
  }

  if (request.method === "GET") {
    sendJson(response, 200, await buildProductSpecificationsResponse());
    return;
  }

  if (request.method !== "PUT" && request.method !== "DELETE") {
    sendJson(response, 405, { message: "Method not allowed." });
    return;
  }

  try {
    const payload = await parseRequestBody(request);
    const isDefault = payload?.isDefault === true;
    const categoryName = normalizeCategoryName(payload?.category ?? "");
    const businessTypes = await readProductSpecificationBusinessTypes();

    if (!isDefault) {
      const categoryKey = categoryName.toLowerCase();
      const knownCategory = businessTypes.some((businessType) =>
        businessType.categories.some((name) => normalizeCategoryName(name).toLowerCase() === categoryKey))
        || getProductSpecificationConfig().categories.some((settings) => settings.key === categoryKey);
      if (!categoryKey || !knownCategory) {
        sendJson(response, 400, { message: "Choose a category that exists in Business Types." });
        return;
      }
    }

    const targetLabel = isDefault ? "the default list" : `"${categoryName}"`;
    if (request.method === "PUT") {
      const settings = await saveCategorySpecifications(categoryName, payload?.options, { isDefault });
      await logSuperAdminSystemActivity(
        {
          type: "product-specifications",
          action: "updated",
          category: "catalog",
          title: "Specifications updated",
          description:
            `Super Admin set ${settings.options.length} specification${settings.options.length === 1 ? "" : "s"} `
            + `for ${targetLabel}.`,
        },
        request,
      );
    } else {
      const removed = await resetCategorySpecifications(categoryName, { isDefault });
      if (removed) {
        await logSuperAdminSystemActivity(
          {
            type: "product-specifications",
            action: "reset",
            category: "catalog",
            title: "Specifications reset",
            description: `Super Admin reset the specifications of ${targetLabel} to the code list.`,
          },
          request,
        );
      }
    }

    sendJson(response, 200, await buildProductSpecificationsResponse(businessTypes));
  } catch (error) {
    sendJson(response, Number(error?.statusCode) || 500, {
      message: error instanceof Error ? error.message : "Unable to save specifications.",
    });
  }
}

async function handleSuperAdminStoreTypesApi(request, response, requestUrl) {
  if (!requireSuperAdmin(request, response)) {
    return;
  }

  if (request.method === "GET") {
    try {
      const [storedStoreTypes, accounts, products, orders, chatThreads] = await Promise.all([
        readStoreTypes(),
        readAccounts(),
        readProducts(),
        readOrders(),
        readChatThreads(),
      ]);
      const storeTypeDetails = getGlobalStoreTypeDetails(
        storedStoreTypes,
        accounts,
        products,
        orders,
        chatThreads,
      );
      sendJson(response, 200, {
        storeTypes: storeTypeDetails.map((storeType) => storeType.name),
        storeTypeDetails,
      });
    } catch (error) {
      sendJson(response, 500, {
        message: error instanceof Error ? error.message : "Unable to load business types.",
      });
    }
    return;
  }

  if (request.method === "POST") {
    try {
      const payload = await parseRequestBody(request);
      const storeTypeName = normalizeStoreTypeName(payload.name ?? payload.storeType);

      if (storeTypeName.length < 2) {
        throw new Error("Business type name must be at least 2 characters long.");
      }

      const storedStoreTypes = await readStoreTypes();
      const existingStoreTypes = getGlobalStoreTypeList(storedStoreTypes);
      const alreadyExists = existingStoreTypes.some(
        (storeType) => storeType.toLowerCase() === storeTypeName.toLowerCase(),
      );

      if (alreadyExists) {
        throw new Error("Business type already exists.");
      }

      const persistedStoreTypes = [
        ...storedStoreTypes,
        normalizeStoreTypeRecord({
          name: storeTypeName,
          platformId: payload.platformId ?? payload.platform ?? payload.buyerPlatform,
          categories: payload.categories,
          status: payload.status,
          commissionRate: payload.commissionRate,
          serviceFee: payload.serviceFee,
          heroImageUrl: payload.heroImageUrl ?? payload.imageUrl,
          iconImageUrl: payload.iconImageUrl ?? payload.iconUrl,
          iconName: payload.iconName ?? payload.lucideIconName,
          categoryDetails: payload.categoryDetails ?? payload.categoryStats,
        }),
      ].filter(Boolean);

      await writeStoreTypes(persistedStoreTypes);
      const [accounts, products] = await Promise.all([readAccounts(), readProducts()]);
      const storeTypeDetails = getGlobalStoreTypeDetails(persistedStoreTypes, accounts, products);
      const categoryCount = Array.isArray(payload.categories) ? payload.categories.length : 0;
      await logSuperAdminSystemActivity(
        {
          type: "store-type-catalog",
          action: "created",
          category: "catalog",
          title: "Business type added",
          description: categoryCount
            ? `Super Admin added business type "${storeTypeName}" with ${categoryCount} categor${categoryCount === 1 ? "y" : "ies"}.`
            : `Super Admin added business type "${storeTypeName}".`,
          storeTypeName,
          targetUrl: "/super_admin.html#store-types",
        },
        request,
      );
      sendJson(response, 201, {
        storeType: storeTypeName,
        storeTypeRecord: storeTypeDetails.find(
          (storeType) => storeType.name.toLowerCase() === storeTypeName.toLowerCase(),
        ),
        storeTypes: storeTypeDetails.map((storeType) => storeType.name),
        storeTypeDetails,
        message: "Business type added.",
      });
    } catch (error) {
      sendJson(response, 400, {
        message: error instanceof Error ? error.message : "Unable to add business type.",
      });
    }
    return;
  }

  if (request.method === "PUT") {
    try {
      const payload = await parseRequestBody(request);
      const previousStoreTypeName = normalizeStoreTypeName(
        payload.oldName ?? payload.currentName ?? payload.previousStoreType,
      );
      const nextStoreTypeName = normalizeStoreTypeName(payload.name ?? payload.storeType);

      if (!previousStoreTypeName) {
        throw new Error("Current business type name is required.");
      }

      if (nextStoreTypeName.length < 2) {
        throw new Error("Business type name must be at least 2 characters long.");
      }

      const [storedStoreTypes, accounts] = await Promise.all([
        readStoreTypes(),
        readAccounts(),
      ]);
      const allStoreTypes = getGlobalStoreTypeList(storedStoreTypes);
      const previousStoreTypeKey = previousStoreTypeName.toLowerCase();
      const nextStoreTypeKey = nextStoreTypeName.toLowerCase();

      const storeTypeExists = allStoreTypes.some(
        (storeType) => storeType.toLowerCase() === previousStoreTypeKey,
      );

      if (!storeTypeExists) {
        throw new Error("Business type not found.");
      }

      const alreadyExists = allStoreTypes.some((storeType) => {
        const storeTypeKey = storeType.toLowerCase();
        return storeTypeKey === nextStoreTypeKey && storeTypeKey !== previousStoreTypeKey;
      });

      if (alreadyExists) {
        throw new Error("Business type already exists.");
      }

      const previousStoreTypeRecord =
        storedStoreTypes.find(
          (storeType) => getStoreTypeRecordName(storeType).toLowerCase() === previousStoreTypeKey,
        ) || {};
      const nextStoreTypeRecord = normalizeStoreTypeRecord({
        ...(
          previousStoreTypeRecord && typeof previousStoreTypeRecord === "object"
            ? previousStoreTypeRecord
            : {}
        ),
        name: nextStoreTypeName,
        platformId:
          payload.platformId === undefined
            && payload.platform === undefined
            && payload.buyerPlatform === undefined
            ? previousStoreTypeRecord?.platformId
            : payload.platformId ?? payload.platform ?? payload.buyerPlatform,
        categories:
          payload.categories === undefined
            ? previousStoreTypeRecord?.categories
            : payload.categories,
        status:
          payload.status === undefined
            ? previousStoreTypeRecord?.status
            : payload.status,
        commissionRate:
          payload.commissionRate === undefined
            ? previousStoreTypeRecord?.commissionRate
            : payload.commissionRate,
        serviceFee:
          payload.serviceFee === undefined
            ? previousStoreTypeRecord?.serviceFee
            : payload.serviceFee,
        heroImageUrl:
          payload.heroImageUrl === undefined && payload.imageUrl === undefined
            ? previousStoreTypeRecord?.heroImageUrl
            : payload.heroImageUrl ?? payload.imageUrl,
        iconImageUrl:
          payload.iconImageUrl === undefined && payload.iconUrl === undefined
            ? previousStoreTypeRecord?.iconImageUrl
            : payload.iconImageUrl ?? payload.iconUrl,
        iconName:
          payload.iconName === undefined && payload.lucideIconName === undefined
            ? previousStoreTypeRecord?.iconName
            : payload.iconName ?? payload.lucideIconName,
        categoryDetails:
          payload.categoryDetails === undefined && payload.categoryStats === undefined
            ? previousStoreTypeRecord?.categoryDetails ?? previousStoreTypeRecord?.categoryStats
            : payload.categoryDetails ?? payload.categoryStats,
      });
      const nextStoredStoreTypes = [
        ...storedStoreTypes.filter(
          (storeType) => getStoreTypeRecordName(storeType).toLowerCase() !== previousStoreTypeKey,
        ),
        nextStoreTypeRecord,
      ].filter(Boolean);

      let updatedAdmins = 0;
      const nextAccounts = accounts.map((account) => {
        const currentStoreType = normalizeStoreTypeName(
          account?.storeType ?? account?.storeTypeName ?? account?.businessType,
        );
        if (currentStoreType.toLowerCase() !== previousStoreTypeKey) {
          return account;
        }

        updatedAdmins += 1;
        return {
          ...account,
          storeType: nextStoreTypeName,
          storeTypeName: nextStoreTypeName,
          businessType: nextStoreTypeName,
        };
      });

      await Promise.all([
        writeStoreTypes(nextStoredStoreTypes),
        writeAccounts(nextAccounts),
      ]);
      let products = await readProducts();
      const storeTypeDetails = getGlobalStoreTypeDetails(nextStoredStoreTypes, nextAccounts, products);
      const categoriesTouched =
        payload.categories !== undefined ||
        payload.categoryDetails !== undefined ||
        payload.categoryStats !== undefined;
      await logSuperAdminSystemActivity(
        {
          type: "store-type-catalog",
          action: categoriesTouched ? "categories-updated" : "updated",
          category: "catalog",
          title: categoriesTouched ? "Categories updated" : "Business type updated",
          description: categoriesTouched
            ? `Super Admin updated categories for business type "${nextStoreTypeName}".`
            : `Super Admin updated business type "${previousStoreTypeName}" → "${nextStoreTypeName}".`,
          storeTypeName: nextStoreTypeName,
          targetUrl: "/super_admin.html#store-types",
        },
        request,
      );
      sendJson(response, 200, {
        storeType: nextStoreTypeName,
        storeTypeRecord: storeTypeDetails.find(
          (storeType) => storeType.name.toLowerCase() === nextStoreTypeKey,
        ),
        previousStoreType: previousStoreTypeName,
        updatedAdmins,
        storeTypes: storeTypeDetails.map((storeType) => storeType.name),
        storeTypeDetails,
        message: "Business type updated.",
      });
    } catch (error) {
      sendJson(response, 400, {
        message: error instanceof Error ? error.message : "Unable to update business type.",
      });
    }
    return;
  }

  if (request.method === "DELETE") {
    try {
      const storeTypeName = normalizeStoreTypeName(requestUrl?.searchParams.get("name"));

      if (!storeTypeName) {
        throw new Error("Business type name is required.");
      }

      const [storedStoreTypes, accounts] = await Promise.all([
        readStoreTypes(),
        readAccounts(),
      ]);
      const allStoreTypes = getGlobalStoreTypeList(storedStoreTypes);
      const storeTypeKey = storeTypeName.toLowerCase();
      const storeTypeExists = allStoreTypes.some(
        (storeType) => storeType.toLowerCase() === storeTypeKey,
      );

      if (!storeTypeExists) {
        throw new Error("Business type not found.");
      }

      const nextStoreTypes = storedStoreTypes.filter(
        (storeType) => getStoreTypeRecordName(storeType).toLowerCase() !== storeTypeKey,
      );
      let clearedAdmins = 0;
      const nextAccounts = accounts.map((account) => {
        const currentStoreType = normalizeStoreTypeName(
          account?.storeType ?? account?.storeTypeName ?? account?.businessType,
        );
        if (currentStoreType.toLowerCase() !== storeTypeKey) {
          return account;
        }

        clearedAdmins += 1;
        return {
          ...account,
          storeType: "",
          storeTypeName: "",
          businessType: "",
        };
      });

      await Promise.all([
        writeStoreTypes(nextStoreTypes),
        writeAccounts(nextAccounts),
      ]);
      const products = await readProducts();
      const storeTypeDetails = getGlobalStoreTypeDetails(nextStoreTypes, nextAccounts, products);
      await logSuperAdminSystemActivity(
        {
          type: "store-type-catalog",
          action: "deleted",
          category: "catalog",
          title: "Business type deleted",
          description: `Super Admin deleted business type "${storeTypeName}".`,
          storeTypeName,
          targetUrl: "/super_admin.html#store-types",
        },
        request,
      );
      sendJson(response, 200, {
        storeTypes: storeTypeDetails.map((storeType) => storeType.name),
        storeTypeDetails,
        clearedAdmins,
        message: "Business type deleted.",
      });
    } catch (error) {
      sendJson(response, 400, {
        message: error instanceof Error ? error.message : "Unable to delete business type.",
      });
    }
    return;
  }

  sendJson(response, 405, { message: "Method not allowed." });
}

async function handleStoreTypesApi(request, response) {
  if (request.method === "GET") {
    try {
      const storedStoreTypes = await readStoreTypes();
      const storeTypeDetails = getGlobalStoreTypeDetails(storedStoreTypes)
        .filter((storeType) => storeType.status !== "inactive")
        .map(hideInactiveStoreTypeCategoriesFromStoreType)
        .filter(Boolean);
      sendJson(response, 200, {
        storeTypes: storeTypeDetails.map((storeType) => storeType.name),
        storeTypeDetails,
      });
    } catch (error) {
      sendJson(response, 500, {
        message: error instanceof Error ? error.message : "Unable to load business types.",
      });
    }
    return;
  }

  sendJson(response, 403, {
    message: "Business type management is available in Super Admin only.",
  });
}

async function handleEmployeeLoginApi(request, response) {
  if (request.method !== "POST") {
    sendJson(response, 405, { message: "Method not allowed." });
    return;
  }

  try {
    const payload = await parseRequestBody(request);
    const employeeId = String(payload.employeeId ?? "").trim();
    const password = String(payload.password ?? "").trim();

    if (!employeeId || !password) {
      sendJson(response, 400, {
        message: "Please enter both the employee ID and password.",
      });
      return;
    }

    const loginAttempt = await beginLoginAttempt(request, response, employeeId);
    if (!loginAttempt) {
      return;
    }

    if (await isEmployeePostgresReady()) {
      const pgLogin = await loginEmployee({ employeeId, password });
      if (pgLogin.ok) {
        const faceAttendanceData = await readFaceAttendanceData();
        const serializedAccount = serializeEmployeeAccount(
          stripEmployeeInternalFields(pgLogin.account),
          faceAttendanceData,
        );
        const dashboardPath = getEmployeeDashboardPath(serializedAccount);
        const sessionFields = issueAppSessionForAccount(
          request,
          response,
          pgLogin.account,
          "employee",
        );
        recordLoginSuccess(loginAttempt);
        sendJson(response, 200, {
          account: serializedAccount,
          adminId: serializedAccount.adminId,
          dashboardPath,
          redirectPath: "/main.html",
          message: "Employee login verified.",
          authStore: "postgres",
          ...sessionFields,
        });
        return;
      }

      recordLoginFailure(loginAttempt);
      sendJson(response, 401, {
        message: "Employee ID or password is incorrect.",
      });
      return;
    }

    const accounts = await readAccounts();
    const account = await findEmployeeLoginAccountWithPassword(accounts, employeeId, password);

    if (!account) {
      recordLoginFailure(loginAttempt);
      sendJson(response, 401, {
        message: "Employee ID or password is incorrect.",
      });
      return;
    }

    const faceAttendanceData = await readFaceAttendanceData();
    const serializedAccount = serializeEmployeeAccount(account, faceAttendanceData);
    const dashboardPath = getEmployeeDashboardPath(serializedAccount);
    const sessionFields = issueAppSessionForAccount(
      request,
      response,
      account,
      "employee",
    );
    recordLoginSuccess(loginAttempt);
    sendJson(response, 200, {
      account: serializedAccount,
      adminId: serializedAccount.adminId,
      dashboardPath,
      redirectPath: "/main.html",
      message: "Employee login verified.",
      authStore: "json",
      ...sessionFields,
    });
  } catch (error) {
    sendJson(response, 400, {
      message:
        error instanceof Error
          ? error.message
          : "Unable to verify employee login.",
    });
  }
}

async function handleEmployeeLookupApi(request, response) {
  if (request.method !== "GET") {
    sendJson(response, 405, { message: "Method not allowed." });
    return;
  }

  try {
    const requestUrl = new URL(request.url, `http://127.0.0.1:${PORT}`);
    const employeeId = String(requestUrl.searchParams.get("employeeId") ?? "").trim();

    if (!employeeId) {
      sendJson(response, 400, { message: "Employee ID is required." });
      return;
    }

    let account = null;
    if (await isEmployeePostgresReady()) {
      account = await findEmployeeLoginCandidate(employeeId);
    }
    if (!account) {
      const accounts = await readAccounts();
      account = findEmployeeLoginAccount(accounts, employeeId);
    }

    if (!account) {
      sendJson(response, 404, { message: "Invalid Employee ID" });
      return;
    }

    sendJson(response, 200, {
      account: {
        employeeId: String(account.employeeId ?? account.accountCode ?? "").trim(),
        accountCode: String(account.accountCode ?? account.employeeId ?? "").trim(),
        role: "employee",
      },
    });
  } catch (error) {
    sendJson(response, 500, {
      message:
        error instanceof Error
          ? error.message
          : "Unable to check employee ID.",
    });
  }
}

async function handleAccountsApi(request, response) {
  const requestUrl = new URL(request.url, `http://127.0.0.1:${PORT}`);
  const requestAdminId = getRequestAdminId(request, requestUrl);
  const requestIsSuperAdmin = isSuperAdminAuthorized(request);
  const requestHasAdminScope = hasRequestAdminScope(request, requestUrl);
  const requestShouldUseAdminScope = !requestIsSuperAdmin;
  const shouldApplyAdminRestriction = !requestIsSuperAdmin && requestHasAdminScope;
  const getAccountRequestId = (payload = {}) =>
    String(
      payload.id
        ?? payload.accountId
        ?? payload.employeeId
        ?? requestUrl.searchParams.get("id")
        ?? requestUrl.searchParams.get("accountId")
        ?? requestUrl.searchParams.get("employeeId")
        ?? "",
    ).trim();
  const findAccountIndexById = (accounts, accountId) => {
    const normalizedAccountId = String(accountId ?? "").trim().toLowerCase();
    if (!normalizedAccountId) {
      return -1;
    }

    return accounts.findIndex((account) =>
      [
        account.id,
        account.accountCode,
        account.employeeId,
      ].some((value) => String(value ?? "").trim().toLowerCase() === normalizedAccountId),
    );
  };

  if (request.method === "GET") {
    try {
      const [accounts, faceAttendanceData] = await Promise.all([
        readAccounts(),
        readFaceAttendanceData(),
      ]);
      const testModeOn = await isTestModeEnabled();
      const visibleAccounts = filterAccountsForSuperAdmin(
        accounts
          .filter((account) => !isAdminAccount(account))
          .filter((account) =>
            requestShouldUseAdminScope ? isRecordInAdminScope(account, requestAdminId) : true,
          ),
        { testModeOn },
      );
      const protectionAccounts = requestIsSuperAdmin
        && sellerBuyerProtectionApi
        && typeof sellerBuyerProtectionApi.attachTicketsToBuyerAccounts === "function"
        ? await sellerBuyerProtectionApi.attachTicketsToBuyerAccounts(visibleAccounts)
        : visibleAccounts;
      sendJson(response, 200, {
        accounts: protectionAccounts.map((account) =>
          serializeAccountForList(account, faceAttendanceData),
        ),
        workspace: testModeOn ? "test" : "live",
        testMode: testModeOn,
      });
    } catch (error) {
      sendJson(response, 500, {
        message: error instanceof Error ? error.message : "Unable to load accounts.",
      });
    }
    return;
  }

  if (request.method === "POST") {
    try {
      const payload = await parseRequestBody(request);
      const isAppUserRegistration =
        String(payload.source ?? "").trim().toLowerCase() === "app";

      if (
        isAppUserRegistration
        && !(await requireTestModeAccountCreationAllowed(request, response))
      ) {
        return;
      }

      if (
        isAppUserRegistration
        && !(await requirePlatformSettingEnabled(
          response,
          "buyerRegistration",
          "Buyer registration is currently disabled by Super Admin.",
        ))
      ) {
        return;
      }

      if (
        !isAppUserRegistration
        && !requireAppSession(request, response, requestUrl, {
          roles: ["seller", "employee"],
          identityKind: "admin",
        })
      ) {
        return;
      }
      if (!isAppUserRegistration) {
        assertSessionPayloadIdentity(request, payload, { admin: true });
      }

      if (
        !isAppUserRegistration &&
        shouldApplyAdminRestriction &&
        !(await requireAdminRestrictionAllowed(
          request,
          response,
          requestUrl,
          "manage_employees",
          requestAdminId,
        ))
      ) {
        return;
      }

      // Customer (Flutter app) registration → PostgreSQL when configured.
      if (isAppUserRegistration && (await isCustomerPostgresReady())) {
        const pgAccount = await createCustomerAccount({
          ...payload,
          adminId: DEFAULT_ADMIN_ID,
          googleProfile: payload.googleProfile,
          verificationToken: payload.verificationToken,
          verificationChannel: payload.verificationChannel ?? "email",
        });

        const accountActivityActor = createEmployeeRequestActivityActor(payload, pgAccount);
        await logActivitySafely(accountActivityActor && {
          title: "New user registered",
          actor: accountActivityActor,
          adminId: requestAdminId,
          targetPermission: "employee-data",
          description:
            `${pgAccount.firstName} ${pgAccount.lastName} created an account from the app.`,
          createdAt: new Date().toISOString(),
        }, request);

        sendJson(response, 201, {
          account: serializeAccountForList(stripInternalFields(pgAccount)),
          message: "User account created.",
          authStore: "postgres",
        });
        return;
      }

      // Employee (web) registration → PostgreSQL when configured.
      if (!isAppUserRegistration && (await isEmployeePostgresReady())) {
        const normalizedAccount = applyAdminId(normalizeAccountRecord({
          ...payload,
          adminId: requestAdminId,
        }), requestAdminId);

        const pgEmployee = await createEmployeeAccount(normalizedAccount);

        const accountActivityActor = createEmployeeRequestActivityActor(payload, pgEmployee);
        await logActivitySafely(accountActivityActor && {
          title: "Employee account created",
          actor: accountActivityActor,
          adminId: requestAdminId,
          targetPermission: "employee-data",
          description:
            `${pgEmployee.firstName} ${pgEmployee.lastName} was registered as an employee account.`,
          createdAt: new Date().toISOString(),
        }, request);

        sendJson(response, 201, {
          account: serializeAccountForList(stripEmployeeInternalFields(pgEmployee)),
          message: "Employee account created.",
          authStore: "postgres",
        });
        return;
      }

      const accounts = await readAccounts();
      const normalizedAccount = applyAdminId(normalizeAccountRecord({
        ...payload,
        password: await hashPassword(payload.password),
        adminId: isAppUserRegistration ? DEFAULT_ADMIN_ID : requestAdminId,
      }), isAppUserRegistration ? DEFAULT_ADMIN_ID : requestAdminId);
      const hasEmployeeId = normalizedAccount.employeeId.trim().length > 0;
      const employeeIdTaken = hasEmployeeId && accounts.some(
        (account) =>
          !isAdminAccount(account) &&
          isRecordInAdminScope(account, requestAdminId) &&
          String(account.employeeId ?? "").toLowerCase() === normalizedAccount.employeeId.toLowerCase(),
      );

      if (employeeIdTaken) {
        throw new Error("Employee ID already exists.");
      }

      const emailTaken = accounts.some(
        (account) =>
          !isAdminAccount(account) &&
          isRecordInAdminScope(account, requestAdminId) &&
          String(account.email ?? "").toLowerCase() === normalizedAccount.email,
      );

      if (emailTaken) {
        throw new Error("Email address is already registered.");
      }

      const applicantNameKey = normalizeAccountApplicantNameForComparison(normalizedAccount);
      const applicantNameTaken = Boolean(applicantNameKey) && accounts.some(
        (account) =>
          !isAdminAccount(account) &&
          isRecordInAdminScope(account, requestAdminId) &&
          normalizeAccountApplicantNameForComparison(account) === applicantNameKey,
      );

      if (applicantNameTaken) {
        throw new Error("This applicant is already existed.");
      }

      const mobileNumberTaken = accounts.some(
        (account) =>
          !isAdminAccount(account) &&
          isRecordInAdminScope(account, requestAdminId) &&
          normalizeAccountPhoneForComparison(account.mobileNumber) ===
          normalizeAccountPhoneForComparison(normalizedAccount.mobileNumber),
      );

      if (mobileNumberTaken) {
        throw new Error("Phone number is already registered.");
      }

      accounts.unshift(normalizedAccount);
      await writeAccounts(accounts);
      const accountActivityActor = createEmployeeRequestActivityActor(payload, normalizedAccount);
      await logActivitySafely(accountActivityActor && {
        title:
          normalizedAccount.source === "app"
            ? "New user registered"
            : "Employee account created",
        actor: accountActivityActor,
        adminId: requestAdminId,
        targetPermission: "employee-data",
        description:
          normalizedAccount.source === "app"
            ? `${normalizedAccount.firstName} ${normalizedAccount.lastName} created an account from the app.`
            : `${normalizedAccount.firstName} ${normalizedAccount.lastName} was registered as an employee account.`,
        createdAt: new Date().toISOString(),
      }, request);
      sendJson(response, 201, {
        account: serializeAccountForList(normalizedAccount),
        message:
          normalizedAccount.source === "app"
            ? "User account created."
            : "Employee account created.",
        authStore: "json",
      });
    } catch (error) {
      sendJson(response, 400, {
        message: error instanceof Error ? error.message : "Unable to create account.",
      });
    }
    return;
  }

  if (request.method === "PUT") {
    try {
      if (
        shouldApplyAdminRestriction &&
        !(await requireAdminRestrictionAllowed(
          request,
          response,
          requestUrl,
          "manage_employees",
          requestAdminId,
        ))
      ) {
        return;
      }

      const payload = await parseRequestBody(request);
      const accounts = await readAccounts();
      const accountId = getAccountRequestId(payload);
      const accountIndex = findAccountIndexById(accounts, accountId);

      if (accountIndex < 0) {
        throw new Error("Employee account was not found.");
      }

      const existingAccount = accounts[accountIndex];
      if (!isRecordInAdminScope(existingAccount, requestAdminId)) {
        throw new Error("Employee account was not found.");
      }
      if (String(existingAccount.source ?? "").trim().toLowerCase() !== "web") {
        throw new Error("Only employee accounts can be edited here.");
      }

      const submittedPassword = String(payload.password ?? "").trim();
      const accountUpdatedAt = new Date().toISOString();
      const passwordWasChanged = Boolean(submittedPassword);
      const storedPassword = submittedPassword
        ? await hashPassword(submittedPassword)
        : existingAccount.password;
      const mergedPayload = {
        ...existingAccount,
        ...payload,
        __accessPermissionsWereProvided:
          Object.prototype.hasOwnProperty.call(payload, "accessPermissions")
          || Object.prototype.hasOwnProperty.call(payload, "employeeAccessPermissions"),
        id: existingAccount.id,
        accountCode: existingAccount.accountCode,
        employeeId: existingAccount.employeeId,
        source: "web",
        adminId: getRecordAdminId(existingAccount, requestAdminId),
        password: storedPassword,
        passwordUpdatedAt: passwordWasChanged
          ? accountUpdatedAt
          : existingAccount.passwordUpdatedAt ?? null,
        countryCode: payload.countryCode ?? existingAccount.countryCode ?? "+63",
        eDocument: payload.eDocument ?? existingAccount.eDocument,
        faceVerified: payload.faceVerified ?? existingAccount.faceVerified,
        verifiedAt: payload.verifiedAt ?? existingAccount.verifiedAt,
        createdAt: existingAccount.createdAt,
        updatedAt: accountUpdatedAt,
      };
      const normalizedAccount = applyAdminId(
        normalizeAccountRecord(mergedPayload, existingAccount),
        getRecordAdminId(existingAccount, requestAdminId),
      );

      const applicantNameKey = normalizeAccountApplicantNameForComparison(normalizedAccount);
      const hasDuplicateApplicantName =
        Boolean(applicantNameKey) &&
        accounts.some((account, index) =>
          index !== accountIndex &&
          !isAdminAccount(account) &&
          isRecordInAdminScope(account, requestAdminId) &&
          normalizeAccountApplicantNameForComparison(account) === applicantNameKey,
        );

      if (hasDuplicateApplicantName) {
        throw new Error("This applicant is already existed.");
      }

      const hasDuplicateEmail = accounts.some(
        (account, index) =>
          index !== accountIndex &&
          !isAdminAccount(account) &&
          isRecordInAdminScope(account, requestAdminId) &&
          String(account.email ?? "").toLowerCase() === normalizedAccount.email,
      );

      if (hasDuplicateEmail) {
        throw new Error("Email address is already registered.");
      }

      const hasDuplicateMobileNumber = accounts.some(
        (account, index) =>
          index !== accountIndex &&
          !isAdminAccount(account) &&
          isRecordInAdminScope(account, requestAdminId) &&
          normalizeAccountPhoneForComparison(account.mobileNumber) ===
            normalizeAccountPhoneForComparison(normalizedAccount.mobileNumber),
      );

      if (hasDuplicateMobileNumber) {
        throw new Error("Phone number is already registered.");
      }

      accounts[accountIndex] = normalizedAccount;
      await writeAccounts(accounts);
      const accountActivityActor = createEmployeeRequestActivityActor(payload, normalizedAccount);
      const profileImageWasChanged =
        Object.prototype.hasOwnProperty.call(payload, "profileImageUrl") &&
        getActivityAccountProfileImageUrl(existingAccount) !== getActivityAccountProfileImageUrl(normalizedAccount);
      const accountDisplayName = getActivityAccountDisplayName(normalizedAccount) ||
        `${normalizedAccount.firstName ?? ""} ${normalizedAccount.lastName ?? ""}`.replace(/\s+/g, " ").trim() ||
        "Employee";
      await logActivitySafely(accountActivityActor && {
        id: createActivityLogId(),
        type: "employee-account",
        action: profileImageWasChanged ? "profile-image-updated" : "updated",
        title: profileImageWasChanged ? "Employee profile updated" : "Employee account updated",
        actor: accountActivityActor,
        adminId: requestAdminId,
        targetPermission: "employee-data",
        description: profileImageWasChanged
          ? `${accountDisplayName} updated their profile picture.`
          : `${accountDisplayName} employee account was updated.`,
        createdAt: new Date().toISOString(),
      }, request);
      sendJson(response, 200, {
        account: serializeAccountForList(normalizedAccount),
        message: "Employee account updated.",
      });
    } catch (error) {
      sendJson(response, 400, {
        message: error instanceof Error ? error.message : "Unable to update account.",
      });
    }
    return;
  }

  if (request.method === "DELETE") {
    try {
      if (
        shouldApplyAdminRestriction &&
        !(await requireAdminRestrictionAllowed(
          request,
          response,
          requestUrl,
          "manage_employees",
          requestAdminId,
        ))
      ) {
        return;
      }

      const payload = await parseRequestBody(request).catch(() => ({}));
      const accounts = await readAccounts();
      const accountId = getAccountRequestId(payload);
      const accountIndex = findAccountIndexById(accounts, accountId);

      if (accountIndex < 0) {
        throw new Error("Employee account was not found.");
      }

      if (!isRecordInAdminScope(accounts[accountIndex], requestAdminId)) {
        throw new Error("Employee account was not found.");
      }

      const [deletedAccount] = accounts.splice(accountIndex, 1);
      await writeAccounts(accounts);
      const faceAttendanceCleanup = await removeFaceAttendanceProfileForAccount(
        deletedAccount,
      ).catch((cleanupError) => {
        console.warn("Unable to remove Face Attendance profile.", cleanupError);
        return { removed: false, removedEmployeeIds: [] };
      });
      const accountActivityActor = createEmployeeRequestActivityActor(payload, deletedAccount);
      await logActivitySafely(accountActivityActor && {
        title: "Employee account deleted",
        actor: accountActivityActor,
        adminId: requestAdminId,
        targetPermission: "employee-data",
        description: `${deletedAccount.firstName ?? ""} ${deletedAccount.lastName ?? ""} employee account was deleted.`.trim(),
        createdAt: new Date().toISOString(),
      }, request);
      sendJson(response, 200, {
        account: serializeAccountForList(deletedAccount),
        faceAttendanceProfileRemoved: Boolean(faceAttendanceCleanup.removed),
        message: "Employee account deleted.",
      });
    } catch (error) {
      sendJson(response, 400, {
        message: error instanceof Error ? error.message : "Unable to delete account.",
      });
    }
    return;
  }

  sendJson(response, 405, { message: "Method not allowed." });
}

